  | { readonly ok: true; readonly value: T }
  | { readonly ok: false; readonly violations: readonly ActivityDefinitionValidationViolation[] };

const EXECUTION_MODES: readonly ActivityDefinitionExecutionMode[] = [
  "DURATION",
  "REPETITIONS",
  "TO_FAILURE",
];

/** Zones corporelles non vides et distinctes (plan §4 : « Catégorie exactement unique et Zones non vides, distinctes et valides »). */
function validateBodyZoneIds(bodyZoneIds: readonly string[]): {
  readonly ok: boolean;
  readonly code?: "REQUIRED" | "DUPLICATE";
} {
  if (bodyZoneIds.length === 0) {
    return { ok: false, code: "REQUIRED" };
  }
  const unique = new Set(bodyZoneIds);
  if (unique.size !== bodyZoneIds.length) {
    return { ok: false, code: "DUPLICATE" };
  }
  return { ok: true };
}

/** Résout une référence de Catégorie sans jamais affecter automatiquement une valeur (plan §12 : « sans affectation automatique »). */
function validateCategoryInput(
  category: CreateCategoryInput,
  violations: ActivityDefinitionValidationViolation[],
): CreateCategoryInput | undefined {
  if (category.kind === "EXISTING") {
    if (category.categoryId.trim().length === 0) {
      violations.push({ code: "REQUIRED", field: "activityDefinition.category" });
      return undefined;
    }
    return category;
  }
  const nameResult = validateCategoryName(category.name);
  const colorResult = validateCategoryColor(category.color);
  if (!nameResult.ok || !colorResult.ok) {
    violations.push({ code: "REQUIRED", field: "activityDefinition.category" });
    return undefined;
  }
  return { kind: "NEW", name: nameResult.value, color: colorResult.value };
}

/**
 * Valide et normalise une entrée de création/modification d'une
 * `ActivityDefinition`. Agrège toutes les violations déterminables (jamais
 * seulement la première) et ne lève jamais d'exception — même contrat que
 * `validateCreateSessionInput` (`@/domain/sessions/SessionDraft`).
 */
export function validateActivityDefinitionInput(
  rawInput: CreateActivityDefinitionInput,
): ActivityDefinitionValidationResult<CreateActivityDefinitionInput> {
  const violations: ActivityDefinitionValidationViolation[] = [];

  // PRE-3 : paramètres canoniques = autorité. Validés avec les bornes PRE-3,
  // puis projetés vers les scalaires historiques (jamais écrits
  // indépendamment).
  let executionParameters: ExecutionParameters | undefined;
  let input = rawInput;
  if (rawInput.executionParameters !== undefined) {
    const canonical = validateExecutionParameters(rawInput.executionParameters);
    if (canonical.ok) {
      executionParameters = canonical.value;
      const projection = projectLegacyScalars(canonical.value);
      input = {
        ...rawInput,
        executionMode: projection.executionMode,
        durationSeconds: projection.durationSeconds,
        repetitionCount: projection.repetitionCount,
        seriesCount: projection.seriesCount,
        pauseSeconds: projection.pauseSeconds,
        sideMode: projection.sideMode,
        sideRecoverySeconds: projection.sideRecoverySeconds,
      };
    } else {
      violations.push({
        code: "OUT_OF_RANGE",
        field: "activityDefinition.executionParameters",
        executionViolations: canonical.violations,
      });
    }
  }

  const nameResult = validateExerciseName(input.name);
  const name = nameResult.ok ? nameResult.value : undefined;
  if (!nameResult.ok) {
    violations.push({ code: "REQUIRED", field: "activityDefinition.name" });
  }

  const descriptionResult = validateInstruction(input.description);
  const description = descriptionResult.ok ? descriptionResult.value : null;
  if (!descriptionResult.ok) {
    violations.push({ code: "TOO_LONG", field: "activityDefinition.description" });
  }

  if (!EXECUTION_MODES.includes(input.executionMode)) {
    violations.push({ code: "UNRECOGNIZED", field: "activityDefinition.executionMode" });
  }

  let durationSeconds: number | null = null;
  let repetitionCount: number | null = null;

  if (input.executionMode === "DURATION") {
    if (input.durationSeconds === null) {
      violations.push({ code: "REQUIRED", field: "activityDefinition.durationSeconds" });
    } else {
      const durationResult = validateExerciseDurationSeconds(input.durationSeconds);
      if (durationResult.ok) {
        durationSeconds = durationResult.value;
      } else {
        violations.push({ code: "OUT_OF_RANGE", field: "activityDefinition.durationSeconds" });
      }
    }
    if (input.repetitionCount !== null) {
      violations.push({ code: "MUST_BE_ABSENT", field: "activityDefinition.repetitionCount" });
    }
  } else if (input.executionMode === "REPETITIONS") {
    if (input.repetitionCount === null) {
      violations.push({ code: "REQUIRED", field: "activityDefinition.repetitionCount" });
    } else if (executionParameters) {
      // Borne PRE-3 (1..100) déjà vérifiée par la validation canonique.
      repetitionCount = input.repetitionCount;
    } else {
      const repetitionResult = validateRepetitionCount(input.repetitionCount);
      if (repetitionResult.ok) {
        repetitionCount = repetitionResult.value;
      } else {
        violations.push({ code: "OUT_OF_RANGE", field: "activityDefinition.repetitionCount" });
      }
    }
    if (input.durationSeconds !== null) {
      violations.push({ code: "MUST_BE_ABSENT", field: "activityDefinition.durationSeconds" });
    }
  } else if (input.executionMode === "TO_FAILURE") {
    if (input.durationSeconds !== null) {
      violations.push({ code: "MUST_BE_ABSENT", field: "activityDefinition.durationSeconds" });
    }
    if (input.repetitionCount !== null) {
      violations.push({ code: "MUST_BE_ABSENT", field: "activityDefinition.repetitionCount" });
    }
  }

  const seriesResult = validateSeriesCount(input.seriesCount);
  if (!seriesResult.ok) {
    violations.push({ code: "OUT_OF_RANGE", field: "activityDefinition.seriesCount" });
  }

  const pauseResult = validatePauseSeconds(input.pauseSeconds);
  for (const item of input.media ?? []) {
    const invalidAsset = item.asset !== undefined && (item.asset.id !== item.assetId || !isValidNewMediaAsset(item.asset));
    if (item.assetId.trim().length === 0 || invalidAsset) {
      violations.push({ code: "REQUIRED", field: "activityDefinition.media" });
      break;
    }
  }
  if (!pauseResult.ok) {
    violations.push({ code: "OUT_OF_RANGE", field: "activityDefinition.pauseSeconds" });
  }

  const sideRecoveryResult = validatePauseSeconds(input.sideRecoverySeconds);
  if (!sideRecoveryResult.ok) {
    violations.push({ code: "OUT_OF_RANGE", field: "activityDefinition.sideRecoverySeconds" });
  }

  const bodyZonesResult = validateBodyZoneIds(input.bodyZoneIds);
  if (!bodyZonesResult.ok) {
    violations.push({
      code: bodyZonesResult.code === "DUPLICATE" ? "DUPLICATE" : "REQUIRED",
      field: "activityDefinition.bodyZoneIds",
    });
  }

  const category = validateCategoryInput(input.category, violations);

  if (violations.length > 0) {
    return { ok: false, violations };
  }

  return {
    ok: true,
    value: {
      name: name as string,
      description,
      executionMode: input.executionMode,
      durationSeconds,
      repetitionCount,
      seriesCount: seriesResult.ok ? seriesResult.value : input.seriesCount,
      pauseSeconds: pauseResult.ok ? pauseResult.value : input.pauseSeconds,
      category: category as CreateCategoryInput,
      bodyZoneIds: input.bodyZoneIds,
      sideMode: isSideMode(input.sideMode) ? input.sideMode : DEFAULT_SIDE_MODE,
      sideRecoverySeconds: sideRecoveryResult.ok
        ? sideRecoveryResult.value
        : input.sideRecoverySeconds,
      // V2-PRE-1 (plan §3.3/§13) : transmis tel quel, position stable =
      // ordre du tableau — jamais retrié, jamais une validation dupliquée
      // (l'intégrité référentielle de `assetId` reste à la charge du
      // Repository, même patron que `category`/`bodyZoneIds`).
      media: input.media ?? [],
      ...(executionParameters ? { executionParameters } : {}),
    },
  };
}

/**
 * Brouillon d'`ActivityDefinition` vide, destiné à l'écran de création du
 * Catalogue — mêmes valeurs par défaut que `createExerciseDraft` (Composition),
 * sans `id`/`type`/`structuralPosition` (non applicables à une définition).
 * Aucune Catégorie n'est présélectionnée (plan §12 : « sans affectation
 * automatique ») — l'appelant doit fournir une sélection explicite avant
 * `Terminer` (contrat UX `08` l.978 / `13` §4.10).
 */
export function createEmptyActivityDefinitionDraft(): Omit<CreateActivityDefinitionInput, "category"> {
  const exerciseDraft = createExerciseDraft("draft");
  return {
    name: exerciseDraft.name,
    description: exerciseDraft.instruction,
    executionMode: exerciseDraft.executionMode,
    durationSeconds: exerciseDraft.durationSeconds,
    repetitionCount: exerciseDraft.repetitionCount,
    seriesCount: exerciseDraft.seriesCount,
    pauseSeconds: exerciseDraft.pauseSeconds,
    bodyZoneIds: exerciseDraft.bodyZoneIds,
    sideMode: exerciseDraft.sideMode,
    sideRecoverySeconds: 0,
  };
}

/** Projette une `ActivityDefinition` persistée vers l'entrée éditable de l'éditeur (préremplissage exact, modification). */
export function activityDefinitionToInput(
  definition: ActivityDefinition,
): CreateActivityDefinitionInput {
  return {
    name: definition.name,
    description: definition.description,
    executionMode: definition.executionMode,
    durationSeconds: definition.durationSeconds,
    repetitionCount: definition.repetitionCount,
    seriesCount: definition.seriesCount,
    pauseSeconds: definition.pauseSeconds,
    category: { kind: "EXISTING", categoryId: definition.categoryId ?? "" },
    bodyZoneIds: definition.bodyZoneIds,
    sideMode: definition.sideMode,
    sideRecoverySeconds: definition.sideRecoverySeconds ?? 0,
    // PRE-3 : la réouverture conserve TOUS les paramètres et les liens
    // ordonnés — la modification d'un seul champ ne les perd jamais.
    ...(definition.executionParameters
      ? { executionParameters: cloneExecutionParameters(definition.executionParameters) }
      : {}),
    ...(definition.media
      ? { media: definition.media.map((item) => ({ assetId: item.assetId, asset: { ...item.asset } })) }
      : {}),
  };
}

/**
 * PRE-3 : paramètres canoniques EFFECTIFS d'une définition — le JSON
 * persisté, ou l'adaptateur conservateur d'un ancien objet (jamais le
 * Profil courant).
 */
export function resolveDefinitionExecutionParameters(definition: ActivityDefinition): ExecutionParameters {
  return (
    definition.executionParameters ??
    legacyExecutionParameters({
      executionMode: definition.executionMode,
      durationSeconds: definition.durationSeconds,
      repetitionCount: definition.repetitionCount,
      seriesCount: definition.seriesCount,
      pauseSeconds: definition.pauseSeconds,
      sideMode: definition.sideMode,
      sideRecoverySeconds: definition.sideRecoverySeconds ?? 0,
    })
  );
}

/**
 * Copie INDÉPENDANTE d'une `ActivityDefinition` vers une `SessionActivity`
 * locale (`SessionDraftExercise`) — « Une activité existante » depuis la
 * Composition (plan §4.4/§6.1). La copie porte un NOUVEL identifiant
 * (`newId`, fourni par l'appelant — ce module reste pur, sans
 * `expo-crypto`), reprend toutes les propriétés métier applicables et une
 * position structurelle par défaut (`DEFAULT_STRUCTURAL_POSITION`) — la zone
 * réelle d'insertion est décidée au moment de l'ajout par
 * `appendActivityAfterLastDisplayed` (`composition.ts`), jamais ici. Les
 * modifications ultérieures de la définition et de la copie restent
 * indépendantes : aucune référence n'est conservée vers `definition.id`.
 *
 * **V2-PRE-1 (plan §3.1/§3.2)** : `ActivityDefinition` ne porte plus aucune
 * récupération post-exercice — `postActivityRecoverySeconds` de l'occurrence
 * est donc un paramètre EXPLICITE, jamais dérivé de la définition source. Le
 * seul point d'insertion réel d'une occurrence (`SessionService`, plan §3.2)
 * le lit depuis le Profil au moment de la création ; cette fonction reste
 * pure et ne lit jamais le Profil elle-même.
 */
/**
 * Règle pure de copie de la Pause entre les côtés du Profil, appliquée par
 * `ExerciseScreen` (adaptateur Catalogue) au changement de côté d'une
 * `ActivityDefinition` (V2-PRE-2, plan §6.1/§7, T21, D-213) :
 *
 * - `Sans changement` (`UNILATERAL`) → `D→G`/`G→D` : copie la valeur
 *   COURANTE du Profil (snapshot atomique à l'activation, jamais relue
 *   ensuite) ;
 * - toute autre transition (`D→G` ↔ `G→D`, ou un retour à `Sans
 *   changement`) : la valeur stockée est CONSERVÉE inchangée — jamais
 *   réinitialisée, jamais recopiée du Profil.
 *
 * Une création unilatérale (`createEmptyActivityDefinitionDraft`) n'appelle
 * jamais cette fonction : elle reste à `0` par construction.
 */
export function sideRecoveryOnSideModeChange(
  previousSideMode: SideMode,
  nextSideMode: SideMode,
  currentSideRecoverySeconds: number,
  profileSideChangeRecoverySecondsDefault: number,
): number {
  const wasUnilateral = previousSideMode === "UNILATERAL";
  const isNowBilateral = nextSideMode !== "UNILATERAL";
  if (wasUnilateral && isNowBilateral) {
    return profileSideChangeRecoverySecondsDefault;
  }
  return currentSideRecoverySeconds;
}

export function activityDefinitionToDraftExercise(
  definition: ActivityDefinition,
  newId: string,
  postActivityRecoverySeconds: number,
): SessionDraftExercise {
  // PRE-3 (P3-18) : copie COMPLÈTE et indépendante — paramètres canoniques
  // clonés, Catégorie, médias ordonnés (mêmes fichiers physiques, nouveaux
  // liens créés à l'enregistrement de la Séance). Aucune référence partagée.
  const media: readonly DraftMediaItem[] = (definition.media ?? []).map((item) => ({
    assetId: item.assetId,
    asset: { ...item.asset },
  }));
  return {
    executionParameters: cloneExecutionParameters(resolveDefinitionExecutionParameters(definition)),
    categoryId: definition.categoryId ?? null,
    media,
    id: newId,
    type: DEFAULT_ACTIVITY_TYPE,
    structuralPosition: DEFAULT_STRUCTURAL_POSITION,
    name: definition.name,
    executionMode: definition.executionMode,
    durationSeconds: definition.durationSeconds,
    repetitionCount: definition.repetitionCount,
    seriesCount: definition.seriesCount,
    pauseSeconds: definition.pauseSeconds,
    postActivityRecoverySeconds,
    instruction: definition.description,
    bodyZoneIds: [...definition.bodyZoneIds],
    sideMode: definition.sideMode,
  };
}

import type {
  ActivityDefinition,
  CreateActivityDefinitionInput,
  UpdateActivityDefinitionInput,
} from "./ActivityDefinition";

/** Repository de persistance des `ActivityDefinition` (V2-CAT-01). Aucune suppression, archivage ni restauration ne sont exposés : hors périmètre de cette tranche. */
export interface ActivityDefinitionRepository {
  create(input: CreateActivityDefinitionInput): Promise<ActivityDefinition>;
  findById(id: string): Promise<ActivityDefinition | null>;
  /** Triée par `updatedAt DESC` — tri implicite, jamais une préférence persistée (plan §4.1). */
  listAll(): Promise<readonly ActivityDefinition[]>;
  /** `null` si l'identifiant est inconnu. */
  update(id: string, input: UpdateActivityDefinitionInput): Promise<ActivityDefinition | null>;
}

/**
 * PRE-3 — autorité unique des durées d'un Exercice (v13 §4–5, Bip v2 §2–3).
 *
 * Le calcul énumère les phases chronométrées réellement prévues (registre
 * d'événements) plutôt que d'appliquer des formules fermées : Σ(Ti+Pi) en
 * unilatéral, 2Σ(Ti+Pi)+PC en côtés successifs, 2ΣTi+ΣPi+N×PC par paire en
 * découlent par construction, de même que la substitution de la SEULE Pause
 * terminale par une Récupération positive. Durée → Ti = cible ; Répétitions
 * avec bip b>0 → Ti = Ri×b ; sinon travail inconnu (aucune convention 2 s).
 *
 * Résultat typé `exact | estimated | omitted` à l'Exercice — `omitted` ne
 * porte aucun montant, mais les contributions connues (pauses) restent
 * disponibles pour l'agrégation de Séance (`lowerBound`). Compte à rebours
 * et Fin propres sont exclus du total intrinsèque.
 */

import {
  isBilateral,
  normalizeEffective,
  seriesCountOf,
  seriesRowsOf,
  type ExecutionParameters,
  type ExecutionParametersInput,
} from "./ExecutionParameters";

export type LedgerSide = "NONE" | "RIGHT" | "LEFT";

export type LedgerEvent =
  | { readonly kind: "WORK"; readonly series: number; readonly side: LedgerSide; readonly seconds: number | null }
  | { readonly kind: "SERIES_PAUSE"; readonly series: number; readonly side: LedgerSide; readonly seconds: number }
  | { readonly kind: "SIDE_PAUSE"; readonly series: number | null; readonly seconds: number }
  | { readonly kind: "RECOVERY"; readonly seconds: number };

export type ExerciseDurationKind = "exact" | "estimated" | "omitted";

export type ExerciseDurationResult = {
  readonly kind: ExerciseDurationKind;
  /** Somme des contributions chronométrées connues (pauses, travaux calculables). */
  readonly knownSeconds: number;
  readonly events: readonly LedgerEvent[];
  /** Absent si `omitted` : aucune valeur, aucun zéro. */
  readonly seconds?: number;
};

/** Paramètres dont le mode est connu : seuls calculables. */
type CalculableParameters = ExecutionParametersInput & { readonly mode: NonNullable<ExecutionParametersInput["mode"]> };

function requireMode(parameters: ExecutionParametersInput): CalculableParameters {
  if (parameters.mode === null) {
    throw new Error("Execution mode is required to calculate a duration.");
  }
  return parameters as CalculableParameters;
}

function workSeconds(parameters: CalculableParameters, target: number | null): number | null {
  if (parameters.mode === "DURATION") {
    return target;
  }
  if (parameters.mode === "REPETITIONS" && parameters.cadenceBeepIntervalSeconds > 0 && target !== null) {
    return target * parameters.cadenceBeepIntervalSeconds;
  }
  return null;
}

/**
 * Registre des phases prévues, après normalisation effective (N=1 → par
 * côté). `recoverySeconds > 0` remplace la toute dernière Pause physique,
 * une seule fois.
 */
export function buildExecutionLedger(
  input: ExecutionParametersInput,
  recoverySeconds: number = 0,
): readonly LedgerEvent[] {
  const parameters = normalizeEffective(requireMode(input));
  const rows = seriesRowsOf(parameters);
  const events: LedgerEvent[] = [];
  const work = (index: number, side: LedgerSide) =>
    events.push({ kind: "WORK", series: index + 1, side, seconds: workSeconds(parameters, rows[index]!.target) });
  const pause = (index: number, side: LedgerSide) =>
    events.push({ kind: "SERIES_PAUSE", series: index + 1, side, seconds: rows[index]!.pauseSeconds });

  if (!isBilateral(parameters.sideMode)) {
    rows.forEach((_, index) => {
      work(index, "NONE");
      pause(index, "NONE");
    });
  } else {
    const sides: readonly LedgerSide[] = parameters.sideMode === "RIGHT_LEFT" ? ["RIGHT", "LEFT"] : ["LEFT", "RIGHT"];
    if (parameters.sideOrder === "BY_SIDE") {
      sides.forEach((side, sideIndex) => {
        if (sideIndex > 0) {
          events.push({ kind: "SIDE_PAUSE", series: null, seconds: parameters.sideRecoverySeconds });
        }
        rows.forEach((_, index) => {
          work(index, side);
          pause(index, side);
        });
      });
    } else {
      rows.forEach((_, index) => {
        work(index, sides[0]!);
        events.push({ kind: "SIDE_PAUSE", series: index + 1, seconds: parameters.sideRecoverySeconds });
        work(index, sides[1]!);
        pause(index, sides[1]!);
      });
    }
  }

  if (recoverySeconds > 0) {
    events[events.length - 1] = { kind: "RECOVERY", seconds: recoverySeconds };
  }
  return events;
}

function summarize(mode: CalculableParameters["mode"], events: readonly LedgerEvent[]): ExerciseDurationResult {
  let knownSeconds = 0;
  let unknown = false;
  for (const event of events) {
    if (event.seconds === null) {
      unknown = true;
    } else {
      knownSeconds += event.seconds;
    }
  }
  const kind: ExerciseDurationKind = unknown ? "omitted" : mode === "REPETITIONS" ? "estimated" : "exact";
  return unknown ? { kind, knownSeconds, events } : { kind, knownSeconds, events, seconds: knownSeconds };
}

/** Total intrinsèque d'un Exercice (hors R, hors Compte à rebours/Fin). */
export function computeIntrinsicDuration(parameters: ExecutionParametersInput): ExerciseDurationResult {
  return summarize(requireMode(parameters).mode, buildExecutionLedger(parameters));
}

/** Durée d'occurrence : To = T − PN + R si R > 0, sinon To = T. */
export function computeOccurrenceDuration(
  parameters: ExecutionParametersInput,
  recoverySeconds: number,
): ExerciseDurationResult {
  return summarize(requireMode(parameters).mode, buildExecutionLedger(parameters, recoverySeconds));
}

/** Vrai si le mode est connu (aucun calcul n'est possible sur un mode « — »). */
export function isCalculable(parameters: ExecutionParametersInput): parameters is CalculableParameters {
  return parameters.mode !== null;
}

// --- Inversion « Durée totale » (Durée uniforme seulement, v13 §5) ---------

export const INVERSION_SERIES_MIN = 1;
export const INVERSION_SERIES_MAX = 99;

/** Vrai uniquement en Durée uniforme avec une cible renseignée. */
export function isTotalDurationInvertible(parameters: ExecutionParametersInput): boolean {
  return (
    parameters.mode === "DURATION" && parameters.series.kind === "UNIFORM" && parameters.series.target !== null
  );
}

function uniformWithCount<T extends ExecutionParametersInput>(parameters: T, count: number): T {
  if (parameters.series.kind !== "UNIFORM") {
    throw new Error("Total duration inversion is reserved to uniform series.");
  }
  return { ...parameters, series: { ...parameters.series, count } };
}

/** Total intrinsèque exact pour N Séries, N=1 normalisé par côté. */
export function totalDurationForSeriesCount(parameters: ExecutionParametersInput, count: number): number {
  const result = computeIntrinsicDuration(uniformWithCount(parameters, count));
  return result.knownSeconds;
}

export type TotalDurationInversion = {
  readonly seriesCount: number;
  readonly totalSeconds: number;
  /** Vrai seulement si le total réalisé diffère du total demandé (message d'ajustement). */
  readonly adjusted: boolean;
};

/**
 * Énumère N = 1..99 (N=1 normalisé), retient le total réalisable le plus
 * proche, égalité vers le N le plus grand. Jamais N=0 ni N=100.
 */
export function invertTotalDuration(
  parameters: ExecutionParametersInput,
  requestedSeconds: number,
): TotalDurationInversion {
  if (!isTotalDurationInvertible(parameters)) {
    throw new Error("Total duration inversion is reserved to uniform Duration mode.");
  }
  let best: { seriesCount: number; totalSeconds: number; distance: number } | null = null;
  for (let count = INVERSION_SERIES_MIN; count <= INVERSION_SERIES_MAX; count += 1) {
    const totalSeconds = totalDurationForSeriesCount(parameters, count);
    const distance = Math.abs(totalSeconds - requestedSeconds);
    if (best === null || distance <= best.distance) {
      best = { seriesCount: count, totalSeconds, distance };
    }
  }
  return {
    seriesCount: best!.seriesCount,
    totalSeconds: best!.totalSeconds,
    adjusted: best!.totalSeconds !== requestedSeconds,
  };
}

/** Bornes du sélecteur de total : extrêmes réalisables (N=1 et N=99). */
export function totalDurationRange(parameters: ExecutionParametersInput): { readonly min: number; readonly max: number } {
  const values = [INVERSION_SERIES_MIN, INVERSION_SERIES_MAX].map((count) =>
    totalDurationForSeriesCount(parameters, count),
  );
  return { min: Math.min(...values), max: Math.max(...values) };
}

/**
 * Plan complet d'UNE occurrence (v13 §5, Bip v2 §3) : durée d'occurrence
 * puis Compte à rebours et Fin propres, chacun UNE seule fois pour
 * l'Exercice complet (jamais par Série ni par côté). Les métriques
 * Catalogue/Composition gardent leur périmètre structurel et n'utilisent
 * pas ce total.
 */
export function computeExercisePlanDuration(
  parameters: ExecutionParametersInput,
  recoverySeconds: number,
): ExerciseDurationResult {
  const occurrence = computeOccurrenceDuration(parameters, recoverySeconds);
  const phases = parameters.countdownSeconds + parameters.endSeconds;
  const knownSeconds = occurrence.knownSeconds + phases;
  return occurrence.seconds === undefined
    ? { ...occurrence, knownSeconds }
    : { ...occurrence, knownSeconds, seconds: knownSeconds };
}

// --- Agrégation de Séance (Bip v2 §2) --------------------------------------

export type SessionDurationKind = "exact" | "estimated" | "lowerBound";

export type SessionDurationResult = {
  readonly kind: SessionDurationKind;
  readonly seconds: number;
};

export type SessionDurationContribution = {
  readonly result: ExerciseDurationResult;
  /** Nombre de passages (répétitions du Circuit pour la zone IN_TOUR, 1 sinon). */
  readonly multiplicity: number;
};

/**
 * Total de Séance : exact si tout est exact ; ≈ si au moins une estimation
 * et aucun inconnu ; ≥ (contributions connues) si au moins un inconnu. Les
 * pauses connues d'un Exercice `omitted` sont incluses, jamais un travail
 * inventé.
 */
export function aggregateSessionDuration(
  contributions: readonly SessionDurationContribution[],
): SessionDurationResult {
  let seconds = 0;
  let estimated = false;
  let unknown = false;
  for (const { result, multiplicity } of contributions) {
    seconds += result.knownSeconds * multiplicity;
    if (multiplicity > 0) {
      estimated = estimated || result.kind === "estimated";
      unknown = unknown || result.kind === "omitted";
    }
  }
  return { kind: unknown ? "lowerBound" : estimated ? "estimated" : "exact", seconds };
}

export type { ExecutionParameters };
export { seriesCountOf };

/**
 * PRE-3 — représentation canonique versionnée des paramètres d'exécution
 * d'un Exercice (`SPECIFICATION-PARAMETRES-MODALE-v13.md`, Bip v2,
 * `schema-et-ecritures.md` §« Représentation canonique »).
 *
 * Une seule source de vérité pour la définition Catalogue ET l'occurrence de
 * Séance : le mode, l'état uniforme/variable EXPLICITE (jamais déduit de
 * l'égalité des valeurs), N par côté, la collection ordonnée cible/Pause,
 * la direction, l'ordre des côtés, la Pause entre les côtés, le bip commun,
 * le Compte à rebours et la Fin propres. La Récupération (R) n'en fait
 * JAMAIS partie : elle reste portée par l'occurrence.
 *
 * Fonctions pures — sans React, SQLite, Expo, Profil implicite ni horloge.
 * Les scalaires historiques (`durationSeconds`, `seriesCount`…) ne sont que
 * des PROJECTIONS dérivées de cette représentation (`projectLegacyScalars`),
 * jamais une seconde écriture indépendante.
 */

import type { ExerciseExecutionMode } from "@/domain/sessions/Session";
import { isSideMode, type SideMode } from "@/domain/sessions/sideMode";

export const EXECUTION_PARAMETERS_VERSION = 1 as const;

export type ExecutionMode = ExerciseExecutionMode;
export type SideOrder = "BY_SIDE" | "BY_SERIES";

export const EXECUTION_MODES: readonly ExecutionMode[] = ["DURATION", "REPETITIONS", "TO_FAILURE"];
export const SIDE_ORDERS: readonly SideOrder[] = ["BY_SIDE", "BY_SERIES"];

/** Bornes PRE-3 (v13 §6, Bip v2 §1) — appliquées aux NOUVELLES saisies ; une ancienne valeur hors bornes reste lue sans clamp. */
export const EXECUTION_BOUNDS = {
  seriesCount: { min: 1, max: 99 },
  durationTarget: { min: 1, max: 5999 },
  repetitionTarget: { min: 1, max: 100 },
  pauseSeconds: { min: 0, max: 300 },
  sideRecoverySeconds: { min: 0, max: 300 },
  cadenceBeepIntervalSeconds: { min: 0, max: 10 },
  countdownSeconds: { min: 0, max: 60 },
  endSeconds: { min: 0, max: 60 },
} as const;

/** Une Série : cible du mode (secondes Durée, nombre Répétitions, `null` À l'échec) et sa Pause après Série. */
export type SeriesRow = {
  readonly target: number | null;
  readonly pauseSeconds: number;
};

export type UniformSeries = {
  readonly kind: "UNIFORM";
  readonly count: number;
  readonly target: number | null;
  readonly pauseSeconds: number;
};

/** État variable explicite : la longueur de `rows` est N. Aucune valeur commune concurrente. */
export type VariableSeries = {
  readonly kind: "VARIABLE";
  readonly rows: readonly SeriesRow[];
};

export type ExecutionSeries = UniformSeries | VariableSeries;

/** Paramètres persistables, complets et valides. */
export type ExecutionParameters = {
  readonly version: typeof EXECUTION_PARAMETERS_VERSION;
  readonly mode: ExecutionMode;
  readonly series: ExecutionSeries;
  readonly sideMode: SideMode;
  readonly sideOrder: SideOrder;
  readonly sideRecoverySeconds: number;
  readonly cadenceBeepIntervalSeconds: number;
  readonly countdownSeconds: number;
  readonly endSeconds: number;
};

/**
 * Brouillon de paramètres porté par le parent (éditeur) : identique à
 * `ExecutionParameters` mais le mode et le côté peuvent rester non renseignés
 * (« — », v13 §6 « Création : mode/durée/côté non renseignés »). Jamais
 * persisté tel quel : `validateExecutionParameters` le transforme.
 */
export type ExecutionParametersInput = Omit<ExecutionParameters, "mode" | "sideMode"> & {
  readonly mode: ExecutionMode | null;
  readonly sideMode: SideMode | null;
};

export type ExecutionParametersField =
  | "version"
  | "mode"
  | "seriesCount"
  | "target"
  | "pauseSeconds"
  | "sideMode"
  | "sideOrder"
  | "sideRecoverySeconds"
  | "cadenceBeepIntervalSeconds"
  | "countdownSeconds"
  | "endSeconds";

export type ExecutionParametersViolation = {
  readonly code: "REQUIRED" | "OUT_OF_RANGE" | "NOT_INTEGER" | "UNRECOGNIZED" | "MUST_BE_ABSENT";
  readonly field: ExecutionParametersField;
  /** Rang 1-indexé de la Série concernée, pour les messages « Série n » (v13 §6). */
  readonly seriesNumber?: number;
  readonly details?: { readonly min: number; readonly max: number };
};

export type ExecutionParametersResult =
  | { readonly ok: true; readonly value: ExecutionParameters }
  | { readonly ok: false; readonly violations: readonly ExecutionParametersViolation[] };

/** Erreur de DONNÉES persistées (JSON corrompu, version inconnue) — jamais convertie silencieusement en scalaires. */
export class ExecutionParametersDataError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ExecutionParametersDataError";
  }
}

export function seriesCountOf(parameters: { readonly series: ExecutionSeries }): number {
  return parameters.series.kind === "UNIFORM" ? parameters.series.count : parameters.series.rows.length;
}

/** Lignes effectives dans l'ordre courant (l'uniforme est développé en N lignes identiques). */
export function seriesRowsOf(parameters: { readonly series: ExecutionSeries }): readonly SeriesRow[] {
  const { series } = parameters;
  if (series.kind === "VARIABLE") {
    return series.rows;
  }
  return Array.from({ length: series.count }, () => ({
    target: series.target,
    pauseSeconds: series.pauseSeconds,
  }));
}

export function isBilateral(sideMode: SideMode | null): boolean {
  return sideMode === "RIGHT_LEFT" || sideMode === "LEFT_RIGHT";
}

/**
 * Normalisation EFFECTIVE (v13 §3, arbitrage N=1) : à N=1 l'état est
 * uniforme sur la première ligne courante et l'ordre des côtés est « Un côté
 * après l'autre », dès le brouillon et son calcul. À l'échec ne porte aucune
 * cible numérique. Les réserves temporaires du brouillon ne sont jamais ici.
 */
export function normalizeEffective<T extends ExecutionParametersInput>(parameters: T): T {
  const count = seriesCountOf(parameters);
  const failure = parameters.mode === "TO_FAILURE";
  let series = parameters.series;
  if (count === 1 && series.kind === "VARIABLE") {
    const first = series.rows[0]!;
    series = { kind: "UNIFORM", count: 1, target: first.target, pauseSeconds: first.pauseSeconds };
  }
  if (failure) {
    series =
      series.kind === "UNIFORM"
        ? { ...series, target: null }
        : { kind: "VARIABLE", rows: series.rows.map((row) => ({ ...row, target: null })) };
  }
  return {
    ...parameters,
    series,
    sideOrder: count === 1 ? "BY_SIDE" : parameters.sideOrder,
  };
}

function checkInteger(
  value: unknown,
  field: ExecutionParametersField,
  bounds: { readonly min: number; readonly max: number },
  violations: ExecutionParametersViolation[],
  seriesNumber?: number,
): boolean {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    violations.push({ code: "REQUIRED", field, ...(seriesNumber ? { seriesNumber } : {}) });
    return false;
  }
  if (!Number.isInteger(value)) {
    violations.push({ code: "NOT_INTEGER", field, ...(seriesNumber ? { seriesNumber } : {}) });
    return false;
  }
  if (value < bounds.min || value > bounds.max) {
    violations.push({
      code: "OUT_OF_RANGE",
      field,
      details: { min: bounds.min, max: bounds.max },
      ...(seriesNumber ? { seriesNumber } : {}),
    });
    return false;
  }
  return true;
}

function targetBounds(mode: ExecutionMode) {
  return mode === "DURATION" ? EXECUTION_BOUNDS.durationTarget : EXECUTION_BOUNDS.repetitionTarget;
}

/**
 * Seule validation des nouveaux paramètres (P3-04/bounds) : agrège TOUTES
 * les violations, identifie le champ et la Série, ne lève jamais. Un mode ou
 * une cible active non renseignée est une erreur (« incomplet »), jamais un
 * zéro ni un résultat temporel omis. Un côté non renseigné est normalisé
 * « Sans changement » (v13 §6). Retourne la valeur EFFECTIVE normalisée.
 */
export function validateExecutionParameters(input: ExecutionParametersInput): ExecutionParametersResult {
  const violations: ExecutionParametersViolation[] = [];

  if (input.version !== EXECUTION_PARAMETERS_VERSION) {
    violations.push({ code: "UNRECOGNIZED", field: "version" });
  }
  const mode = input.mode;
  if (mode === null) {
    violations.push({ code: "REQUIRED", field: "mode" });
  } else if (!EXECUTION_MODES.includes(mode)) {
    violations.push({ code: "UNRECOGNIZED", field: "mode" });
  }
  const sideMode = input.sideMode ?? "UNILATERAL";
  if (!isSideMode(sideMode)) {
    violations.push({ code: "UNRECOGNIZED", field: "sideMode" });
  }
  if (!SIDE_ORDERS.includes(input.sideOrder)) {
    violations.push({ code: "UNRECOGNIZED", field: "sideOrder" });
  }

  const count = seriesCountOf(input);
  checkInteger(count, "seriesCount", EXECUTION_BOUNDS.seriesCount, violations);
  const rows = seriesRowsOf(input);
  const uniform = input.series.kind === "UNIFORM";
  rows.forEach((row, index) => {
    // En uniforme, une seule cible/Pause commune : ne la signaler qu'une fois.
    if (uniform && index > 0) {
      return;
    }
    const seriesNumber = uniform ? undefined : index + 1;
    if (mode === "TO_FAILURE") {
      if (row.target !== null) {
        violations.push({ code: "MUST_BE_ABSENT", field: "target", ...(seriesNumber ? { seriesNumber } : {}) });
      }
    } else if (mode === "DURATION" || mode === "REPETITIONS") {
      if (row.target === null) {
        violations.push({ code: "REQUIRED", field: "target", ...(seriesNumber ? { seriesNumber } : {}) });
      } else {
        checkInteger(row.target, "target", targetBounds(mode), violations, seriesNumber);
      }
    }
    checkInteger(row.pauseSeconds, "pauseSeconds", EXECUTION_BOUNDS.pauseSeconds, violations, seriesNumber);
  });

  checkInteger(input.sideRecoverySeconds, "sideRecoverySeconds", EXECUTION_BOUNDS.sideRecoverySeconds, violations);
  checkInteger(
    input.cadenceBeepIntervalSeconds,
    "cadenceBeepIntervalSeconds",
    EXECUTION_BOUNDS.cadenceBeepIntervalSeconds,
    violations,
  );
  checkInteger(input.countdownSeconds, "countdownSeconds", EXECUTION_BOUNDS.countdownSeconds, violations);
  checkInteger(input.endSeconds, "endSeconds", EXECUTION_BOUNDS.endSeconds, violations);

  if (violations.length > 0) {
    return { ok: false, violations };
  }
  const normalized = normalizeEffective({ ...input, sideMode });
  return { ok: true, value: { ...normalized, mode: mode as ExecutionMode, sideMode } };
}

/** Sérialisation canonique : ordre de clés fixe, aucune phrase, aucun total, aucun segment. */
export function serializeExecutionParameters(parameters: ExecutionParameters): string {
  const series =
    parameters.series.kind === "UNIFORM"
      ? {
          kind: "UNIFORM",
          count: parameters.series.count,
          target: parameters.series.target,
          pauseSeconds: parameters.series.pauseSeconds,
        }
      : {
          kind: "VARIABLE",
          rows: parameters.series.rows.map((row) => ({ target: row.target, pauseSeconds: row.pauseSeconds })),
        };
  return JSON.stringify({
    version: parameters.version,
    mode: parameters.mode,
    series,
    sideMode: parameters.sideMode,
    sideOrder: parameters.sideOrder,
    sideRecoverySeconds: parameters.sideRecoverySeconds,
    cadenceBeepIntervalSeconds: parameters.cadenceBeepIntervalSeconds,
    countdownSeconds: parameters.countdownSeconds,
    endSeconds: parameters.endSeconds,
  });
}

function isNonNegativeInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) && value >= 0;
}

function parseRow(value: unknown, mode: ExecutionMode): SeriesRow {
  if (typeof value !== "object" || value === null) {
    throw new ExecutionParametersDataError("Malformed series row.");
  }
  const row = value as { target?: unknown; pauseSeconds?: unknown };
  const target = row.target === null ? null : row.target;
  if (target !== null && !isNonNegativeInteger(target)) {
    throw new ExecutionParametersDataError("Malformed series target.");
  }
  if (mode === "TO_FAILURE" ? target !== null : target === null) {
    throw new ExecutionParametersDataError("Series target inconsistent with mode.");
  }
  if (!isNonNegativeInteger(row.pauseSeconds)) {
    throw new ExecutionParametersDataError("Malformed series pause.");
  }
  return { target, pauseSeconds: row.pauseSeconds };
}

/**
 * Lecture d'un JSON persisté. Corrompu ou version inconnue → erreur de
 * données explicite (P3-17/corrupt-version), JAMAIS un repli sur les
 * scalaires. Les bornes PRE-3 ne sont pas réappliquées : une donnée écrite
 * valide reste lisible telle quelle, sans clamp.
 */
export function parseExecutionParameters(json: string): ExecutionParameters {
  let raw: unknown;
  try {
    raw = JSON.parse(json);
  } catch {
    throw new ExecutionParametersDataError("Execution parameters JSON is malformed.");
  }
  if (typeof raw !== "object" || raw === null) {
    throw new ExecutionParametersDataError("Execution parameters JSON is malformed.");
  }
  const value = raw as Record<string, unknown>;
  if (value.version !== EXECUTION_PARAMETERS_VERSION) {
    throw new ExecutionParametersDataError(`Unknown execution parameters version: ${String(value.version)}.`);
  }
  const mode = value.mode as ExecutionMode;
  if (!EXECUTION_MODES.includes(mode)) {
    throw new ExecutionParametersDataError("Unknown execution mode.");
  }
  if (!isSideMode(value.sideMode) || !SIDE_ORDERS.includes(value.sideOrder as SideOrder)) {
    throw new ExecutionParametersDataError("Unknown side mode or order.");
  }
  for (const key of ["sideRecoverySeconds", "cadenceBeepIntervalSeconds", "countdownSeconds", "endSeconds"]) {
    if (!isNonNegativeInteger(value[key])) {
      throw new ExecutionParametersDataError(`Malformed ${key}.`);
    }
  }
  const seriesValue = value.series as Record<string, unknown> | null;
  if (typeof seriesValue !== "object" || seriesValue === null) {
    throw new ExecutionParametersDataError("Malformed series.");
  }
  let series: ExecutionSeries;
  if (seriesValue.kind === "UNIFORM") {
    if (!isNonNegativeInteger(seriesValue.count) || seriesValue.count < 1) {
      throw new ExecutionParametersDataError("Malformed series count.");
    }
    const row = parseRow({ target: seriesValue.target, pauseSeconds: seriesValue.pauseSeconds }, mode);
    series = { kind: "UNIFORM", count: seriesValue.count, target: row.target, pauseSeconds: row.pauseSeconds };
  } else if (seriesValue.kind === "VARIABLE" && Array.isArray(seriesValue.rows) && seriesValue.rows.length >= 1) {
    series = { kind: "VARIABLE", rows: seriesValue.rows.map((row) => parseRow(row, mode)) };
  } else {
    throw new ExecutionParametersDataError("Unknown series kind.");
  }
  return {
    version: EXECUTION_PARAMETERS_VERSION,
    mode,
    series,
    sideMode: value.sideMode as SideMode,
    sideOrder: value.sideOrder as SideOrder,
    sideRecoverySeconds: value.sideRecoverySeconds as number,
    cadenceBeepIntervalSeconds: value.cadenceBeepIntervalSeconds as number,
    countdownSeconds: value.countdownSeconds as number,
    endSeconds: value.endSeconds as number,
  };
}

/** Scalaires historiques d'un objet antérieur à PRE-3. */
export type LegacyExecutionScalars = {
  readonly executionMode: ExecutionMode | null;
  readonly durationSeconds: number | null;
  readonly repetitionCount: number | null;
  readonly seriesCount: number | null;
  readonly pauseSeconds: number;
  readonly sideMode?: SideMode;
  /** Absent d'une copie de Séance historique (aucune colonne PC) : l'absence reste explicite, 0. */
  readonly sideRecoverySeconds?: number;
};

/**
 * Adaptateur conservateur d'un ancien objet sans JSON (v13 §8,
 * `schema-et-ecritures.md`) : uniforme, Un côté après l'autre, bip 0 ;
 * cibles, N, Pause et direction CONSERVÉES ; CR/Fin à la compatibilité
 * neutre 0 (proposition approuvée avec le plan) — jamais une lecture du
 * Profil courant, jamais un clamp aux nouvelles bornes.
 */
export function legacyExecutionParameters(scalars: LegacyExecutionScalars): ExecutionParameters {
  const mode: ExecutionMode = scalars.executionMode ?? "DURATION";
  const target =
    mode === "DURATION" ? scalars.durationSeconds : mode === "REPETITIONS" ? scalars.repetitionCount : null;
  return {
    version: EXECUTION_PARAMETERS_VERSION,
    mode,
    series: {
      kind: "UNIFORM",
      count: Math.max(scalars.seriesCount ?? 1, 1),
      target,
      pauseSeconds: scalars.pauseSeconds,
    },
    sideMode: scalars.sideMode ?? "UNILATERAL",
    sideOrder: "BY_SIDE",
    sideRecoverySeconds: scalars.sideRecoverySeconds ?? 0,
    cadenceBeepIntervalSeconds: 0,
    countdownSeconds: 0,
    endSeconds: 0,
  };
}

/**
 * Paramètres EFFECTIFS d'un objet (définition, occurrence, brouillon) : ses
 * paramètres canoniques s'ils existent, sinon l'adaptateur conservateur de
 * ses scalaires historiques. Seul point de résolution partagé par le calcul,
 * la phrase et l'éditeur.
 */
export function resolveExecutionParameters(
  source: LegacyExecutionScalars & { readonly executionParameters?: ExecutionParametersInput },
): ExecutionParametersInput {
  return source.executionParameters ?? legacyExecutionParameters(source);
}

export type LegacyScalarProjection = {
  readonly executionMode: ExecutionMode;
  readonly durationSeconds: number | null;
  readonly repetitionCount: number | null;
  readonly seriesCount: number;
  readonly pauseSeconds: number;
  readonly sideMode: SideMode;
  readonly sideRecoverySeconds: number;
};

/**
 * Projections d'écriture vers les colonnes historiques (CHECK SQL, anciens
 * DTO) : première cible/Pause EFFECTIVE, N, mode, direction. Jamais une
 * moyenne ni une somme ; jamais relues comme source quand le JSON existe.
 */
export function projectLegacyScalars(parameters: ExecutionParameters): LegacyScalarProjection {
  const effective = normalizeEffective(parameters);
  const first = seriesRowsOf(effective)[0]!;
  return {
    executionMode: effective.mode,
    durationSeconds: effective.mode === "DURATION" ? first.target : null,
    repetitionCount: effective.mode === "REPETITIONS" ? first.target : null,
    seriesCount: seriesCountOf(effective),
    pauseSeconds: first.pauseSeconds,
    sideMode: effective.sideMode,
    sideRecoverySeconds: effective.sideRecoverySeconds,
  };
}

/** Défauts Profil copiés au moment réel de la création (P3-10) — jamais relus ensuite. */
export type ExecutionProfileDefaults = {
  readonly countdownSeconds: number;
  readonly endSeconds: number;
};

/**
 * Brouillon de création (v13 §6) : mode et côté non renseignés, Série 1,
 * Pause 0 s, bip 0 ; CR/Fin copiés du Profil. Aucune cible inventée.
 */
export function createEmptyExecutionParameters(defaults: ExecutionProfileDefaults): ExecutionParametersInput {
  return {
    version: EXECUTION_PARAMETERS_VERSION,
    mode: null,
    series: { kind: "UNIFORM", count: 1, target: null, pauseSeconds: 0 },
    sideMode: null,
    sideOrder: "BY_SIDE",
    sideRecoverySeconds: 0,
    cadenceBeepIntervalSeconds: 0,
    countdownSeconds: defaults.countdownSeconds,
    endSeconds: defaults.endSeconds,
  };
}

/** Comparaison structurelle exacte (garde d'abandon, copie, égalité de brouillon). */
export function executionParametersEqual(
  a: ExecutionParametersInput | null | undefined,
  b: ExecutionParametersInput | null | undefined,
): boolean {
  if (!a || !b) {
    return !a && !b;
  }
  if (
    a.version !== b.version ||
    a.mode !== b.mode ||
    a.sideMode !== b.sideMode ||
    a.sideOrder !== b.sideOrder ||
    a.sideRecoverySeconds !== b.sideRecoverySeconds ||
    a.cadenceBeepIntervalSeconds !== b.cadenceBeepIntervalSeconds ||
    a.countdownSeconds !== b.countdownSeconds ||
    a.endSeconds !== b.endSeconds ||
    a.series.kind !== b.series.kind
  ) {
    return false;
  }
  if (a.series.kind === "UNIFORM" && b.series.kind === "UNIFORM") {
    return (
      a.series.count === b.series.count &&
      a.series.target === b.series.target &&
      a.series.pauseSeconds === b.series.pauseSeconds
    );
  }
  const rowsA = seriesRowsOf(a);
  const rowsB = seriesRowsOf(b);
  return (
    rowsA.length === rowsB.length &&
    rowsA.every((row, index) => row.target === rowsB[index]!.target && row.pauseSeconds === rowsB[index]!.pauseSeconds)
  );
}

/** Copie profonde immuable : aucune référence partagée entre une définition et sa copie. */
export function cloneExecutionParameters<T extends ExecutionParametersInput>(parameters: T): T {
  return {
    ...parameters,
    series:
      parameters.series.kind === "UNIFORM"
        ? { ...parameters.series }
        : { kind: "VARIABLE", rows: parameters.series.rows.map((row) => ({ ...row })) },
  };
}

/**
 * PRE-3 — machine de brouillon PURE de la feuille Paramètres (v13 §3,
 * `perimetre-et-couverture.md` §5).
 *
 * Ouvrir la feuille copie les paramètres du parent dans un sous-brouillon
 * isolé ; ✕/retour système l'abandonne simplement (le parent n'a jamais été
 * touché) ; ✓ (`commitSheetDraft`) produit atomiquement les paramètres
 * EFFECTIFS valides à appliquer au parent, sans aucune persistance. Les
 * réserves (lignes retirées par réduction de N, dernier tableau variable,
 * cibles par mode, ordre des côtés demandé à N≥2) sont volatiles : elles
 * n'existent que pendant cette ouverture et ne sont jamais transmises.
 *
 * Correction revue 1 (REV-01) : chaque ligne (active, retirée ou réservée
 * dans le dernier tableau variable) et la valeur uniforme portent une
 * IDENTITÉ volatile ; leurs cibles sont mémorisées PAR MODE et par identité.
 * Une réserve créée dans un mode ne fournit donc jamais de cible active
 * dans un autre mode (« — », jamais une conversion), quel que soit le
 * chemin (variable ↔ uniforme, N, déplacement, À l'échec) ; revenir au mode
 * précédent avant ✓ restaure ses dernières cibles.
 */

import {
  cloneExecutionParameters,
  EXECUTION_BOUNDS,
  normalizeEffective,
  seriesCountOf,
  seriesRowsOf,
  validateExecutionParameters,
  type ExecutionMode,
  type ExecutionParameters,
  type ExecutionParametersInput,
  type ExecutionParametersViolation,
  type SeriesRow,
  type SideOrder,
} from "./ExecutionParameters";
import { invertTotalDuration, isTotalDurationInvertible, type TotalDurationInversion } from "./executionCalculations";
import type { SideMode } from "@/domain/sessions/sideMode";

/** Cibles mémorisées d'une identité de ligne, par mode visité pendant l'ouverture. */
type TargetsByMode = Readonly<Partial<Record<ExecutionMode, number | null>>>;

export type ExecutionSheetDraft = {
  readonly mode: ExecutionMode | null;
  /** N demandé (par côté). */
  readonly count: number;
  /** État variable DEMANDÉ — l'état effectif est uniforme à N=1. */
  readonly variable: boolean;
  /** Cible/Pause uniformes communes (cible du mode courant). */
  readonly uniform: SeriesRow;
  /** Lignes variables actives (longueur N quand `variable`), cibles du mode courant. */
  readonly rows: readonly SeriesRow[];
  /** Lignes retirées par une réduction de N, dans leur ordre relatif d'origine. */
  readonly hiddenRows: readonly SeriesRow[];
  /** Dernier tableau variable, restitué à la réactivation avant ✓. */
  readonly savedVariableRows: readonly SeriesRow[] | null;
  /** Identités volatiles alignées sur `rows`, `hiddenRows` et `savedVariableRows`. */
  readonly rowIds: readonly number[];
  readonly hiddenIds: readonly number[];
  readonly savedIds: readonly number[] | null;
  readonly uniformId: number;
  /** Cibles par identité et par mode (le mode courant est relu des lignes elles-mêmes). */
  readonly targetsById: Readonly<Record<number, TargetsByMode>>;
  readonly nextId: number;
  readonly sideMode: SideMode | null;
  /** Ordre DEMANDÉ — l'ordre effectif est « Un côté après l'autre » à N=1. */
  readonly sideOrder: SideOrder;
  readonly sideRecoverySeconds: number;
  readonly cadenceBeepIntervalSeconds: number;
  readonly countdownSeconds: number;
  readonly endSeconds: number;
};

/** Copie des paramètres du parent à l'ouverture — aucune réserve héritée. */
export function openSheetDraft(parent: ExecutionParametersInput): ExecutionSheetDraft {
  const parameters = cloneExecutionParameters(parent);
  const rows = seriesRowsOf(parameters).map((row) => ({ ...row }));
  const variable = parameters.series.kind === "VARIABLE";
  const activeRows = variable ? rows : [];
  const rowIds = activeRows.map((_, index) => index + 1);
  const uniformId = rowIds.length + 1;
  const targetsById: Record<number, TargetsByMode> = {};
  const uniform = { target: rows[0]?.target ?? null, pauseSeconds: rows[0]?.pauseSeconds ?? 0 };
  if (parameters.mode !== null) {
    activeRows.forEach((row, index) => (targetsById[rowIds[index]!] = { [parameters.mode!]: row.target }));
    targetsById[uniformId] = { [parameters.mode]: uniform.target };
  }
  return {
    mode: parameters.mode,
    count: seriesCountOf(parameters),
    variable,
    uniform,
    rows: activeRows,
    hiddenRows: [],
    savedVariableRows: null,
    rowIds,
    hiddenIds: [],
    savedIds: null,
    uniformId,
    targetsById,
    nextId: uniformId + 1,
    sideMode: parameters.sideMode,
    sideOrder: parameters.sideOrder,
    sideRecoverySeconds: parameters.sideRecoverySeconds,
    cadenceBeepIntervalSeconds: parameters.cadenceBeepIntervalSeconds,
    countdownSeconds: parameters.countdownSeconds,
    endSeconds: parameters.endSeconds,
  };
}

/** Lignes sans propriété volatile (jamais d'identité transmise au parent). */
const plain = (row: SeriesRow): SeriesRow => ({ target: row.target, pauseSeconds: row.pauseSeconds });

/** Paramètres DEMANDÉS (avant normalisation N=1), état variable/ordre compris. */
function requestedParameters(draft: ExecutionSheetDraft): ExecutionParametersInput {
  return {
    version: 1,
    mode: draft.mode,
    series: draft.variable
      ? { kind: "VARIABLE", rows: draft.rows.map(plain) }
      : { kind: "UNIFORM", count: draft.count, target: draft.uniform.target, pauseSeconds: draft.uniform.pauseSeconds },
    sideMode: draft.sideMode,
    sideOrder: draft.sideOrder,
    sideRecoverySeconds: draft.sideRecoverySeconds,
    cadenceBeepIntervalSeconds: draft.cadenceBeepIntervalSeconds,
    countdownSeconds: draft.countdownSeconds,
    endSeconds: draft.endSeconds,
  };
}

/**
 * Paramètres EFFECTIFS du brouillon, utilisés pour le calcul, la phrase et
 * l'affichage : à N=1, uniforme sur la première ligne courante et « Un côté
 * après l'autre », immédiatement (P3-08/immediate-N1).
 */
export function effectiveParameters(draft: ExecutionSheetDraft): ExecutionParametersInput {
  return normalizeEffective(requestedParameters(draft));
}

/** Contrôles « sans effet » à N=1 : interrupteur variable et Ordre des côtés grisés. */
export function isSingleSeries(draft: ExecutionSheetDraft): boolean {
  return draft.count === 1;
}

function clampCount(count: number): number {
  return Math.min(Math.max(Math.trunc(count), EXECUTION_BOUNDS.seriesCount.min), EXECUTION_BOUNDS.seriesCount.max);
}

/**
 * Mémorise, pour le mode courant, la cible affichée de chaque identité
 * (lignes actives, retirées, réservées, uniforme) avant une transition.
 */
function rememberCurrentTargets(draft: ExecutionSheetDraft): Record<number, TargetsByMode> {
  const targetsById: Record<number, TargetsByMode> = { ...draft.targetsById };
  if (draft.mode === null || draft.mode === "TO_FAILURE") {
    return targetsById;
  }
  const mode = draft.mode;
  const remember = (id: number, target: number | null) => {
    targetsById[id] = { ...targetsById[id], [mode]: target };
  };
  draft.rows.forEach((row, index) => remember(draft.rowIds[index]!, row.target));
  draft.hiddenRows.forEach((row, index) => remember(draft.hiddenIds[index]!, row.target));
  (draft.savedVariableRows ?? []).forEach((row, index) => remember(draft.savedIds![index]!, row.target));
  remember(draft.uniformId, draft.uniform.target);
  return targetsById;
}

/** Nouvelle identité copiant les cibles mémorisées de `sourceId` (copie de ligne). */
function cloneIdentity(
  targetsById: Record<number, TargetsByMode>,
  sourceId: number,
  nextId: number,
): { readonly id: number; readonly nextId: number } {
  targetsById[nextId] = { ...targetsById[sourceId] };
  return { id: nextId, nextId: nextId + 1 };
}

/**
 * Change N (P3-06) : réduire retire les dernières lignes actives et les
 * conserve dans leur ordre relatif ; remonter restaure d'abord ces lignes,
 * puis clone la dernière ligne active. Uniforme : seul N change.
 */
export function setSeriesCount(draft: ExecutionSheetDraft, requested: number): ExecutionSheetDraft {
  const count = clampCount(requested);
  if (!draft.variable) {
    return { ...draft, count };
  }
  const targetsById = rememberCurrentTargets(draft);
  let nextId = draft.nextId;
  let rows = [...draft.rows];
  let rowIds = [...draft.rowIds];
  let hiddenRows = [...draft.hiddenRows];
  let hiddenIds = [...draft.hiddenIds];
  if (count < rows.length) {
    hiddenRows = [...rows.slice(count), ...hiddenRows];
    hiddenIds = [...rowIds.slice(count), ...hiddenIds];
    rows = rows.slice(0, count);
    rowIds = rowIds.slice(0, count);
  } else {
    while (rows.length < count) {
      const restored = hiddenRows.shift();
      const restoredId = hiddenIds.shift();
      if (restored && restoredId !== undefined) {
        rows.push({ ...restored });
        rowIds.push(restoredId);
      } else {
        const sourceId = rowIds[rowIds.length - 1] ?? draft.uniformId;
        const clone = cloneIdentity(targetsById, sourceId, nextId);
        nextId = clone.nextId;
        rows.push({ ...(rows[rows.length - 1] ?? draft.uniform) });
        rowIds.push(clone.id);
      }
    }
  }
  return { ...draft, count, rows, rowIds, hiddenRows, hiddenIds, targetsById, nextId };
}

/**
 * Active/désactive « Séries variables » (P3-05). Activation : chaque ligne
 * copie la cible/Pause uniformes, ou restitue le dernier tableau variable de
 * cette ouverture (avec la cible MÉMORISÉE POUR LE MODE COURANT, « — » sinon).
 * Désactivation : l'uniforme reprend la PREMIÈRE ligne dans l'ordre courant.
 * Jamais déduit de l'égalité des valeurs.
 */
export function setVariable(draft: ExecutionSheetDraft, variable: boolean): ExecutionSheetDraft {
  if (variable === draft.variable) {
    return draft;
  }
  const targetsById = rememberCurrentTargets(draft);
  let nextId = draft.nextId;
  if (!variable) {
    const first = draft.rows[0] ?? draft.uniform;
    const firstId = draft.rowIds[0] ?? draft.uniformId;
    const uniform = cloneIdentity(targetsById, firstId, nextId);
    return {
      ...draft,
      variable: false,
      uniform: { ...first },
      uniformId: uniform.id,
      savedVariableRows: [...draft.rows, ...draft.hiddenRows],
      savedIds: [...draft.rowIds, ...draft.hiddenIds],
      rows: [],
      rowIds: [],
      hiddenRows: [],
      hiddenIds: [],
      targetsById,
      nextId: uniform.nextId,
    };
  }
  const rows: SeriesRow[] = [];
  const rowIds: number[] = [];
  const hiddenRows: SeriesRow[] = [];
  const hiddenIds: number[] = [];
  const saved = draft.savedVariableRows;
  if (saved && saved.length > 0) {
    saved.forEach((row, index) => {
      const target = index < draft.count;
      (target ? rows : hiddenRows).push({ ...row });
      (target ? rowIds : hiddenIds).push(draft.savedIds![index]!);
    });
    while (rows.length < draft.count) {
      const clone = cloneIdentity(targetsById, rowIds[rowIds.length - 1]!, nextId);
      nextId = clone.nextId;
      rows.push({ ...rows[rows.length - 1]! });
      rowIds.push(clone.id);
    }
  } else {
    for (let index = 0; index < draft.count; index += 1) {
      const clone = cloneIdentity(targetsById, draft.uniformId, nextId);
      nextId = clone.nextId;
      rows.push({ ...draft.uniform });
      rowIds.push(clone.id);
    }
  }
  return { ...draft, variable: true, rows, rowIds, hiddenRows, hiddenIds, targetsById, nextId };
}

/**
 * Change de mode (P3-04) : N, Pauses, bip, côtés conservés ; cibles
 * incompatibles « — » (null, jamais zéro) ; retour à un mode déjà visité
 * pendant cette ouverture → ses cibles sont restaurées, identité par
 * identité (lignes actives, retirées et réservées). Création (mode jusqu'ici
 * non renseigné) en Répétitions uniforme : cible initiale 1.
 */
export function setMode(draft: ExecutionSheetDraft, mode: ExecutionMode): ExecutionSheetDraft {
  if (mode === draft.mode) {
    return draft;
  }
  const targetsById = rememberCurrentTargets(draft);
  const targetFor = (id: number): number | null => (mode === "TO_FAILURE" ? null : (targetsById[id]?.[mode] ?? null));
  const retarget = (rows: readonly SeriesRow[], ids: readonly number[]) =>
    rows.map((row, index) => ({ ...row, target: targetFor(ids[index]!) }));
  const initialUniform = draft.mode === null && mode === "REPETITIONS" && !draft.variable ? 1 : null;
  const uniformTarget = targetsById[draft.uniformId]?.[mode] !== undefined ? targetFor(draft.uniformId) : initialUniform;
  return {
    ...draft,
    mode,
    targetsById,
    uniform: { ...draft.uniform, target: mode === "TO_FAILURE" ? null : uniformTarget },
    rows: retarget(draft.rows, draft.rowIds),
    hiddenRows: retarget(draft.hiddenRows, draft.hiddenIds),
    savedVariableRows: draft.savedVariableRows ? retarget(draft.savedVariableRows, draft.savedIds!) : null,
  };
}

/**
 * Cible/Pause uniformes. À N=1 en état variable DEMANDÉ, l'état effectif est
 * uniforme sur la première ligne : le réglage affiché modifie donc cette
 * ligne (aucun contrôle actif sans effet, REV-02), et la valeur uniforme.
 */
export function setUniformTarget(draft: ExecutionSheetDraft, target: number | null): ExecutionSheetDraft {
  const rows = draft.variable && draft.rows.length > 0 ? draft.rows.map((row, index) => (index === 0 ? { ...row, target } : row)) : draft.rows;
  return { ...draft, rows, uniform: { ...draft.uniform, target } };
}

export function setUniformPause(draft: ExecutionSheetDraft, pauseSeconds: number): ExecutionSheetDraft {
  const rows =
    draft.variable && draft.rows.length > 0 ? draft.rows.map((row, index) => (index === 0 ? { ...row, pauseSeconds } : row)) : draft.rows;
  return { ...draft, rows, uniform: { ...draft.uniform, pauseSeconds } };
}

export function setRowTarget(draft: ExecutionSheetDraft, index: number, target: number | null): ExecutionSheetDraft {
  return { ...draft, rows: draft.rows.map((row, current) => (current === index ? { ...row, target } : row)) };
}

export function setRowPause(draft: ExecutionSheetDraft, index: number, pauseSeconds: number): ExecutionSheetDraft {
  return { ...draft, rows: draft.rows.map((row, current) => (current === index ? { ...row, pauseSeconds } : row)) };
}

/**
 * Déplace une Série (P3-07) : cible, Pause et identité voyagent ensemble,
 * les lignes sont renumérotées par leur position ; la nouvelle dernière
 * ligne porte PN. Indices hors bornes : aucun changement.
 */
export function moveRow(draft: ExecutionSheetDraft, from: number, to: number): ExecutionSheetDraft {
  if (from === to || from < 0 || to < 0 || from >= draft.rows.length || to >= draft.rows.length) {
    return draft;
  }
  const rows = [...draft.rows];
  const rowIds = [...draft.rowIds];
  const [moved] = rows.splice(from, 1);
  const [movedId] = rowIds.splice(from, 1);
  rows.splice(to, 0, moved!);
  rowIds.splice(to, 0, movedId!);
  return { ...draft, rows, rowIds };
}

export function setSideMode(
  draft: ExecutionSheetDraft,
  sideMode: SideMode,
  profileSideRecoverySecondsDefault: number,
): ExecutionSheetDraft {
  const activating = (draft.sideMode === null || draft.sideMode === "UNILATERAL") && sideMode !== "UNILATERAL";
  return {
    ...draft,
    sideMode,
    // P3-10 : la Pause entre les côtés est copiée du Profil à l'activation, jamais relue ensuite.
    sideRecoverySeconds: activating ? profileSideRecoverySecondsDefault : draft.sideRecoverySeconds,
  };
}

export function setSideOrder(draft: ExecutionSheetDraft, sideOrder: SideOrder): ExecutionSheetDraft {
  return { ...draft, sideOrder };
}

export function setSideRecovery(draft: ExecutionSheetDraft, sideRecoverySeconds: number): ExecutionSheetDraft {
  return { ...draft, sideRecoverySeconds };
}

export function setCadenceBeep(draft: ExecutionSheetDraft, cadenceBeepIntervalSeconds: number): ExecutionSheetDraft {
  return { ...draft, cadenceBeepIntervalSeconds };
}

export function setCountdown(draft: ExecutionSheetDraft, countdownSeconds: number): ExecutionSheetDraft {
  return { ...draft, countdownSeconds };
}

export function setEnd(draft: ExecutionSheetDraft, endSeconds: number): ExecutionSheetDraft {
  return { ...draft, endSeconds };
}

/** Le total est éditable (roulette d'inversion) exactement quand l'état EFFECTIF est Durée uniforme renseignée. */
export function isRequestedTotalEditable(draft: ExecutionSheetDraft): boolean {
  return isTotalDurationInvertible(effectiveParameters(draft));
}

/**
 * Inversion de la Durée totale (P3-14) — réservée à la Durée uniforme
 * EFFECTIVE. Correction revue 1 (REV-02) : à N=1 depuis un tableau variable
 * (effectif uniforme sur la première ligne), l'inversion s'applique aussi ;
 * le brouillon passe en uniforme sur cette première ligne — exactement la
 * base du calcul affiché — et le tableau reste réservé (réactivation avant ✓
 * le restitue). Le total réalisé est donc toujours celui annoncé.
 */
export function applyRequestedTotal(
  draft: ExecutionSheetDraft,
  requestedSeconds: number,
): { readonly draft: ExecutionSheetDraft; readonly inversion: TotalDurationInversion } | null {
  const parameters = effectiveParameters(draft);
  if (!isTotalDurationInvertible(parameters)) {
    return null;
  }
  const inversion = invertTotalDuration(parameters, requestedSeconds);
  const uniform = draft.variable ? setVariable(draft, false) : draft;
  return { draft: { ...uniform, count: inversion.seriesCount }, inversion };
}

export type SheetCommitResult =
  | { readonly ok: true; readonly value: ExecutionParameters }
  | { readonly ok: false; readonly violations: readonly ExecutionParametersViolation[] };

/**
 * ✓ (P3-16) : valide l'état EFFECTIF (repli du tableau sans effet) ; succès
 * → paramètres normalisés à appliquer atomiquement au parent, réserves
 * abandonnées ; échec → aucune application, violations nommant la Série.
 */
export function commitSheetDraft(draft: ExecutionSheetDraft): SheetCommitResult {
  return validateExecutionParameters(effectiveParameters(draft));
}

/** Première Série incomplète (message « Série n », v13 §6), ou `null`. */
export function firstIncompleteSeries(violations: readonly ExecutionParametersViolation[]): number | null {
  const withSeries = violations.find((violation) => violation.field === "target" && violation.seriesNumber);
  return withSeries?.seriesNumber ?? null;
}

/**
 * PRE-3 — générateur pur de la phrase des paramètres d'exécution
 * (`SPECIFICATION-PHRASE-PARAMETRES-EXECUTION-v1.md`, corpus v15 de 276 cas).
 *
 * Retourne des segments ordonnés `{texte, gras}` émis DIRECTEMENT par le
 * gabarit — jamais une chaîne redécoupée a posteriori, jamais de Markdown.
 * La concaténation des `texte` restitue la phrase exacte. Le total est
 * fourni par l'autorité de calcul (`executionCalculations.ts`) ; aucun
 * montant d'exemple n'est lu. Aucune phrase ni aucun segment n'est
 * persisté : la phrase est régénérée à chaque affichage.
 *
 * Générateur francophone uniquement (décision MVP, §6 de la spécification) :
 * ordre des groupes, accords et ponctuation dépendent de la langue, ces
 * segments ne sont pas des fragments à traduire isolément.
 */

import {
  isBilateral,
  normalizeEffective,
  seriesCountOf,
  seriesRowsOf,
  type ExecutionParametersInput,
} from "./ExecutionParameters";
import { computeIntrinsicDuration, isCalculable } from "./executionCalculations";

export type PhraseSegment = {
  readonly texte: string;
  readonly gras: boolean;
};

/** « X min Y s » / « X min » / « Y s » — aucune heure, aucun zéro inutile. */
export function formatPhraseDuration(totalSeconds: number): string {
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  if (minutes > 0 && seconds > 0) {
    return `${minutes} min ${seconds} s`;
  }
  return minutes > 0 ? `${minutes} min` : `${seconds} s`;
}

class SegmentBuilder {
  private readonly segments: PhraseSegment[] = [];

  text(value: string): this {
    return this.push(value, false);
  }

  bold(value: string): this {
    return this.push(value, true);
  }

  private push(value: string, gras: boolean): this {
    if (value.length === 0) {
      return this;
    }
    const last = this.segments[this.segments.length - 1];
    if (last && last.gras === gras) {
      this.segments[this.segments.length - 1] = { texte: last.texte + value, gras };
    } else {
      this.segments.push({ texte: value, gras });
    }
    return this;
  }

  build(): readonly PhraseSegment[] {
    return this.segments;
  }
}

function seriesLabel(count: number): string {
  return count === 1 ? `${count} série` : `${count} séries`;
}

function repetitionsLabel(count: number): string {
  return count === 1 ? `${count} répétition` : `${count} répétitions`;
}

/** Énumération « a, b puis c » (gras par élément selon `boldItem`). */
function enumerate(builder: SegmentBuilder, items: readonly string[], boldItem: (index: number) => boolean): void {
  items.forEach((item, index) => {
    if (index > 0) {
      builder.text(index === items.length - 1 ? " puis " : ", ");
    }
    if (boldItem(index)) {
      builder.bold(item);
    } else {
      builder.text(item);
    }
  });
}

/**
 * Segments de la phrase descriptive d'un Exercice. `null` lorsque le mode
 * n'est pas renseigné ou qu'une cible active manque (aucune cible inventée
 * pendant un brouillon incomplet — la carte affiche alors son état vide).
 */
export function generateExecutionPhrase(input: ExecutionParametersInput): readonly PhraseSegment[] | null {
  if (!isCalculable(input)) {
    return null;
  }
  const parameters = normalizeEffective(input);
  const rows = seriesRowsOf(parameters);
  const count = seriesCountOf(parameters);
  const mode = parameters.mode;
  if (mode !== "TO_FAILURE" && rows.some((row) => row.target === null)) {
    return null;
  }
  const variable = parameters.series.kind === "VARIABLE";
  const targets = rows.map((row) => row.target as number);
  const builder = new SegmentBuilder();

  builder.bold(seriesLabel(count));

  // --- Contenu ---------------------------------------------------------------
  if (mode === "DURATION") {
    if (!variable) {
      builder.text(" de ").bold(formatPhraseDuration(targets[0]!));
    } else if (count <= 3) {
      builder.text(" de durée variable (");
      enumerate(builder, targets.map(formatPhraseDuration), () => true);
      builder.text(")");
    } else {
      builder
        .text(" variables, de ")
        .bold(formatPhraseDuration(Math.min(...targets)))
        .text(" à ")
        .bold(formatPhraseDuration(Math.max(...targets)));
    }
  } else if (mode === "REPETITIONS") {
    if (!variable) {
      builder.text(" de ").bold(repetitionsLabel(targets[0]!));
    } else if (count <= 3) {
      builder.text(" de ");
      const items = targets.map((target, index) =>
        index === targets.length - 1 ? repetitionsLabel(target) : String(target),
      );
      enumerate(builder, items, (index) => index === items.length - 1);
    } else {
      builder
        .text(` variables, de ${Math.min(...targets)} à `)
        .bold(repetitionsLabel(Math.max(...targets)));
    }
    if (parameters.cadenceBeepIntervalSeconds > 0) {
      builder.text(" cadencées toutes les ").bold(formatPhraseDuration(parameters.cadenceBeepIntervalSeconds));
    }
  } else {
    builder.text(count === 1 ? " menée jusqu’à l’échec" : " menées jusqu’à l’échec");
  }

  // --- Pause (uniforme seulement ; omise en variable, conformément aux 276 cas)
  if (!variable) {
    const pause = rows[0]!.pauseSeconds;
    if (pause > 0) {
      builder.text(", avec ").bold(formatPhraseDuration(pause)).text(" de pause après chaque série");
    } else if (count > 1) {
      builder.text(", enchaînées sans pause");
    }
  }

  // --- Côtés --------------------------------------------------------------
  if (isBilateral(parameters.sideMode)) {
    const rightFirst = parameters.sideMode === "RIGHT_LEFT";
    const first = rightFirst ? "droit" : "gauche";
    const second = rightFirst ? "gauche" : "droit";
    if (count === 1) {
      builder.text(`, en faisant le côté ${first} puis le `).bold(second);
    } else if (parameters.sideOrder === "BY_SERIES") {
      builder.text(`, en alternant le côté ${first} puis le `).bold(second).text(" à chaque série");
    } else {
      builder
        .text(", en faisant d’abord toutes les séries à ")
        .bold(rightFirst ? "droite" : "gauche")
        .text(", puis à ")
        .bold(rightFirst ? "gauche" : "droite");
    }
    if (parameters.sideRecoverySeconds > 0) {
      builder
        .text(", avec ")
        .bold(formatPhraseDuration(parameters.sideRecoverySeconds))
        .text(" de pause au changement de côté");
    }
  }

  builder.text(".");

  // --- Durée totale ---------------------------------------------------------
  const result = computeIntrinsicDuration(parameters);
  const redundant =
    mode === "DURATION" && count === 1 && !isBilateral(parameters.sideMode) && rows[0]!.pauseSeconds === 0;
  if (result.kind !== "omitted" && result.seconds !== undefined && !redundant) {
    const amount = formatPhraseDuration(result.seconds);
    builder.text(" Durée totale : ").bold(result.kind === "estimated" ? `≈ ${amount}` : amount).text(".");
  }

  return builder.build();
}

/** Texte complet (concaténation exacte des segments) — libellé accessible unique de la carte. */
export function phraseText(segments: readonly PhraseSegment[]): string {
  return segments.map((segment) => segment.texte).join("");
}

/**
 * PRE-3 — frontière de sérialisation IMMUABLE d'un Exercice (P3-18).
 *
 * Prépare les données dont la future Exécution aura besoin (paramètres
 * canoniques, Récupération de l'occurrence, médias ordonnés et leurs
 * métadonnées immuables) sans introduire de moteur, de chronomètre ni de
 * Repository d'historique. Un instantané est une copie profonde gelée :
 * aucune mutation de la définition, de l'occurrence ou du Profil ne peut
 * l'atteindre. Aucune phrase, aucun segment, aucun total dérivé n'y est
 * stocké — ils se régénèrent depuis les paramètres à l'affichage.
 */

import type { MediaAsset } from "@/domain/media/MediaAsset";

import {
  cloneExecutionParameters,
  parseExecutionParameters,
  serializeExecutionParameters,
  type ExecutionParameters,
} from "./ExecutionParameters";

export const EXERCISE_SNAPSHOT_VERSION = 1 as const;

export type ExerciseSnapshotMedia = {
  readonly position: number;
  readonly asset: MediaAsset;
};

export type ExerciseSnapshot = {
  readonly snapshotVersion: typeof EXERCISE_SNAPSHOT_VERSION;
  readonly name: string;
  readonly categoryId: string | null;
  readonly bodyZoneIds: readonly string[];
  readonly executionParameters: ExecutionParameters;
  /** Récupération explicite de l'occurrence (0 = aucune) — jamais portée par la définition. */
  readonly recoverySeconds: number;
  readonly media: readonly ExerciseSnapshotMedia[];
  /** Durée réellement réalisée, si l'instantané provient d'une exécution — jamais recalculée. */
  readonly actualDurationSeconds: number | null;
};

export type ExerciseSnapshotSource = {
  readonly name: string;
  readonly categoryId: string | null;
  readonly bodyZoneIds: readonly string[];
  readonly executionParameters: ExecutionParameters;
  readonly recoverySeconds: number;
  readonly media: readonly { readonly asset: MediaAsset }[];
  readonly actualDurationSeconds?: number | null;
};

function deepFreeze<T>(value: T): T {
  if (value !== null && typeof value === "object" && !Object.isFrozen(value)) {
    Object.freeze(value);
    for (const key of Object.keys(value as object)) {
      deepFreeze((value as Record<string, unknown>)[key]);
    }
  }
  return value;
}

/** Copie profonde gelée de la source — les médias gardent leur ordre et le même fichier physique (même `assetId`/URI). */
export function createExerciseSnapshot(source: ExerciseSnapshotSource): ExerciseSnapshot {
  return deepFreeze({
    snapshotVersion: EXERCISE_SNAPSHOT_VERSION,
    name: source.name,
    categoryId: source.categoryId,
    bodyZoneIds: [...source.bodyZoneIds],
    executionParameters: cloneExecutionParameters(source.executionParameters),
    recoverySeconds: source.recoverySeconds,
    media: source.media.map((item, position) => ({ position, asset: { ...item.asset } })),
    actualDurationSeconds: source.actualDurationSeconds ?? null,
  });
}

/** Sérialisation versionnée : paramètres canoniques, aucun champ de phrase/segment/total. */
export function serializeExerciseSnapshot(snapshot: ExerciseSnapshot): string {
  return JSON.stringify({
    snapshotVersion: snapshot.snapshotVersion,
    name: snapshot.name,
    categoryId: snapshot.categoryId,
    bodyZoneIds: snapshot.bodyZoneIds,
    executionParameters: JSON.parse(serializeExecutionParameters(snapshot.executionParameters)),
    recoverySeconds: snapshot.recoverySeconds,
    media: snapshot.media,
    actualDurationSeconds: snapshot.actualDurationSeconds,
  });
}

export class ExerciseSnapshotDataError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ExerciseSnapshotDataError";
  }
}

/**
 * Relecture d'un instantané. Les champs inconnus (par exemple une phrase
 * historique injectée) sont IGNORÉS, jamais réutilisés : la phrase se
 * régénère depuis `executionParameters` sous la grammaire courante.
 */
export function parseExerciseSnapshot(json: string): ExerciseSnapshot {
  let raw: Record<string, unknown>;
  try {
    raw = JSON.parse(json) as Record<string, unknown>;
  } catch {
    throw new ExerciseSnapshotDataError("Exercise snapshot JSON is malformed.");
  }
  if (raw === null || typeof raw !== "object" || raw.snapshotVersion !== EXERCISE_SNAPSHOT_VERSION) {
    throw new ExerciseSnapshotDataError("Unknown exercise snapshot version.");
  }
  const media = Array.isArray(raw.media) ? (raw.media as ExerciseSnapshotMedia[]) : [];
  return deepFreeze({
    snapshotVersion: EXERCISE_SNAPSHOT_VERSION,
    name: String(raw.name),
    categoryId: typeof raw.categoryId === "string" ? raw.categoryId : null,
    bodyZoneIds: Array.isArray(raw.bodyZoneIds) ? (raw.bodyZoneIds as string[]).map(String) : [],
    executionParameters: parseExecutionParameters(JSON.stringify(raw.executionParameters)),
    recoverySeconds: typeof raw.recoverySeconds === "number" ? raw.recoverySeconds : 0,
    media: media.map((item, position) => ({ position, asset: { ...item.asset } })),
    actualDurationSeconds: typeof raw.actualDurationSeconds === "number" ? raw.actualDurationSeconds : null,
  });
}

/** Point d'entrée du domaine des Activités du Catalogue (V2-CAT-01). */

export * from "./ActivityDefinition";
export * from "./ActivityDefinitionRepository";

import { normalizeName } from "@/domain/sessions/validation";

/**
 * Référentiel PERSISTANT des Zones corporelles (V2-PRE-1, plan §3.1 ;
 * V2-PRE-2, plan §6.1) : nom et état actif/retiré, sans couleur. Distinct de
 * `@/features/reference-data/bodyZones.ts` (`BODY_ZONES`), qui reste une
 * source historique de seed et de compatibilité.
 *
 * V2-PRE-2 : clé normalisée obligatoire et unique (`canonicalKey`,
 * `canonicalBodyZoneKey`) — créer un nom dont la clé normalisée correspond
 * à une entrée RETIRÉE la réactive (D2) ; un nom actif de même clé est
 * refusé comme doublon. Aucune couleur n'est jamais proposée ni stockée.
 */

export type BodyZone = {
  readonly id: string;
  readonly name: string;
  /**
   * Toujours renseignée en pratique par le Repository (`migration008`,
   * `NOT NULL` en base). Champ OPTIONNEL uniquement sur ce type LU, pour la
   * compatibilité structurelle de fixtures hors périmètre d'écriture
   * (`compositionPresentation.test.ts`, `ActivityCard.test.tsx`,
   * `scope_allow`) qui construisent encore ce type sans elle — même patron
   * que `ActivityDefinition.categoryId?`.
   */
  readonly canonicalKey?: string;
  readonly isActive: boolean;
  readonly createdAt: string;
};

/** Une Zone est disponible pour une NOUVELLE affectation si et seulement si elle est active. */
export function isBodyZoneAssignable(zone: BodyZone): boolean {
  return zone.isActive;
}

/** Sous-ensemble assignable à une NOUVELLE sélection (actives uniquement), dans l'ordre d'origine — jamais utilisé pour filtrer l'affichage d'une Zone déjà référencée par un objet existant. */
export function listAssignableBodyZones(zones: readonly BodyZone[]): readonly BodyZone[] {
  return zones.filter(isBodyZoneAssignable);
}

/** Entrée de création d'une Zone (modale de sélection Zones, `13` §4.10) — nom seul, jamais de couleur ni d'identifiant (généré par le Repository). */
export type CreateBodyZoneInput = {
  readonly name: string;
};

export type BodyZoneValidationErrorCode = "REQUIRED" | "TOO_LONG" | "DUPLICATE" | "RETIRED" | "NOT_FOUND";
export type BodyZoneValidationField = "bodyZone.name" | "bodyZone.id";
export type BodyZoneValidationViolation = {
  readonly code: BodyZoneValidationErrorCode;
  readonly field: BodyZoneValidationField;
  readonly details?: { readonly max?: number };
};
export type BodyZoneValidationResult<T> =
  | { readonly ok: true; readonly value: T }
  | { readonly ok: false; readonly violations: readonly BodyZoneValidationViolation[] };

/** Zone : `1..80` points de code (T9, matrice §5.2 ; code), distinct des bornes `≤40` d'Étiquette/Catégorie. */
export const BODY_ZONE_NAME_MAX_LENGTH = 80;

function normalizeBodyZoneName(raw: string): string {
  return normalizeName(raw);
}

/** Clé canonique de comparaison/unicité (même patron que `canonicalCategoryKey`/`canonicalLabelKey`) — jamais affichée à l'utilisateur. */
export function canonicalBodyZoneKey(raw: string): string {
  return normalizeBodyZoneName(raw)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "");
}

/** Nom d'une Zone : non vide après normalisation, au plus `BODY_ZONE_NAME_MAX_LENGTH` points de code. */
export function validateBodyZoneName(raw: string): BodyZoneValidationResult<string> {
  const normalized = normalizeBodyZoneName(raw);
  const length = Array.from(normalized).length;
  if (length < 1) {
    return { ok: false, violations: [{ code: "REQUIRED", field: "bodyZone.name" }] };
  }
  if (length > BODY_ZONE_NAME_MAX_LENGTH) {
    return {
      ok: false,
      violations: [
        { code: "TOO_LONG", field: "bodyZone.name", details: { max: BODY_ZONE_NAME_MAX_LENGTH } },
      ],
    };
  }
  return { ok: true, value: normalized };
}

import { SESSION_COLORS, type SessionColor } from "@/domain/sessions/Session";

import { fail, ok, type CategoryValidationResult } from "./errors";

/**
 * Catégorie d'Exercice (V2-PRE-1, plan §3.1) : nom, couleur, état
 * actif/retiré, affectation OBLIGATOIRE à un Exercice (D-211,
 * `08 – Conception fonctionnelle détaillée.md` l.978). La relation
 * historique Catégorie de Séance N:N est retirée du contrat cible — ce type
 * n'est plus colocalisé avec `Session` (`Session.ts` ne le référence plus),
 * la dépendance circulaire `sessions ↔ categories` qui justifiait
 * l'ancienne colocalisation n'existe donc plus.
 *
 * Une Catégorie retirée (`isActive: false`) est indisponible pour une
 * NOUVELLE affectation mais reste représentable par les Exercices qui la
 * référencent déjà (plan §3.1, même règle que `@/domain/body-zones` et
 * `@/domain/labels`).
 */

export type CategoryColor = SessionColor;
export const CATEGORY_COLORS: readonly CategoryColor[] = SESSION_COLORS;

export type Category = {
  readonly id: string;
  readonly name: string;
  readonly canonicalKey: string;
  readonly color: CategoryColor;
  readonly isPredefined: boolean;
  readonly displayOrder: number | null;
  readonly isActive: boolean;
  readonly createdAt: string;
};

/** Une Catégorie est disponible pour une NOUVELLE affectation si et seulement si elle est active. */
export function isCategoryAssignable(category: Category): boolean {
  return category.isActive;
}

/** Sous-ensemble assignable à une NOUVELLE sélection (actives uniquement), dans l'ordre d'origine. */
export function listAssignableCategories(categories: readonly Category[]): readonly Category[] {
  return categories.filter(isCategoryAssignable);
}

/**
 * Référence d'une Catégorie à résoudre pour un Exercice (modale de
 * sélection Catégorie, `08` l.978 / `13` §4.10) : soit une Catégorie déjà
 * persistée (prédéfinie ou créée précédemment), soit une Catégorie
 * personnalisée à créer — sa création ne devient effective que dans la
 * transaction atomique d'enregistrement de l'Exercice, jamais isolément
 * avant elle (même contrat que l'ancien `CreateSessionCategoryInput`).
 */
export type CreateCategoryInput =
  | { readonly kind: "EXISTING"; readonly categoryId: string }
  | { readonly kind: "NEW"; readonly name: string; readonly color: CategoryColor };

/**
 * Valide une couleur de Catégorie (une des `CATEGORY_COLORS` canoniques,
 * réutilisées de `SESSION_COLORS`) — `categories/validation.ts` reste
 * intégralement PRÉSERVÉ (`FILE_UNCHANGED`, contrat de bornes) : cette
 * validation, nouvelle pour cette tranche, est donc co-localisée ici plutôt
 * que d'y être ajoutée.
 */
export function validateCategoryColor(raw: string): CategoryValidationResult<CategoryColor> {
  if (!CATEGORY_COLORS.includes(raw as CategoryColor)) {
    return fail([{ code: "INVALID_COLOR", field: "category.color" }]);
  }
  return ok(raw as CategoryColor);
}

/**
 * Validation et normalisation métier de la Catégorie (T01-S09, D-106).
 *
 * Fonction pure, indépendante de SQL et d'Expo : ne lève jamais d'exception,
 * retourne un `CategoryValidationResult` (§ contrat dans `errors.ts`). Les
 * bornes de longueur sont comptées par points de code Unicode
 * (`Array.from(value).length`), même convention que `@/domain/sessions/
 * validation.ts`.
 */

import { normalizeName } from "@/domain/sessions/validation";
import { fail, ok, type CategoryValidationResult } from "./errors";

/** Exportée pour être réutilisée telle quelle comme `maxLength` d'un `TextInput` (écran Catégories) — jamais dupliquée en dur (D-106). */
export const CATEGORY_NAME_MAX_LENGTH = 40;

function codePointLength(value: string): number {
  return Array.from(value).length;
}

/**
 * Trim + réduction des espaces internes — réutilise exactement
 * `normalizeName` (Domaine Séance) : D-106 n'impose aucune règle de
 * normalisation d'espaces différente de celle déjà établie pour le Nom de
 * la Séance/de l'Exercice, aucune raison d'en dupliquer une variante ici.
 * Casse et diacritiques conservés — c'est la valeur affichée et persistée.
 */
export function normalizeCategoryName(raw: string): string {
  return normalizeName(raw);
}

/**
 * Clé canonique de comparaison/unicité (D-106) : normalisation des espaces
 * (`normalizeCategoryName`), puis casse ET diacritiques ignorés
 * (`toLowerCase` + décomposition Unicode NFD + suppression des marques
 * combinantes). Jamais affichée à l'utilisateur — seul `normalizeCategoryName`
 * produit le libellé visible/persisté.
 */
export function canonicalCategoryKey(raw: string): string {
  return normalizeCategoryName(raw)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "");
}

/** Nom d'une Catégorie personnalisée : non vide après normalisation, au plus `CATEGORY_NAME_MAX_LENGTH` points de code (D-106). */
export function validateCategoryName(raw: string): CategoryValidationResult<string> {
  const normalized = normalizeCategoryName(raw);
  const length = codePointLength(normalized);

  if (length < 1) {
    return fail([{ code: "REQUIRED", field: "category.name" }]);
  }
  if (length > CATEGORY_NAME_MAX_LENGTH) {
    return fail([{ code: "TOO_LONG", field: "category.name", details: { max: CATEGORY_NAME_MAX_LENGTH } }]);
  }
  return ok(normalized);
}

import { SESSION_COLORS, type SessionColor } from "@/domain/sessions/Session";
import { normalizeName } from "@/domain/sessions/validation";

/**
 * Étiquette persistante (V2-PRE-1, plan §3.1/§3.3 ; V2-PRE-2, plan §6.1) :
 * nom, couleur, état actif/retiré, affectation FACULTATIVE à une Séance. La
 * couleur affichée d'une Séance est DÉRIVÉE de son Étiquette associée — une
 * Étiquette retirée reste représentable par les Séances qui la référencent
 * déjà, sans être disponible pour une nouvelle affectation (même règle que
 * `@/domain/body-zones`).
 *
 * V2-PRE-2 : clé normalisée obligatoire et unique (`canonicalKey`,
 * `canonicalLabelKey`) — créer un nom dont la clé normalisée correspond à
 * une entrée RETIRÉE la réactive (D2, même identifiant, associations
 * conservées, couleur choisie appliquée) ; un nom actif de même clé est
 * refusé comme doublon.
 *
 * Réutilise l'énumération `SessionColor`/`SESSION_COLORS` déjà établie
 * (`@/domain/sessions/Session`) plutôt que d'en dupliquer une variante.
 */

export type LabelColor = SessionColor;
export const LABEL_COLORS: readonly LabelColor[] = SESSION_COLORS;

export type Label = {
  readonly id: string;
  readonly name: string;
  readonly canonicalKey: string;
  readonly color: LabelColor;
  readonly isActive: boolean;
  readonly createdAt: string;
};

/** Une Étiquette est disponible pour une NOUVELLE affectation si et seulement si elle est active. */
export function isLabelAssignable(label: Label): boolean {
  return label.isActive;
}

/** Sous-ensemble assignable à une NOUVELLE sélection (actives uniquement), dans l'ordre d'origine. */
export function listAssignableLabels(labels: readonly Label[]): readonly Label[] {
  return labels.filter(isLabelAssignable);
}

/** Entrée de création d'une Étiquette (modale de sélection Étiquettes, `13` §4.10) — nom et couleur, jamais d'identifiant (généré par le Repository). */
export type CreateLabelInput = {
  readonly name: string;
  readonly color: LabelColor;
};

export type LabelValidationErrorCode =
  | "REQUIRED"
  | "TOO_LONG"
  | "INVALID_COLOR"
  /** Un nom dont la clé normalisée correspond à une Étiquette déjà ACTIVE (D2). */
  | "DUPLICATE"
  /** Une nouvelle affectation vise une Étiquette retirée (T16) — la création/réactivation reste permise, seule une AFFECTATION nouvelle à l'identifiant déjà retiré est refusée. */
  | "RETIRED"
  | "NOT_FOUND";
export type LabelValidationField = "label.name" | "label.color" | "label.id";
export type LabelValidationViolation = {
  readonly code: LabelValidationErrorCode;
  readonly field: LabelValidationField;
  readonly details?: { readonly max?: number };
};
export type LabelValidationResult<T> =
  | { readonly ok: true; readonly value: T }
  | { readonly ok: false; readonly violations: readonly LabelValidationViolation[] };

/** Mêmes bornes que `@/domain/categories/validation.ts` (`CATEGORY_NAME_MAX_LENGTH`, D-106) — aucun fichier `errors.ts`/`validation.ts` dédié n'est autorisé pour ce domaine (`scope_allow`) : validation co-localisée ici. */
export const LABEL_NAME_MAX_LENGTH = 40;

function normalizeLabelName(raw: string): string {
  return normalizeName(raw);
}

/**
 * Clé canonique de comparaison/unicité (même patron que
 * `canonicalCategoryKey`, D-106) : normalisation des espaces, casse ET
 * diacritiques ignorés. Jamais affichée à l'utilisateur.
 */
export function canonicalLabelKey(raw: string): string {
  return normalizeLabelName(raw)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "");
}

/** Nom d'une Étiquette : non vide après normalisation, au plus `LABEL_NAME_MAX_LENGTH` points de code (même contrat que `validateCategoryName`). */
export function validateLabelName(raw: string): LabelValidationResult<string> {
  const normalized = normalizeLabelName(raw);
  const length = Array.from(normalized).length;
  if (length < 1) {
    return { ok: false, violations: [{ code: "REQUIRED", field: "label.name" }] };
  }
  if (length > LABEL_NAME_MAX_LENGTH) {
    return {
      ok: false,
      violations: [{ code: "TOO_LONG", field: "label.name", details: { max: LABEL_NAME_MAX_LENGTH } }],
    };
  }
  return { ok: true, value: normalized };
}

/** Couleur d'une Étiquette (une des `LABEL_COLORS` canoniques). */
export function validateLabelColor(raw: string): LabelValidationResult<LabelColor> {
  if (!LABEL_COLORS.includes(raw as LabelColor)) {
    return { ok: false, violations: [{ code: "INVALID_COLOR", field: "label.color" }] };
  }
  return { ok: true, value: raw as LabelColor };
}

/** Valide et normalise une entrée de création d'Étiquette complète. */
export function validateCreateLabelInput(
  input: CreateLabelInput,
): LabelValidationResult<CreateLabelInput> {
  const violations: LabelValidationViolation[] = [];
  const nameResult = validateLabelName(input.name);
  if (!nameResult.ok) {
    violations.push(...nameResult.violations);
  }
  const colorResult = validateLabelColor(input.color);
  if (!colorResult.ok) {
    violations.push(...colorResult.violations);
  }
  if (violations.length > 0) {
    return { ok: false, violations };
  }
  return {
    ok: true,
    value: { name: (nameResult as { ok: true; value: string }).value, color: input.color },
  };
}

