      }),
    ).toBe(false);
  });

  it("toCreateSessionInput / toUpdateSessionInput carry each Activity's own side mode", () => {
    const exercises = [
      { ...createExerciseDraft("ex-1"), name: "Gainage", durationSeconds: 30, sideMode: "RIGHT_LEFT" as const },
    ];

    const created = toCreateSessionInput({
      ...createEmptyDraft(),
