      exercises,
    });
    expect(created.ok).toBe(true);
    if (created.ok) {
      expect(created.value.exercises[0]?.sideMode).toBe("RIGHT_LEFT");
    }

    const updated = toUpdateSessionInput({
      ...createEmptyDraft(),
      sourceSessionId: "session-1",
      name: "Séance",
      exercises,
    });
