/**
 * Calculs métier déterministes (§10, §12.5) : Nombre d'Activités et Durée
 * estimée.
 *
 * Ces fonctions n'acceptent qu'une entrée métier minimale (« Facts »),
 * jamais une ligne SQL ni un type d'infrastructure.
 *
 * **T02-S01 — structure réelle des trois zones** (CE-T02-01 « Calculs »,
 * AC-10) — conservée par PRE-3 :
 *
 * 1. le NOMBRE d'Activités est celui des Activités RÉELLEMENT COMPOSÉES —
 *    chaque Activité compte UNE SEULE FOIS, quelle que soit sa zone et quel
 *    que soit `tourRepeatCount` ;
 * 2. la DURÉE estimée compte une fois les Activités `BEFORE_TOUR`, multiplie
 *    les Activités `IN_TOUR` par `tourRepeatCount`, puis compte une fois les
 *    Activités `AFTER_TOUR` ;
 * 3. le Compte à rebours initial et la Fin de séance sont EXCLUS de cette
 *    durée affichée.
 *
 * **PRE-3 — autorité unique de la durée d'un Exercice** (v13 §5, Bip v2
 * §2–3) : la durée d'une occurrence n'est plus une formule scalaire locale
 * (ancienne substitution `C − 1`, multiplicateur de côté sans Pause entre
 * les côtés, convention de borne minimale à l'Exercice) mais le résultat
 * typé de `executionCalculations.ts`, à partir des paramètres canoniques de
 * l'occurrence (ou de l'adaptateur conservateur d'un ancien objet) et de sa
 * Récupération explicite, qui remplace UNIQUEMENT la Pause terminale. Une
 * zone porte la somme des contributions connues et la nature du total
 * (exact / ≈ / ≥) ; la projection SQL de liste ne recalcule plus rien.
 */

import {
  resolveExecutionParameters,
  type ExecutionParametersInput,
} from "@/domain/activities/ExecutionParameters";
import {
  aggregateSessionDuration,
  computeOccurrenceDuration,
  type ExerciseDurationResult,
  type SessionDurationContribution,
  type SessionDurationResult,
} from "@/domain/activities/executionCalculations";

import type { Activity, ActivityType, ExerciseExecutionMode, Session } from "./Session";
import type { SideMode } from "./sideMode";

/**
 * Entrée minimale du calcul de durée d'UNE Activité — satisfaite aussi bien
 * par une `Activity` persistée que par un `SessionDraftExercise` (structural
 * typing), pour que le brouillon et l'agrégat ne portent jamais deux formules
 * distinctes.
 */
export type ActivityDurationFacts = {
  readonly type: ActivityType;
  readonly executionMode: ExerciseExecutionMode | null;
  readonly durationSeconds: number | null;
  readonly repetitionCount?: number | null;
  readonly seriesCount: number | null;
  readonly pauseSeconds: number;
  /** Récupération explicite de l'occurrence (`0` = aucune) — remplace la seule Pause terminale. */
  readonly postActivityRecoverySeconds?: number;
  readonly sideMode?: SideMode;
  /** PRE-3 : paramètres canoniques — autorité quand présents. */
  readonly executionParameters?: ExecutionParametersInput;
};

/**
 * Résultat typé de la durée d'UNE occurrence (`exact | estimated |
 * omitted`), contributions connues comprises. Une ancienne Activité
 * `RECOVERY` autonome (convertie par `migration004`, plus jamais produite)
 * reste lue défensivement comme une durée exacte.
 */
export function computeActivityDurationResult(activity: ActivityDurationFacts): ExerciseDurationResult {
  if (activity.type === "RECOVERY") {
    const seconds = activity.durationSeconds ?? 0;
    return { kind: "exact", knownSeconds: seconds, events: [], seconds };
  }
  const parameters = resolveExecutionParameters({
    executionMode: activity.executionMode,
    durationSeconds: activity.durationSeconds,
    repetitionCount: activity.repetitionCount ?? null,
    seriesCount: activity.seriesCount,
    pauseSeconds: activity.pauseSeconds,
    sideMode: activity.sideMode,
    executionParameters: activity.executionParameters,
  });
  if (parameters.mode === null) {
    return { kind: "omitted", knownSeconds: 0, events: [] };
  }
  return computeOccurrenceDuration(parameters, activity.postActivityRecoverySeconds ?? 0);
}

/** Contributions chronométrées connues d'UNE occurrence (montant exact, estimé, ou partiel si omis). */
export function computeActivityDurationSeconds(activity: ActivityDurationFacts): number {
  return computeActivityDurationResult(activity).knownSeconds;
}

/**
 * Durées par zone structurelle (T02-S01) — trois colonnes distinctes, jamais
 * un total déjà agrégé : seule la zone `IN_TOUR` est multipliée par
 * `tourRepeatCount`.
 */
export type EstimatedDurationFacts = {
  readonly beforeTourDurationSeconds: number;
  readonly inTourDurationSeconds: number;
  readonly afterTourDurationSeconds: number;
  /** Répétition du Tour, entier `1..99` (D-058). */
  readonly tourRepeatCount: number;
  /** `true` dès qu'au moins une occurrence contributrice a un travail inconnu (total ≥). */
  readonly isLowerBoundEstimate: boolean;
  /** PRE-3 : `true` dès qu'au moins une occurrence contributrice est estimée (≈). */
  readonly isEstimated?: boolean;
};

/**
 * Nombres d'Activités par zone structurelle (T02-S01). Deux lectures
 * distinctes en découlent, jamais confondues : le nombre d'Activités
 * COMPOSÉES (`computeActivityCount`) et le nombre total d'Activités À
 * EXÉCUTER (`computeTotalActivitiesToExecute`, RM-075).
 */
export type ActivityCountFacts = {
  readonly beforeTourActivityCount: number;
  readonly inTourActivityCount: number;
  readonly afterTourActivityCount: number;
  readonly tourRepeatCount: number;
};

/** Durée estimée = zone avant Tour + (zone du Tour × répétitions du Tour) + zone après Tour. */
export function computeEstimatedDurationSeconds(facts: EstimatedDurationFacts): number {
  return (
    facts.beforeTourDurationSeconds +
    facts.inTourDurationSeconds * facts.tourRepeatCount +
    facts.afterTourDurationSeconds
  );
}

/**
 * Nombre d'Activités RÉELLEMENT COMPOSÉES : chaque Activité des trois zones
 * compte une seule fois, sans multiplication par les répétitions du Tour.
 */
export function computeActivityCount(facts: ActivityCountFacts): number {
  return (
    facts.beforeTourActivityCount + facts.inTourActivityCount + facts.afterTourActivityCount
  );
}

/**
 * Nombre total d'Activités à exécuter (RM-075), après développement des
 * répétitions du Tour : les zones hors Tour comptent une fois, la zone du
 * Tour `tourRepeatCount` fois.
 */
export function computeTotalActivitiesToExecute(facts: ActivityCountFacts): number {
  return (
    facts.beforeTourActivityCount +
    facts.inTourActivityCount * facts.tourRepeatCount +
    facts.afterTourActivityCount
  );
}

/** Durée cumulée d'une COLLECTION d'Activités, et nature du total. */
export type ZoneDurationFacts = {
  readonly seconds: number;
  /** Au moins un travail inconnu : total ≥ contributions connues. */
  readonly isLowerBoundEstimate: boolean;
  /** PRE-3 : présent et vrai dès qu'au moins une occurrence est estimée (≈) ; absent sinon. */
  readonly isEstimated?: boolean;
};

/**
 * Somme des contributions connues d'une zone (ou de toute autre collection)
 * et nature du total — partagée par la présentation (Composition) et
 * l'agrégat, jamais réécrite ailleurs. Chaque occurrence contribue avec SES
 * propres paramètres et SA Récupération explicite.
 */
export function computeZoneDurationFacts(
  activities: readonly ActivityDurationFacts[],
): ZoneDurationFacts {
  let seconds = 0;
  let isLowerBoundEstimate = false;
  let isEstimated = false;
  for (const activity of activities) {
    const result = computeActivityDurationResult(activity);
    seconds += result.knownSeconds;
    isLowerBoundEstimate = isLowerBoundEstimate || result.kind === "omitted";
    isEstimated = isEstimated || result.kind === "estimated";
  }
  return isEstimated ? { seconds, isLowerBoundEstimate, isEstimated } : { seconds, isLowerBoundEstimate };
}

export type StructuredActivities<T extends ActivityDurationFacts> = {
  readonly beforeTour: readonly T[];
  readonly inTour: readonly T[];
  readonly afterTour: readonly T[];
  readonly tourRepeatCount: number;
};

/**
 * PRE-3 (P3-13/tours-cycles-list) : total typé de la Séance — exact / ≈ /
 * ≥ — en développant les répétitions du Circuit sur la seule zone
 * `IN_TOUR`. Autorité unique partagée par la lecture complète, la liste
 * (`listActive`) et la Composition.
 */
export function computeStructuredSessionDuration<T extends ActivityDurationFacts>(
  structure: StructuredActivities<T>,
): SessionDurationResult {
  const contributions: SessionDurationContribution[] = [];
  const add = (activities: readonly T[], multiplicity: number) => {
    for (const activity of activities) {
      contributions.push({ result: computeActivityDurationResult(activity), multiplicity });
    }
  };
  add(structure.beforeTour, 1);
  add(structure.inTour, structure.tourRepeatCount);
  add(structure.afterTour, 1);
  return aggregateSessionDuration(contributions);
}

/** Total typé d'une Séance persistée (lecture complète). */
export function toSessionDurationResult(session: Session): SessionDurationResult {
  return computeStructuredSessionDuration({
    beforeTour: session.cycle.beforeTour ?? [],
    inTour: session.cycle.tour.exercises,
    afterTour: session.cycle.afterTour ?? [],
    tourRepeatCount: session.cycle.tour.repeatCount,
  });
}

function zoneDurationSeconds(activities: readonly Activity[]): ZoneDurationFacts {
  return computeZoneDurationFacts(activities);
}

export function toEstimatedDurationFacts(session: Session): EstimatedDurationFacts {
  const beforeTour = zoneDurationSeconds(session.cycle.beforeTour ?? []);
  const inTour = zoneDurationSeconds(session.cycle.tour.exercises);
  const afterTour = zoneDurationSeconds(session.cycle.afterTour ?? []);

  return {
    beforeTourDurationSeconds: beforeTour.seconds,
    inTourDurationSeconds: inTour.seconds,
    afterTourDurationSeconds: afterTour.seconds,
    tourRepeatCount: session.cycle.tour.repeatCount,
    isLowerBoundEstimate:
      beforeTour.isLowerBoundEstimate ||
      inTour.isLowerBoundEstimate ||
      afterTour.isLowerBoundEstimate,
    ...(beforeTour.isEstimated || inTour.isEstimated || afterTour.isEstimated ? { isEstimated: true } : {}),
  };
}

export function toActivityCountFacts(session: Session): ActivityCountFacts {
  return {
    beforeTourActivityCount: (session.cycle.beforeTour ?? []).length,
    inTourActivityCount: session.cycle.tour.exercises.length,
    afterTourActivityCount: (session.cycle.afterTour ?? []).length,
    tourRepeatCount: session.cycle.tour.repeatCount,
  };
}

/**
 * Opérations métier PURES de réorganisation d'une Composition (T02-S01,
 * CE-T02-01/CE-T02-02, D-124/D-127/D-129).
 *
 * Aucune dépendance React Native, Expo ou SQLite : ce module manipule
 * uniquement la collection ordonnée `SessionDraft.exercises` et retourne une
 * NOUVELLE collection — il ne persiste jamais rien. Conformément à
 * `API-COM-06`, déplacement, duplication et suppression restent des
 * opérations de BROUILLON : elles ne deviennent persistantes qu'à
 * l'enregistrement final de la Séance.
 *
 * **Positions** : `SessionDraft.exercises` ne porte aucun champ `position`.
 * Le rang d'une Activité DANS SA ZONE est dérivé de son ordre dans cette
 * collection au moment de la conversion (`toCreateSessionInput` /
 * `toUpdateSessionInput`) — la « renumérotation continue par zone » exigée
 * par CE-T02-01 est donc obtenue par construction, jamais par un champ à
 * tenir cohérent.
 */

import { cloneExecutionParameters } from "@/domain/activities/ExecutionParameters";

import type { StructuralPosition } from "./Session";
import type { SessionDraftExercise } from "./SessionDraft";

/** Ordre canonique d'affichage et d'exécution des trois zones (D-061). */
export const STRUCTURAL_ZONES = ["BEFORE_TOUR", "IN_TOUR", "AFTER_TOUR"] as const;

export type CompositionZones = {
  readonly beforeTour: readonly SessionDraftExercise[];
  readonly inTour: readonly SessionDraftExercise[];
  readonly afterTour: readonly SessionDraftExercise[];
};

/**
 * Regroupe les Activités du brouillon par zone structurelle, en conservant
 * dans chaque zone l'ordre relatif de la collection source — cet ordre EST
 * l'ordre d'affichage et le rang persisté.
 */
export function groupActivitiesByZone(
  activities: readonly SessionDraftExercise[],
): CompositionZones {
  const beforeTour: SessionDraftExercise[] = [];
  const inTour: SessionDraftExercise[] = [];
  const afterTour: SessionDraftExercise[] = [];

  for (const activity of activities) {
    if (activity.structuralPosition === "BEFORE_TOUR") {
      beforeTour.push(activity);
    } else if (activity.structuralPosition === "AFTER_TOUR") {
      afterTour.push(activity);
    } else {
      inTour.push(activity);
    }
  }

  return { beforeTour, inTour, afterTour };
}

/**
 * Ajoute une NOUVELLE Activité immédiatement APRÈS la DERNIÈRE CARTE
 * ACTUELLEMENT AFFICHÉE, dont elle reprend la zone structurelle (T02-S02,
 * troisième recette visuelle, point 1).
 *
 * **Le placement est décidé au moment de l'ajout, jamais à l'ouverture de
 * l'écran.** La zone portée par le brouillon local — figée au montage par
 * `createExerciseDraft` — n'est PAS consultée : seule compte la Composition
 * telle qu'elle est affichée à l'instant où l'utilisateur termine sa
 * création. C'est ce qui rend le résultat conforme à ce que l'utilisateur
 * voit :
 *
 * | Dernière carte affichée | Nouvelle Activité |
 * | --- | --- |
 * | `BEFORE_TOUR` | juste après elle, donc avant le Tour |
 * | `IN_TOUR` | juste après elle, donc dernière du Tour |
 * | `AFTER_TOUR` | juste après elle, donc avant `Fin de séance` |
 *
 * « Dernière carte affichée » est bien celle de l'ORDRE DE LECTURE
 * (`orderActivitiesByZone`), pas celle de la fin du tableau : la collection
 * n'est pas nécessairement contiguë par zone — `moveActivity` la réordonne —
 * et `[in-1, before-1]` est une Composition parfaitement légitime, dont la
 * dernière carte affichée est `in-1`.
 *
 * L'insertion se fait ensuite juste après cette Activité DANS LA COLLECTION :
 * la nouvelle devient ainsi la dernière de sa zone, donc la dernière
 * affichée. Une Composition encore vide conserve la zone par défaut de
 * l'Activité fournie.
 */
export function appendActivityAfterLastDisplayed(
  activities: readonly SessionDraftExercise[],
  activity: SessionDraftExercise,
): readonly SessionDraftExercise[] {
  const displayed = orderActivitiesByZone(activities);
  const lastDisplayed = displayed[displayed.length - 1];

  if (lastDisplayed === undefined) {
    return [activity];
  }

  const anchorIndex = activities.indexOf(lastDisplayed);
  const next = [...activities];
  next.splice(anchorIndex + 1, 0, {
    ...activity,
    structuralPosition: lastDisplayed.structuralPosition,
  });
  return next;
}

/** Activités d'une seule zone, dans l'ordre (raccourci de `groupActivitiesByZone`). */
export function activitiesInZone(
  activities: readonly SessionDraftExercise[],
  zone: StructuralPosition,
): readonly SessionDraftExercise[] {
  return activities.filter((activity) => activity.structuralPosition === zone);
}

/**
 * Collection à plat normalisée dans l'ordre structurel réel (avant → dans →
 * après le Tour). Une Activité ajoutée en fin de collection dans une zone
 * antérieure reste correctement placée à l'affichage sans cette
 * normalisation (l'affichage regroupe par zone) : cette fonction sert aux
 * opérations qui doivent produire une collection déjà cohérente de bout en
 * bout, jamais à réordonner une Séance persistée à la lecture.
 */
export function orderActivitiesByZone(
  activities: readonly SessionDraftExercise[],
): readonly SessionDraftExercise[] {
  const zones = groupActivitiesByZone(activities);
  return [...zones.beforeTour, ...zones.inTour, ...zones.afterTour];
}

/**
 * Déplace une Activité vers `targetZone` à l'indice `targetIndex` DANS cette
 * zone (CE-T02-01) — intra-zone comme inter-zones.
 *
 * L'identifiant et TOUS les paramètres de l'Activité sont conservés ; seule
 * `structuralPosition` change lorsque la zone change. Aucune Activité n'est
 * créée, dupliquée ni perdue. `targetIndex` est borné à la taille réelle de
 * la zone de destination (une dépose au-delà de la dernière carte place
 * l'Activité en fin de zone). Un identifiant inconnu retourne la collection
 * inchangée — une dépose sans cible valide ne modifie jamais le brouillon.
 *
 * V2-PRE-1 (plan §3.3) : le Circuit (Tour) n'a plus aucune influence
 * fonctionnelle sur la direction — une Activité déposée dans n'importe
 * quelle zone conserve toujours sa direction propre inchangée.
 */
export function moveActivity(
  activities: readonly SessionDraftExercise[],
  activityId: string,
  targetZone: StructuralPosition,
  targetIndex: number,
): readonly SessionDraftExercise[] {
  const source = activities.find((activity) => activity.id === activityId);
  if (source === undefined) {
    return activities;
  }

  const remaining = activities.filter((activity) => activity.id !== activityId);
  const zones: Record<StructuralPosition, SessionDraftExercise[]> = {
    BEFORE_TOUR: [],
    IN_TOUR: [],
    AFTER_TOUR: [],
  };
  for (const activity of remaining) {
    zones[activity.structuralPosition].push(activity);
  }

  const moved =
    source.structuralPosition === targetZone ? source : { ...source, structuralPosition: targetZone };

  const destination = zones[targetZone];
  const index = Number.isFinite(targetIndex) ? Math.trunc(targetIndex) : destination.length;
  destination.splice(Math.max(0, Math.min(index, destination.length)), 0, moved);

  return [...zones.BEFORE_TOUR, ...zones.IN_TOUR, ...zones.AFTER_TOUR];
}

/**
 * Retire UNIQUEMENT l'Activité visée du brouillon (CE-T02-01). Les autres
 * Activités conservent leur identifiant, leurs paramètres et leur ordre
 * relatif ; la zone concernée est renumérotée par construction (voir la note
 * de tête). Un identifiant inconnu retourne la collection inchangée.
 */
export function removeActivity(
  activities: readonly SessionDraftExercise[],
  activityId: string,
): readonly SessionDraftExercise[] {
  if (!activities.some((activity) => activity.id === activityId)) {
    return activities;
  }
  return activities.filter((activity) => activity.id !== activityId);
}

/**
 * Duplique une Activité (D-138, révisant D-124 ; CE-T02-01) : la copie est
 * INDÉPENDANTE, porte `newId` (fourni par l'appelant — ce module reste pur,
 * sans `expo-crypto`), reprend TOUS les paramètres et associations de la
 * source — Pause, **Récupération attachée** et **direction (`sideMode`,
 * V2-BILAT-01) comprises** — et s'insère
 * IMMÉDIATEMENT APRÈS elle dans la MÊME zone structurelle.
 *
 * **T02-S02 — titre strictement identique.** La copie conserve le nom exact
 * de la source ; aucun suffixe n'est appliqué. `D-124` prescrivait
 * `{nom} (copie)`, puis `{nom} (copie 2)`… mais elle est explicitement
 * marquée « Révisée par D-138 » dans le Registre, et `D-138` — la décision
 * qui la remplace — ne réintroduit AUCUNE règle de renommage : elle pose au
 * contraire que « la Récupération appartient à l'Activité et forme avec elle
 * un bloc indivisible pour la Composition, la copie, la duplication… ». La
 * copie est donc rigoureusement identique à sa source, à l'identifiant près.
 * L'ancienne fonction `nextCopyName` est supprimée plutôt que laissée sans
 * consommateur. Écart documentaire disclosé dans le rapport de mission :
 * `13 – Contrats d'écran.md` (CE-T02-01) porte encore la formulation
 * suffixée de D-124, non mise à jour après la publication de D-138.
 *
 * La source reste inchangée. Un identifiant inconnu retourne la collection
 * inchangée.
 */
export function duplicateActivity(
  activities: readonly SessionDraftExercise[],
  activityId: string,
  newId: string,
): readonly SessionDraftExercise[] {
  const index = activities.findIndex((activity) => activity.id === activityId);
  if (index === -1) {
    return activities;
  }

  const source = activities[index]!;
  const copy: SessionDraftExercise = {
    ...source,
    id: newId,
    // Les Zones corporelles sont recopiées comme une NOUVELLE collection :
    // la copie ne doit jamais partager la référence de tableau de sa source.
    bodyZoneIds: [...source.bodyZoneIds],
    // PRE-3 (P3-18) : duplication COMPLÈTE et indépendante — paramètres
    // canoniques clonés en profondeur, Catégorie, médias dans le même ordre
    // (mêmes fichiers physiques ; de nouveaux liens seront créés pour la
    // copie à l'enregistrement). La Récupération existante est conservée.
    ...(source.executionParameters
      ? { executionParameters: cloneExecutionParameters(source.executionParameters) }
      : {}),
    ...(source.media ? { media: source.media.map((item) => ({ assetId: item.assetId, asset: { ...item.asset } })) } : {}),
  };

  const next = [...activities];
  next.splice(index + 1, 0, copy);
  return next;
}

