            <ActivitySelectionScreen />
          </SessionDraftContext.Provider>
        </ProfileServiceContext.Provider>
      </ActivityDefinitionServiceContext.Provider>
    </TestSafeAreaProvider>,
  );
  return { updateDraft };
}

