            style={[styles.referencePill, zoneNames.length > 0 ? null : styles.referenceIconOnly]}
            testID="exercise-body-zones-open"
          >
            {zoneNames.length > 0 ? (
              <Text style={styles.referenceLabel} numberOfLines={1}>
                {zoneNames.join(" · ")}
              </Text>
