          ref={bodyScrollRef}
          style={styles.body}
          contentContainerStyle={styles.bodyContent}
          keyboardShouldPersistTaps="handled"
          onLayout={(event) => {
            bodyHeightRef.current = event.nativeEvent.layout.height;
