    ).toBe("70 s");

    fireEvent.press(screen.getByTestId("profile-setting-sessionFinalPhaseSecondsDefault"));
    expect(
      screen.getByTestId("profile-setting-sessionFinalPhaseSecondsDefault-increment").props
        .accessibilityState,
