          repetitionCount: null,
          seriesCount: 3,
          pauseSeconds: 15,
        }),
      );
      expect(inherited).not.toContain("par côté");
    });
  });

  describe("formatExerciseRecap — direction développée (correction bornée, plan `## 4.5`)", () => {
    const base = {
      name: "Gainage",
      executionMode: "DURATION" as const,
      durationSeconds: 90,
      repetitionCount: null,
      seriesCount: 3,
      pauseSeconds: 15,
      postActivityRecoverySeconds: 0,
