import { strings } from "@/shared/i18n";

/**
 * Fonctions de présentation pures pour `SessionCard` (T01-S06).
 *
 * Volontairement séparées de `resources/fr.ts` : le système d'i18n du
 * projet n'expose aujourd'hui que des chaînes statiques (aucune fonction),
 * et cette tranche ne modifie pas ce contrat transverse pour les seuls
 * besoins de deux pluriels et d'un arrondi de durée — voir
 * `src/features/sessions/README.md`. Ces fonctions lisent les fragments
 * lexicaux nécessaires (singulier/pluriel, unité) dans `strings`, sans
 * jamais les dupliquer en dur, et portent elles-mêmes la logique
 * d'assemblage et d'arrondi.
 */

/** `1 activité` / `N activités`. */
export function formatActivityCount(count: number): string {
  const label =
    count === 1
      ? strings.screens.sessions.card.activitySingular
      : strings.screens.sessions.card.activityPlural;
  return `${count} ${label}`;
}

/** `1 tour` / `N tours`. */
export function formatTourCount(count: number): string {
  const label =
    count === 1
      ? strings.screens.sessions.card.tourSingular
      : strings.screens.sessions.card.tourPlural;
  return `${count} ${label}`;
}

/**
 * `N min`. La durée affichée est une estimation qui ne doit jamais
 * sous-estimer la durée réelle : les secondes entamées comptent pour une
 * minute entière (`Math.ceil`), plutôt qu'un arrondi au plus proche ou une
 * troncature qui minorerait l'attente réelle de l'utilisateur — aucune
 * règle d'arrondi n'étant fixée par les spécifications fonctionnelles pour
 * ce cas (arbitrage documenté dans le plan d'implémentation de T01-S06).
 *
 * `isApproximate` (T01-S09, RM-072) : préfixe `≥` dès qu'au moins une
 * Activité de la Composition est en mode Répétitions — même convention déjà
 * établie côté brouillon par `formatCompositionSummary`
 * (`compositionPresentation.ts`), désormais également appliquée à une
 * Séance persistée (`SessionSummary.isEstimatedDurationApproximate`).
 */
/**
 * PRE-3 (P3-13/tours-cycles-list) : `kind` accepte désormais le résultat
 * typé de l'autorité Domaine (`exact` sans symbole, `estimated` → « ≈ »,
 * `lowerBound` → « ≥ ») ; le booléen historique reste accepté (`true` =
 * borne minimale) pour les appelants existants.
 */
export function formatEstimatedDuration(
  seconds: number,
  kind: boolean | "exact" | "estimated" | "lowerBound" = false,
): string {
  const minutes = Math.ceil(seconds / 60);
  const formatted = `${minutes} ${strings.screens.sessions.card.durationUnit}`;
  if (kind === "estimated") {
    return `≈ ${formatted}`;
  }
  return kind === true || kind === "lowerBound" ? `≥ ${formatted}` : formatted;
}

/**
 * Segment Catégories de la ligne de synthèse sous le nom de la Séance
 * (T01-S09, correction VISUAL tentative 2, point B ; séparation en segment
 * dédié introduite par la correction VISUAL point A, commentaire de revue
 * 5551083690, pour permettre son rendu dans la couleur propre de la
 * Séance — `SessionCard.tsx` colore ce seul segment, jamais le segment Zones
 * corporelles ni le séparateur). Liste jointe par `", "`, dans l'ordre déjà
 * déterminé par `SessionSummary.categoryNames` (Repository, D-107) — jamais
 * réordonné ici. `null` si aucune Catégorie n'est associée.
 */
export function formatCategoryNamesSegment(categoryNames: readonly string[]): string | null {
  return categoryNames.length > 0 ? categoryNames.join(", ") : null;
}

/**
 * Segment Zones corporelles de la ligne de synthèse — même patron que
 * `formatCategoryNamesSegment`, ordre déjà déterminé par
 * `SessionSummary.bodyZoneNames` (référentiel, jamais réordonné ici). `null`
 * si aucune Zone corporelle n'est couverte.
 */
export function formatBodyZoneNamesSegment(bodyZoneNames: readonly string[]): string | null {
  return bodyZoneNames.length > 0 ? bodyZoneNames.join(", ") : null;
}

/**
 * Ligne de synthèse Catégories + Zones corporelles affichée sous le nom de
 * la Séance sur la carte condensée (T01-S09, correction VISUAL tentative 2,
 * point B — ligne manquante du contrat d'écran CE-T01-03 : `Catégories |
 * Associations de Catégories | Si présentes ; ordre et présentation
 * conformes au composant`).
 *
 * Correction VISUAL point A (commentaire de revue 5551083690, 2e
 * contre-recette) : le séparateur entre le groupe Catégories et le groupe
 * Zones corporelles devient `" : "` (auparavant `" · "`, point médian —
 * défaut visuel signalé, le rendu attendu est par exemple
 * « Cardio : Genoux, Dos »). Un groupe vide est omis entièrement (jamais un
 * séparateur adjacent à un segment vide). `null` si aucun des deux groupes
 * n'a de valeur — état vide, l'appelant ne rend alors aucune ligne (jamais
 * une ligne visible vide).
 *
 * Assemblée à partir des mêmes segments que `SessionCard.tsx` utilise pour
 * le rendu coloré (`formatCategoryNamesSegment`/`formatBodyZoneNamesSegment`)
 * — une seule définition de la règle de séparation, jamais dupliquée entre
 * cette forme texte brut et le rendu à deux couleurs.
 */
export function formatSessionTagLine(
  categoryNames: readonly string[],
  bodyZoneNames: readonly string[],
): string | null {
  const categoriesSegment = formatCategoryNamesSegment(categoryNames);
  const zonesSegment = formatBodyZoneNamesSegment(bodyZoneNames);

  if (categoriesSegment === null) {
    return zonesSegment;
  }
  if (zonesSegment === null) {
    return categoriesSegment;
  }
  return `${categoriesSegment} : ${zonesSegment}`;
}

import { Host, Picker as SwiftUIPicker, Text as SwiftUIText } from "@expo/ui/swift-ui";
import {
  accessibilityLabel as accessibilityLabelModifier,
  foregroundStyle,
  frame,
  pickerStyle,
  tag,
} from "@expo/ui/swift-ui/modifiers";
import * as Haptics from "expo-haptics";
import { useEffect, useRef, useState } from "react";
import { Platform, Pressable, ScrollView, StyleSheet, Text, View } from "react-native";
import type { NativeScrollEvent, NativeSyntheticEvent } from "react-native";

import {
  WHEEL_NUMBER_MAX,
  WHEEL_NUMBER_MIN,
  clampIndex,
  indexToOffset,
  offsetToIndex,
} from "@/features/sessions/wheelPickerMath";
import { WheelSelectionOverlay } from "@/features/sessions/WheelSelectionOverlay";
import { KodjoIcon } from "@/shared/ui/KodjoIcon";
import { colors, dimensions, spacing, type } from "@/shared/ui/tokens";

/**
 * Roulette à colonne unique pour Répétitions/Séries d'un Exercice (T01-S08,
 * D-092), reconstruite en **REWORK12** (`[ChatGPT] CHANGES_REQUESTED —
 * REWORK12 — Activité + intégration dans Composition`, 2026-09-04, ACT-07)
 * pour suivre le contrat transverse `Picker / Popover — Source exact`
 * (`2537:1174`), variante `Type=Numeric wheel` (`3210:49`) — voir
 * `13 – Contrats d'écran.md`, « Contrat transverse — Sélections numériques
 * compactes », et le rapport de généralisation
 * `.github/orchestration/reports/2026-09-04_numeric-wheel-generalization.md`
 * (frame ouverte de référence pour Séries : `1992:9618`, instance
 * `3211:4012`). L'ancienne implémentation (`onChange` immédiat à chaque cran
 * de défilement, jamais de brouillon ni de confirmation explicite) est
 * remplacée : ce composant est désormais « non fonctionnel » au sens du
 * contrat transverse, qui exige un brouillon local détruit par Annuler et
 * validé uniquement par Confirmer — jamais un engagement au fil du geste.
 *
 * **Primitive native — même priorité que `DurationWheelPicker`** (`.github/
 * AI_ORCHESTRATION.md`, « Priorité aux primitives natives de l'OS ») : sur
 * iOS, ce composant délègue à `@expo/ui/swift-ui`
 * (`pickerStyle('wheel')`) — une seule colonne, valeurs `WHEEL_NUMBER_MIN`…
 * `WHEEL_NUMBER_MAX` (`1`…`99`). La réimplémentation `ScrollView` reste le
 * seul chemin sur Android/web (`@expo/ui/swift-ui` est iOS/tvOS uniquement),
 * même patron que `DurationWheelPicker`, non répété en détail ici.
 *
 * **Toolbar Annuler/Confirmer** : `PickerToolbar` ci-dessous réutilise
 * volontairement les mêmes actifs canoniques (`wheel-action-cancel.svg`/
 * `wheel-action-validate.svg`) et les mêmes tokens de géométrie/couleur
 * (`dimensions.wheelPicker`, `colors.wheelAction*`) que celle de
 * `DurationWheelPicker.tsx` — **dupliquée localement plutôt qu'importée**,
 * cette dernière restant une baseline gelée qu'aucune mission n'est
 * autorisée à modifier (y compris pour en extraire un import partagé) sans
 * autorisation `CHANGE_REQUEST_REQUIRED` distincte ; la duplication porte
 * ici sur un composant de präsentation minimal (deux `Pressable`), pas sur
 * une logique/geometrie dupliquée par ailleurs interdite par le protocole.
 *
 * Contrat `onValidate`/`onCancel` — identique à `DurationWheelPicker` :
 * `onValidate` valide exactement la valeur actuellement centrée (jamais
 * pendant le défilement) ; `onCancel` ferme sans rien modifier. Toucher la
 * roulette, la zone sélectionnée ou arrêter le défilement ne ferme jamais le
 * sélecteur (seules Annuler/Confirmer ferment).
 */

const ITEM_HEIGHT = 40;
const VALUES = Array.from(
  { length: WHEEL_NUMBER_MAX - WHEEL_NUMBER_MIN + 1 },
  (_, index) => WHEEL_NUMBER_MIN + index,
);

const WHEEL_TOOLBAR_HEIGHT = dimensions.wheelPicker.toolbarHeight;
const WHEEL_CONTENT_MIN_HEIGHT = dimensions.wheelPicker.wheelContentMinHeight;
const WHEEL_ACTION_VISUAL_CIRCLE = dimensions.wheelPicker.actionVisualCircle;
const WHEEL_ACTION_ICON = dimensions.wheelPicker.actionIcon;
const WHEEL_ACTION_TOUCH_TARGET = dimensions.wheelPicker.actionTouchTarget;
const WHEEL_ACTION_HIT_SLOP = (WHEEL_ACTION_TOUCH_TARGET - WHEEL_ACTION_VISUAL_CIRCLE) / 2;
/**
 * T02-S02 : largeur canonique du panneau `Type=Numeric wheel` (`144`,
 * CE-T01-14/D-104) — « largeur déterminée par deux cibles tactiles de
 * largeur `48` et une colonne sélectionnée `56 × 34` centrée »
 * (`48 + 48 + 48 = 144`, `12 – Architecture technique.md`). La hauteur reste
 * dérivée (`53` + `minHeight 150` = `203`), jamais figée.
 */
const WHEEL_NUMERIC_WIDTH = dimensions.wheelPicker.numericWidth;

export type NumberWheelPickerProps = {
  value: number;
  /** Valide exactement la valeur actuellement centrée — jamais appelé pendant le défilement, ni par Annuler. */
  onValidate: (value: number) => void;
  /** Ferme sans rien modifier — le brouillon local est détruit avec le composant, la valeur validée précédente reste inchangée. */
  onCancel: () => void;
  accessibilityLabel: string;
  cancelAccessibilityLabel: string;
  validateAccessibilityLabel: string;
  testID?: string;
};

export function NumberWheelPicker(props: NumberWheelPickerProps) {
  if (Platform.OS === "ios") {
    return <NativeAppleNumberWheelPicker {...props} />;
  }
  return <LegacyNumberWheelPicker {...props} />;
}

/**
 * Roulette native SwiftUI (iOS uniquement) — `Host` + `Picker`
 * (`pickerStyle('wheel')`), une seule colonne, chaque option portant sa
 * valeur via `<SwiftUIText modifiers={[tag(valeur)]}>`. Même patron que
 * `NativeAppleDurationWheelPicker` (`DurationWheelPicker.tsx`), pas répété
 * en détail ici : zone roue en `minHeight` (jamais figée), surface opaque
 * blanche arrondie/bordée/ombrée, aucune fermeture par toucher d'un chiffre
 * ou de la zone sélectionnée.
 *
 * **Correction bloquante — visibilité des valeurs** (« CORRECTION
 * BLOQUANTE AVANT T01-S09 — VISIBILITÉ DES ROULETTES », 2026-09-05) : même
 * cause racine et même correction que `NativeAppleDurationWheelPicker`
 * (voir sa note de tête pour la justification complète) — chaque
 * `SwiftUIText` de la colonne porte désormais explicitement
 * `foregroundStyle(colors.textPrimary)`, jamais la couleur de premier plan
 * par défaut de SwiftUI (dynamique, non fiable derrière ce pont natif).
 */
function NativeAppleNumberWheelPicker({
  value,
  onValidate,
  onCancel,
  accessibilityLabel,
  cancelAccessibilityLabel,
  validateAccessibilityLabel,
  testID = "number-wheel-picker",
}: NumberWheelPickerProps) {
  // `useState(() => ...)` : initialisé UNE SEULE FOIS au montage — jamais
  // recalculé depuis `value` à un rendu ultérieur (brouillon local), même
  // patron que `DurationWheelPicker`.
  const [initial] = useState(() => WHEEL_NUMBER_MIN + clampIndex(value - WHEEL_NUMBER_MIN, WHEEL_NUMBER_MAX - WHEEL_NUMBER_MIN));
  const [draft, setDraft] = useState(initial);
  const draftRef = useRef(initial);

  function handleChange(next: number) {
    if (next === draftRef.current) {
      return;
    }
    draftRef.current = next;
    setDraft(next);
    Haptics.selectionAsync().catch(() => {});
  }

  function handleValidate() {
    onValidate(draftRef.current);
  }

  return (
    <View style={styles.nativeSurface} testID={testID}>
      <PickerToolbar
        onCancel={onCancel}
        onValidate={handleValidate}
        cancelAccessibilityLabel={cancelAccessibilityLabel}
        validateAccessibilityLabel={validateAccessibilityLabel}
      />
      <Host style={styles.nativeHost} matchContents>
        <SwiftUIPicker
          selection={draft}
          onSelectionChange={handleChange}
          modifiers={[pickerStyle("wheel"), frame({ width: 96 }), accessibilityLabelModifier(accessibilityLabel)]}
          testID="number-wheel-column"
        >
          {VALUES.map((item) => (
            <SwiftUIText key={item} modifiers={[tag(item), foregroundStyle(colors.textPrimary)]}>
              {String(item)}
            </SwiftUIText>
          ))}
        </SwiftUIPicker>
      </Host>
    </View>
  );
}

/** Même patron que `PickerToolbar` de `DurationWheelPicker.tsx` — voir la note de tête pour la justification de la duplication locale. */
function PickerToolbar({
  onCancel,
  onValidate,
  cancelAccessibilityLabel,
  validateAccessibilityLabel,
}: {
  onCancel: () => void;
  onValidate: () => void;
  cancelAccessibilityLabel: string;
  validateAccessibilityLabel: string;
}) {
  return (
    <View style={styles.toolbar} testID="number-wheel-toolbar">
      <Pressable
        onPress={onCancel}
        accessibilityRole="button"
        accessibilityLabel={cancelAccessibilityLabel}
        hitSlop={WHEEL_ACTION_HIT_SLOP}
        style={styles.actionCancel}
        testID="number-wheel-cancel"
      >
        <KodjoIcon
          name="wheel-action-cancel"
          size={WHEEL_ACTION_ICON}
          testID="number-wheel-cancel-icon"
        />
      </Pressable>
      <Pressable
        onPress={onValidate}
        accessibilityRole="button"
        accessibilityLabel={validateAccessibilityLabel}
        hitSlop={WHEEL_ACTION_HIT_SLOP}
        style={styles.actionValidate}
        testID="number-wheel-validate"
      >
        <KodjoIcon
          name="wheel-action-validate"
          size={WHEEL_ACTION_ICON}
          testID="number-wheel-validate-icon"
        />
      </Pressable>
    </View>
  );
}

/**
 * Chemin Android/web — `ScrollView` + détection `onScroll` (même patron que
 * `LegacyDurationWheelPicker`, pas répété en détail ici) : brouillon local
 * uniquement pendant le défilement/l'appui direct, validé uniquement par
 * Confirmer.
 */
function LegacyNumberWheelPicker({
  value,
  onValidate,
  onCancel,
  accessibilityLabel,
  cancelAccessibilityLabel,
  validateAccessibilityLabel,
  testID = "number-wheel-picker",
}: NumberWheelPickerProps) {
  const initialIndex = clampIndex(value - WHEEL_NUMBER_MIN, WHEEL_NUMBER_MAX - WHEEL_NUMBER_MIN);
  const [initial] = useState(() => initialIndex);
  const indexRef = useRef(initial);
  const scrollRef = useRef<ScrollView>(null);

  useEffect(() => {
    scrollRef.current?.scrollTo({ y: indexToOffset(initial, ITEM_HEIGHT), animated: false });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  function applyIndex(index: number) {
    if (index === indexRef.current) {
      return;
    }
    indexRef.current = index;
    Haptics.selectionAsync().catch(() => {});
  }

  function handleScroll(event: NativeSyntheticEvent<NativeScrollEvent>) {
    const index = offsetToIndex(
      event.nativeEvent.contentOffset.y,
      ITEM_HEIGHT,
      WHEEL_NUMBER_MAX - WHEEL_NUMBER_MIN,
    );
    applyIndex(index);
  }

  function align() {
    scrollRef.current?.scrollTo({ y: indexToOffset(indexRef.current, ITEM_HEIGHT), animated: true });
  }

  function handleItemPress(index: number) {
    applyIndex(index);
    align();
  }

  function handleValidate() {
    onValidate(WHEEL_NUMBER_MIN + indexRef.current);
  }

  return (
    <View style={styles.legacySurface} testID={testID}>
      <PickerToolbar
        onCancel={onCancel}
        onValidate={handleValidate}
        cancelAccessibilityLabel={cancelAccessibilityLabel}
        validateAccessibilityLabel={validateAccessibilityLabel}
      />
      <View style={styles.wheelArea}>
        <ScrollView
          ref={scrollRef}
          testID="number-wheel-column"
          style={styles.column}
          showsVerticalScrollIndicator={false}
          snapToInterval={ITEM_HEIGHT}
          decelerationRate="fast"
          scrollEventThrottle={16}
          onScroll={handleScroll}
          onMomentumScrollEnd={align}
          onScrollEndDrag={align}
          accessibilityRole="adjustable"
          accessibilityLabel={accessibilityLabel}
          accessibilityValue={{
            min: WHEEL_NUMBER_MIN,
            max: WHEEL_NUMBER_MAX,
            now: WHEEL_NUMBER_MIN + initial,
          }}
          onAccessibilityAction={(event) => {
            if (event.nativeEvent.actionName === "increment") {
              handleItemPress(Math.min(indexRef.current + 1, VALUES.length - 1));
            } else if (event.nativeEvent.actionName === "decrement") {
              handleItemPress(Math.max(indexRef.current - 1, 0));
            }
          }}
          accessibilityActions={[{ name: "increment" }, { name: "decrement" }]}
        >
          {VALUES.map((item, index) => (
            <Pressable
              key={item}
              style={styles.item}
              onPress={() => handleItemPress(index)}
              accessibilityRole="button"
              accessibilityLabel={String(item)}
              testID={`number-wheel-column-item-${item}`}
            >
              <Text style={styles.itemLabel}>{item}</Text>
            </Pressable>
          ))}
        </ScrollView>
        <WheelSelectionOverlay itemHeight={ITEM_HEIGHT} />
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  nativeSurface: {
    width: WHEEL_NUMERIC_WIDTH,
    backgroundColor: colors.background,
    borderRadius: 16,
    borderWidth: 1,
    borderColor: colors.border,
    elevation: 8,
    shadowColor: "#000000",
    shadowOffset: { width: 0, height: 4 },
    shadowOpacity: 0.16,
    shadowRadius: 12,
    paddingHorizontal: spacing[12],
    paddingBottom: spacing[8],
  },
  legacySurface: {
    backgroundColor: colors.background,
    borderRadius: 16,
    borderWidth: 1,
    borderColor: colors.border,
    elevation: 8,
    shadowColor: "#000000",
    shadowOffset: { width: 0, height: 4 },
    shadowOpacity: 0.16,
    shadowRadius: 12,
    paddingHorizontal: spacing[12],
    alignItems: "center",
  },
  toolbar: {
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "space-between",
    height: WHEEL_TOOLBAR_HEIGHT,
  },
  actionCancel: {
    width: WHEEL_ACTION_VISUAL_CIRCLE,
    height: WHEEL_ACTION_VISUAL_CIRCLE,
    borderRadius: WHEEL_ACTION_VISUAL_CIRCLE / 2,
    backgroundColor: colors.wheelActionCancelBackground,
    alignItems: "center",
    justifyContent: "center",
  },
  actionValidate: {
    width: WHEEL_ACTION_VISUAL_CIRCLE,
    height: WHEEL_ACTION_VISUAL_CIRCLE,
    borderRadius: WHEEL_ACTION_VISUAL_CIRCLE / 2,
    backgroundColor: colors.wheelActionValidateBackground,
    alignItems: "center",
    justifyContent: "center",
  },
  nativeHost: {
    alignSelf: "center",
    minHeight: WHEEL_CONTENT_MIN_HEIGHT,
  },
  wheelArea: {
    height: ITEM_HEIGHT * 3,
  },
  column: {
    height: ITEM_HEIGHT * 3,
  },
  item: {
    height: ITEM_HEIGHT,
    alignItems: "center",
    justifyContent: "center",
  },
  itemLabel: {
    ...type.metricPrimary,
    color: colors.textPrimary,
  },
});

import type { ReactNode } from "react";
import { Pressable, StyleSheet, Text, View } from "react-native";

import type { SessionSummary } from "@/domain/sessions/Session";
import {
  formatActivityCount,
  formatBodyZoneNamesSegment,
  formatCategoryNamesSegment,
  formatEstimatedDuration,
  formatTourCount,
} from "@/features/sessions/formatSessionSummary";
import { strings } from "@/shared/i18n";
import { CardTitleLine } from "@/shared/ui/CardTitleLine";
import { DisclosureControl } from "@/shared/ui/DisclosureControl";
import { KodjoIcon } from "@/shared/ui/KodjoIcon";
import { colors, fixedRadii, minTouchTarget, spacing, type } from "@/shared/ui/tokens";

export type SessionCardProps = {
  session: SessionSummary;
  /**
   * T01-S10 (CE-T01-S10-01) : appelé lorsque la zone principale de la carte
   * est activée — ouvre `Composition d'une séance` en MODIFICATION. Non
   * fourni : la zone principale reste non pressable (aucune route de
   * modification câblée — état T01-S06/S09).
   */
  onOpen?: () => void;
};

/**
 * Carte condensée d'une Séance active (T01-S06).
 *
 * Présentation pure : ne charge rien, n'appelle jamais `SessionService`.
 *
 * Le chevron et le bouton `Démarrer` sont visuellement présents — les
 * captures Catalogue (`catalogue-seances.png` et les autres cartes non
 * glissées de `catalogue-condense-actions.png`) les montrent tous les deux
 * sur chaque carte condensée, sans qu'aucune interaction n'ait eu lieu — ce
 * sont donc des éléments structurants de la carte, pas des révélations
 * d'interaction. Ils restent néanmoins désactivés dans cette sous-étape :
 * aucun écran de détail (déploiement) ni d'Exécution n'existe encore, donc
 * ni navigation, ni chargement de détail, ni callback métier n'y sont
 * câblés.
 *
 * Correction VISUAL tentative 2 (T01-S09, point B, commentaire de revue
 * 5551813745) :
 * - le nom et la ligne de synthèse reprennent exactement la hiérarchie
 *   typographique déjà établie pour `Boundary Activity`
 *   (`CompositionScreen.tsx` — `rowLabel`/`type.cardTitle` pour le titre,
 *   `boundaryRowSecondaryLine`/`type.caption` pour la ligne secondaire) —
 *   `summary` passe donc de `type.body` à `type.caption`, sans nouveau style ;
 * - une ligne Catégories/Zones corporelles (`tagLine`), absente depuis la
 *   base T01-S09, est restaurée sous le nom — n'est rendue que si au moins
 *   une Catégorie ou une Zone corporelle existe (état vide : aucune ligne,
 *   jamais une ligne visible vide).
 *
 * Correction VISUAL, 2e contre-recette (T01-S09, point A, commentaire de
 * revue 5551083690) :
 * - les noms de Catégories s'affichent désormais dans la couleur propre de
 *   la Séance (`session.color`, même valeur que `colorBar` ci-dessous) —
 *   jamais le segment Zones corporelles ni le séparateur, qui restent dans
 *   la couleur de texte secondaire par défaut ;
 * - le séparateur entre le groupe Catégories et le groupe Zones corporelles
 *   devient `" : "` (auparavant `" · "`, point médian) — rendu attendu par
 *   exemple « Cardio : Genoux, Dos » lorsque les deux groupes existent ;
 *   omis entièrement si l'un des deux groupes est vide (jamais un
 *   séparateur adjacent à un segment vide) ;
 * - `formatCategoryNamesSegment`/`formatBodyZoneNamesSegment`
 *   (`formatSessionSummary.ts`) fournissent chacun leur segment
 *   indépendamment, permettant ce rendu à deux couleurs via un `Text`
 *   imbriqué (RN concatène nativement le texte annoncé à l'accessibilité,
 *   aucun `accessibilityLabel` dédié n'est donc nécessaire).
 *
 * Correction VISUAL, 3e contre-recette (T01-S09, point A, commentaire de
 * revue faisant suite à `1f28a09`) — le chevron `Déployer` délègue désormais
 * entièrement à `DisclosureControl` (`@/shared/ui/DisclosureControl`),
 * l'instance partagée de `Controls / Disclosure — Source exact`
 * (`12 – Architecture technique.md`, `2537:1033`/`2537:1038`). La 2e
 * contre-recette avait réintégré un cadre visible, mais en réutilisant par
 * analogie le token `exerciseParameterRow.chevronBox`/`colors.tourSurface`
 * (« Forms / Select Field », fonction graphique distincte) et une opacité
 * `0.45` — la revue signale que ni ce fond ni cette opacité ne sont
 * documentés pour CE contrôle. `DisclosureControl` retire donc ces deux
 * emprunts non sourcés au profit des quatre valeurs canoniques vérifiées
 * (`colors.disclosureBackground`/`disclosureBorderCollapsed`/
 * `disclosureBorderExpanded`/`disclosureChevronCollapsed`,
 * `dimensions.catalogueDisclosure`). L'état initial condensé
 * (`expanded={false}`), la cible tactile `48 × 48` et l'état désactivé
 * restent inchangés — seuls conteneur et couleurs changent.
 *
 * Le corps de la carte n'est pas pressable : aucune route de modification
 * (`Composition d'une séance`) n'existe avant T01-S07.
 *
 * Alignement DSF 07/10/2026 (`DSF / Cards / Séance`, variante
 * `Contexte=Catalogue, État=Replié` `6214:3572`, D11) :
 * - la durée quitte la ligne de synthèse pour la ligne de titre, sans cadre,
 *   calée à droite à 16 du bord de la carte (`CardTitleLine`) ; son calcul
 *   et son format (`formatEstimatedDuration`, préfixe « ≥ ») sont inchangés ;
 * - la ligne de titre occupe toute la largeur de la colonne de texte (322 à
 *   la largeur de référence) ; Déployer et Démarrer restent en bas à droite ;
 * - conteneur : fond `color/surface-subtle`, contour 0,5 `color/cards/border`,
 *   rayon 8 (`component/cards/radius`).
 * Le chevron de déploiement est conservé (annexe I.3).
 */
export function SessionCard({ session, onOpen }: SessionCardProps) {
  // PRE-3 : symbole issu du résultat typé de l'autorité Domaine (exact / ≈ / ≥).
  const duration = formatEstimatedDuration(
    session.estimatedDurationSeconds,
    session.durationKind ?? session.isEstimatedDurationApproximate,
  );
  const summaryLine = [
    formatActivityCount(session.activityCount),
    formatTourCount(session.tourRepeatCount),
  ].join(" · ");
  const categoriesSegment = formatCategoryNamesSegment(session.categoryNames);
  const zonesSegment = formatBodyZoneNamesSegment(session.bodyZoneNames);
  const hasTagLine = categoriesSegment !== null || zonesSegment !== null;

  return (
    <View style={styles.container}>
      <View
        style={[styles.colorBar, { backgroundColor: session.color }]}
        testID="session-card-color-bar"
      />
      <View style={styles.body}>
        <SessionCardMainArea onOpen={onOpen}>
          <CardTitleLine title={session.name} duration={duration} testID="session-card" />
          {hasTagLine ? (
            <Text style={styles.tagLine} numberOfLines={1} testID="session-card-tag-line">
              {categoriesSegment !== null ? (
                <Text
                  style={{ color: session.color }}
                  testID="session-card-tag-line-categories"
                >
                  {categoriesSegment}
                </Text>
              ) : null}
              {categoriesSegment !== null && zonesSegment !== null ? " : " : null}
              {zonesSegment}
            </Text>
          ) : null}
          <Text style={styles.summary}>{summaryLine}</Text>
        </SessionCardMainArea>
        <View style={styles.actions} pointerEvents="box-none">
          <DisclosureControl
            expanded={false}
            disabled
            accessibilityLabel={strings.screens.sessions.card.expandAccessibilityLabel}
            testID="session-card-disclosure"
          />
          <Pressable
            disabled
            accessibilityRole="button"
            accessibilityState={{ disabled: true }}
            accessibilityLabel={strings.screens.sessions.card.startAccessibilityLabel}
            style={styles.startButton}
          >
            <KodjoIcon name="action-start" opacity={0.55} testID="session-card-start" />
          </Pressable>
        </View>
      </View>
    </View>
  );
}

/**
 * Zone principale de la carte (nom + ligne de tags + synthèse). T01-S10
 * (CE-T01-S10-01) : `Pressable` avec un rôle `button` explicite lorsque
 * `onOpen` est fourni — elle ouvre `Composition d'une séance` en
 * modification. Sans `onOpen`, elle reste un simple `View` non interactif
 * (comportement T01-S06/S09 : « le corps de la carte n'est pas pressable »).
 * Le chevron et `Démarrer` restent des contrôles distincts, hors de cette
 * zone.
 */
function SessionCardMainArea({
  onOpen,
  children,
}: {
  onOpen?: () => void;
  children: ReactNode;
}) {
  if (!onOpen) {
    return <View style={styles.content}>{children}</View>;
  }
  return (
    <Pressable
      onPress={onOpen}
      accessibilityRole="button"
      accessibilityLabel={strings.screens.sessions.card.openAccessibilityLabel}
      style={styles.content}
      testID="session-card-open"
    >
      {children}
    </Pressable>
  );
}

/** Largeur réservée aux actions Déployer/Démarrer, depuis le bord droit de la colonne de texte. */
const LOWER_LINES_ACTION_RESERVE = 2 * minTouchTarget + spacing[2] - spacing[16];

const styles = StyleSheet.create({
  container: {
    flexDirection: "row",
    backgroundColor: colors.surfaceSubtle,
    borderWidth: 0.5,
    borderColor: colors.cardsBorder,
    borderRadius: fixedRadii[8],
    overflow: "hidden",
  },
  colorBar: {
    alignSelf: "stretch",
    width: 4,
  },
  // Colonne de la carte : zone principale (titre/durée pleine largeur, puis
  // classement et synthèse) ; les actions se superposent en bas à droite
  // sans réduire la ligne de titre.
  // `minHeight` : hauteur de la variante Figma (90), qui garantit que les
  // actions (48, ancrées en bas) ne recouvrent jamais la ligne de titre ;
  // la carte grandit avec le texte (police agrandie).
  body: {
    flex: 1,
    minHeight: 90,
  },
