import { createContext, useContext } from "react";

import type { SessionDraft } from "@/domain/sessions/SessionDraft";

/**
 * Contrat React pur du brouillon de Composition (T01-S07 ; T01-S10 :
 * distinction création / modification), sur le même patron que
 * `SessionServiceContext.tsx` (T01-S05) : aucune dépendance SQLite/Repository
 * ici — l'état réel (et sa construction) vit dans `SessionDraftProvider.tsx`.
 */

/**
 * Statut de la (ré)hydratation d'un brouillon de MODIFICATION (T01-S10,
 * CE-T01-S10-01/02/09) :
 * - `"creating"` : aucune Séance source — parcours de création classique ;
 * - `"loading"` : lecture de la Séance persistée en cours ;
 * - `"ready"` : brouillon disponible (vide en création, réhydraté en
 *   modification) ;
 * - `"not-found"` : identifiant inconnu — retour sûr au Catalogue ;
 * - `"archived"` : Séance archivée — aucun brouillon modifiable ;
 * - `"error"` : échec technique de lecture — retry possible.
 */
export type SessionDraftEditStatus =
  | "creating"
  | "loading"
  | "ready"
  | "not-found"
  | "archived"
  | "error";

export type SessionDraftContextValue = {
  readonly draft: SessionDraft;
  /** Fusionne les champs fournis dans le brouillon courant — jamais un remplacement complet. */
  readonly updateDraft: (patch: Partial<SessionDraft>) => void;
  /** Ramène le brouillon à `createEmptyDraft()`. */
  readonly resetDraft: () => void;
  /**
   * T01-S10 : statut de réhydratation courant. Champs optionnels de
   * transition (livraison séquencée) — `SessionDraftProvider` les fournit
   * toujours ; un consommateur lit `editStatus ?? "creating"` et appelle
   * `hydrateFromSession?.(...)`.
   */
  readonly editStatus?: SessionDraftEditStatus;
  /**
   * T01-S10 : (ré)hydrate le brouillon depuis une Séance persistée. `null`
   * (ré)initialise un brouillon de création. Idempotent sur un même
   * `sessionId` déjà chargé ; un changement d'identifiant repart d'un
   * brouillon vierge et invalide toute réponse en vol de l'ancien.
   */
  readonly hydrateFromSession?: (sessionId: string | null) => void;
  /** T01-S10 : relance la dernière réhydratation ayant échoué (`"error"`). */
  readonly retryHydration?: () => void;
  /**
   * T01-S10 (CE-T01-S10-06) : brouillon TEL QU'IL A ÉTÉ RÉHYDRATÉ depuis la
   * Séance persistée, ou `null` en création / avant réhydratation. Sert de
   * référence à la garde de sortie en modification — le dialogue d'abandon
   * n'apparaît que si le brouillon courant en diffère.
   */
  readonly hydratedBaseline?: SessionDraft | null;
  /**
   * V2-PRE-2 (plan §6.1/§7, T18) : brouillon de CRÉATION tel qu'il a été
   * RÉELLEMENT initialisé (valeurs du Profil au moment de la création,
   * snapshot atomique) — sert de référence à `isSessionDraftDirty` en
   * création, exactement comme `hydratedBaseline` sert de référence en
   * modification. Toujours `createEmptyDraft()` (constantes du Domaine) tant
   * que le Profil n'a pas encore été lu (T19).
   */
  readonly creationBaseline?: SessionDraft;
};

export const SessionDraftContext = createContext<SessionDraftContextValue | null>(null);

/** Lève une erreur explicite si utilisé hors d'un `SessionDraftProvider`. */
export function useSessionDraft(): SessionDraftContextValue {
  const value = useContext(SessionDraftContext);
  if (!value) {
    throw new Error("useSessionDraft must be used within a SessionDraftProvider.");
  }
  return value;
}

import {
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";

import {
  createEmptyDraft,
  sessionDraftsEqual,
  toSessionDraft,
  type SessionDraft,
  type SessionDraftDefaults,
} from "@/domain/sessions/SessionDraft";
import { ProfileServiceContext } from "@/features/preferences/ProfileServiceContext";
import {
  SessionDraftContext,
  type SessionDraftContextValue,
  type SessionDraftEditStatus,
} from "@/features/sessions/SessionDraftContext";
import { SessionServiceContext } from "@/features/sessions/SessionServiceContext";

export type SessionDraftProviderProps = {
  children: ReactNode;
};

/**
 * État réel du brouillon de Composition (T01-S07 ; T01-S10 : mode
 * modification). Un unique `useState` local, initialisé à
 * `createEmptyDraft()`. `updateDraft`/`resetDraft`/`hydrateFromSession`/
 * `retryHydration` restent des références stables (`useCallback` sans
 * dépendance variable — l'état lu est passé par ref) : condition nécessaire
 * pour que `useCompositionExitGuard` (qui reçoit `resetDraft`) et l'effet de
 * réhydratation de la route ne resouscrivent / ne rebouclent pas.
 *
 * Monté par `app/(creation)/_layout.tsx`, au-dessus d'un `Stack` imbriqué :
 * le brouillon survit à toute navigation entre écrans enfants de ce `Stack`.
 *
 * **Modification (T01-S10, CE-T01-S10-01/02/09)** : `hydrateFromSession(id)`
 * lit la Séance persistée via `SessionService.getSessionForEdit` (lecture
 * seule, jamais d'écriture à l'ouverture) et remplace le brouillon par
 * `toSessionDraft(session)`. Une réponse asynchrone dont l'identifiant n'est
 * plus l'identifiant courant est ignorée (garde par numéro de requête
 * monotone) : le brouillon d'une nouvelle Séance n'est jamais écrasé par la
 * réponse tardive d'une ancienne. `hydrateFromSession(null)` (ré)initialise
 * un brouillon de création. Le `SessionService` est facultatif ici (le
 * parcours de création n'en a pas besoin) : en son absence, une demande de
 * réhydratation échoue proprement en `"error"`.
 *
 * **V2-PRE-2 (plan §6.1/§6.3, D-213)** : un nouveau brouillon de CRÉATION
 * reçoit Compte à rebours initial et Fin de séance depuis la valeur
 * COURANTE du Profil, lue une seule fois (`ProfileService`, facultatif —
 * en son absence, T19, les constantes du Domaine s'appliquent inchangées).
 * `creationBaseline` expose le brouillon RÉELLEMENT créé, pour que la garde
 * de sortie compare le brouillon courant à ses valeurs initiales réelles
 * (T18), jamais aux constantes du Domaine si le Profil en diffère.
 */
export function SessionDraftProvider({ children }: SessionDraftProviderProps) {
  const service = useContext(SessionServiceContext);
  const serviceRef = useRef(service);
  useEffect(() => {
    serviceRef.current = service;
  }, [service]);

  const profileService = useContext(ProfileServiceContext);
  const sessionDefaultsRef = useRef<SessionDraftDefaults>({});

  const [draft, setDraft] = useState<SessionDraft>(() => createEmptyDraft());
  const [creationBaseline, setCreationBaseline] = useState<SessionDraft>(() => createEmptyDraft());
  const [editStatus, setEditStatusState] = useState<SessionDraftEditStatus>("creating");
  const [hydratedBaseline, setHydratedBaseline] = useState<SessionDraft | null>(null);

  // Numéro de requête monotone : seule la réponse de la requête la plus
  // récente est appliquée (garde anti-brouillon-contaminé).
  const requestSeq = useRef(0);
  const currentSessionId = useRef<string | null>(null);
  const statusRef = useRef<SessionDraftEditStatus>("creating");

  const setEditStatus = useCallback((next: SessionDraftEditStatus) => {
    statusRef.current = next;
    setEditStatusState(next);
  }, []);

  const updateDraft = useCallback((patch: Partial<SessionDraft>) => {
    setDraft((current) => ({ ...current, ...patch }));
  }, []);

  const resetDraft = useCallback(() => {
    requestSeq.current += 1;
    currentSessionId.current = null;
    const fresh = createEmptyDraft(sessionDefaultsRef.current);
    setDraft(fresh);
    setCreationBaseline(fresh);
    setHydratedBaseline(null);
    setEditStatus("creating");
  }, [setEditStatus]);

  const runHydration = useCallback(
    (sessionId: string) => {
      const seq = (requestSeq.current += 1);
      setEditStatus("loading");

      const activeService = serviceRef.current;
      if (!activeService) {
        setEditStatus("error");
        return;
      }

      activeService
        .getSessionForEdit(sessionId)
        .then((result) => {
          if (seq !== requestSeq.current) {
            return; // Réponse obsolète : un autre identifiant a pris la main.
          }
          if (result.status === "NOT_FOUND") {
            setEditStatus("not-found");
            return;
          }
          if (result.status === "ARCHIVED") {
            setEditStatus("archived");
            return;
          }
          const hydrated = toSessionDraft(result.session);
          setDraft(hydrated);
          setHydratedBaseline(hydrated);
          setEditStatus("ready");
        })
        .catch(() => {
          if (seq !== requestSeq.current) {
            return;
          }
          setEditStatus("error");
        });
    },
    [setEditStatus],
  );

  const hydrateFromSession = useCallback(
    (sessionId: string | null) => {
      if (sessionId === null) {
        if (currentSessionId.current === null && statusRef.current === "creating") {
          return; // Déjà en création vierge : aucun effet.
        }
        resetDraft();
        return;
      }
      if (
        sessionId === currentSessionId.current &&
        (statusRef.current === "ready" || statusRef.current === "loading")
      ) {
        return; // Déjà chargé / en cours pour ce même identifiant.
      }
      currentSessionId.current = sessionId;
      // Aucun brouillon obsolète affiché pendant le chargement.
      setDraft(createEmptyDraft());
      setHydratedBaseline(null);
      runHydration(sessionId);
    },
    [resetDraft, runHydration],
  );

  const retryHydration = useCallback(() => {
    if (currentSessionId.current !== null) {
      runHydration(currentSessionId.current);
    }
  }, [runHydration]);

  // V2-PRE-2 (D-213) : lu une seule fois par montage de ce fournisseur — un
  // changement ultérieur du Profil n'affecte jamais un brouillon déjà
  // initialisé (« sans rétroactivité »). N'applique les valeurs lues que si
  // le brouillon courant est encore le brouillon de création VIERGE (jamais
  // sur un brouillon de modification réhydraté, ni sur un brouillon de
  // création déjà modifié par l'utilisateur).
  useEffect(() => {
    if (!profileService) {
      return;
    }
    let cancelled = false;
    profileService.getProfile().then(
      (profile) => {
        if (cancelled) {
          return;
        }
        const defaults: SessionDraftDefaults = {
          initialCountdownSeconds: profile.sessionInitialCountdownSecondsDefault,
          finalPhaseSeconds: profile.sessionFinalPhaseSecondsDefault,
        };
        sessionDefaultsRef.current = defaults;
        if (statusRef.current === "creating" && currentSessionId.current === null) {
          const fresh = createEmptyDraft(defaults);
          setDraft((current) => (sessionDraftsEqual(current, createEmptyDraft()) ? fresh : current));
          setCreationBaseline(fresh);
        }
      },
      (error: unknown) => {
        if (!cancelled) {
          console.error("Impossible de charger les valeurs initiales du Profil.", error);
        }
      },
    );
    return () => {
      cancelled = true;
    };
  }, [profileService]);

  const value = useMemo<SessionDraftContextValue>(
    () => ({
      draft,
      updateDraft,
      resetDraft,
      editStatus,
      hydrateFromSession,
      retryHydration,
      hydratedBaseline,
      creationBaseline,
    }),
    [
      draft,
      updateDraft,
      resetDraft,
      editStatus,
      hydrateFromSession,
      retryHydration,
      hydratedBaseline,
      creationBaseline,
    ],
  );

  return <SessionDraftContext.Provider value={value}>{children}</SessionDraftContext.Provider>;
}

/**
 * Orchestration applicative du cycle de vie de la Séance (T01-S03, §12.4).
 *
 * Ne dépend que du Domaine (`@/domain/sessions/*`) et de l'interface
 * `SessionRepository` — jamais de React, Expo, React Native ou d'une
 * implémentation concrète du Repository (injectée par le constructeur).
 *
 * `createSession` ne capture ni ne transforme les erreurs du Repository :
 * un brouillon invalide produit un résultat structuré par valeur (aucune
 * écriture tentée), tandis qu'une erreur du Repository — technique, ou
 * `SessionValidationError` en défense de dernier recours — se propage
 * telle quelle, sans être confondue avec ce résultat structuré.
 */

import type { Session, SessionSummary } from "@/domain/sessions/Session";
import {
  toCreateSessionInput,
  toUpdateSessionInput,
  type SessionDraft,
} from "@/domain/sessions/SessionDraft";
import type { ValidationResult, ValidationViolation } from "@/domain/sessions/errors";
import type { SessionRepository } from "@/domain/sessions/SessionRepository";

/**
 * Résultat de la création d'une Séance : succès avec la Séance persistée,
 * ou échec avec la liste structurée des violations (mêmes codes/champs que
 * le Domaine, aucun message traduit). Alias direct du contrat du Domaine.
 */
export type CreateSessionResult = ValidationResult<Session>;

/**
 * Résultat métier discriminé d'une tentative de modification. Reprend les
 * trois issues déjà connues du Repository (`UPDATED`/`NOT_FOUND`/`ARCHIVED`)
 * et y ajoute la seule branche que le Repository ne connaît pas : un
 * brouillon invalide (`INVALID`), tranchée avant même d'atteindre le
 * Repository.
 */
export type UpdateSessionResult =
  | { readonly status: "UPDATED"; readonly session: Session }
  | { readonly status: "INVALID"; readonly violations: readonly ValidationViolation[] }
  | { readonly status: "NOT_FOUND" }
  | { readonly status: "ARCHIVED" };

/**
 * Résultat de l'ouverture d'une Séance en MODIFICATION (T01-S10). Une Séance
 * archivée ne produit jamais de brouillon modifiable (§3.1) ; une Séance
 * introuvable non plus. Une erreur technique du Repository se propage
 * (jamais confondue avec `NOT_FOUND`).
 */
export type LoadSessionForEditResult =
  | { readonly status: "OK"; readonly session: Session }
  | { readonly status: "NOT_FOUND" }
  | { readonly status: "ARCHIVED" };

export class SessionService {
  /**
   * `categoryRepository` (T01-S09) n'a plus aucun consommateur depuis le
   * retrait de la relation historique Catégorie de Séance (V2-PRE-1, plan
   * §3.3) — le DEUXIÈME paramètre du constructeur est néanmoins PRÉSERVÉ
   * (type et position inchangés) pour ne jamais rompre la composition
   * existante de `SessionServiceProvider.tsx` (hors périmètre d'écriture de
   * cette tranche, `scope_allow`), qui construit encore
   * `new SessionService(sessionRepository, categoryRepository)`.
   *
   * **V2-PRE-2 (plan §6.3)** : chaque occurrence porte déjà sa propre
   * `postActivityRecoverySeconds`, copiée du Profil au moment de sa
   * création réelle (`ActivitySelectionScreen`, `ExerciseScreen` local) —
   * `createSession` ne la relit ni ne l'écrase plus jamais depuis le Profil
   * (abroge l'écrasement V2-PRE-1 : « sans rétroactivité »).
   */
  constructor(
    private readonly sessionRepository: SessionRepository,
    _categoryRepository?: unknown,
  ) {}

  /**
   * Convertit le brouillon via `toCreateSessionInput` (Domaine). En cas
   * d'échec, aucune tentative d'écriture n'est faite : le résultat
   * structuré est renvoyé tel quel. En cas de succès, délègue la
   * persistance à `SessionRepository.create`, sans jamais altérer les
   * valeurs déjà portées par chaque occurrence du brouillon.
   */
  async createSession(draft: SessionDraft): Promise<CreateSessionResult> {
    const validated = toCreateSessionInput(draft);
    if (!validated.ok) {
      return validated;
    }

    const session = await this.sessionRepository.create(validated.value);
    return { ok: true, value: session };
  }

  /**
   * Modification bout en bout d'une Séance persistée (T01-S10, Q3-A). Le
   * `sessionId` transmis EST l'identifiant source : il prime sur
   * `draft.sourceSessionId` (fixé ici avant conversion). Convertit le
   * brouillon via `toUpdateSessionInput` (jamais `toCreateSessionInput` —
   * `create()` n'est jamais appelé en modification). En cas d'échec de
   * validation, aucune tentative d'appel au Repository : un résultat
   * `INVALID` est renvoyé immédiatement. En cas de succès, délègue à
   * `SessionRepository.update` et renvoie son résultat
   * (`UPDATED`/`NOT_FOUND`/`ARCHIVED`) tel quel. Aucune erreur du Repository
   * n'est interceptée ni transformée.
   */
  async updateSession(sessionId: string, draft: SessionDraft): Promise<UpdateSessionResult> {
    const validated = toUpdateSessionInput({ ...draft, sourceSessionId: sessionId });
    if (!validated.ok) {
      return { status: "INVALID", violations: validated.violations };
    }

    return this.sessionRepository.update(sessionId, validated.value);
  }

  /**
   * Séances actives pour le futur Catalogue, déjà enrichies par le
   * Repository (Nombre d'Activités, Durée estimée) via les fonctions du
   * Domaine. Aucune transformation supplémentaire ici.
   */
  async listActiveSessions(): Promise<readonly SessionSummary[]> {
    return this.sessionRepository.listActive();
  }

  /**
   * Séance complète par identifiant. `null` si l'identifiant n'existe
   * pas — aucune exception levée pour ce cas attendu.
   */
  async getSession(sessionId: string): Promise<Session | null> {
    return this.sessionRepository.findById(sessionId);
  }

  /**
   * Ouvre une Séance en MODIFICATION (T01-S10, CE-T01-S10-01/02). Lecture
   * seule : aucune écriture. Distingue `NOT_FOUND` d'`ARCHIVED` via le
   * statut brut avant tout assemblage d'agrégat. Une erreur technique du
   * Repository se propage telle quelle.
   */
  async getSessionForEdit(sessionId: string): Promise<LoadSessionForEditResult> {
    const status = await this.sessionRepository.findSessionStatus(sessionId);
    if (status === null) {
      return { status: "NOT_FOUND" };
    }
    if (status === "ARCHIVED") {
      return { status: "ARCHIVED" };
    }
    const session = await this.sessionRepository.findById(sessionId);
    if (!session) {
      return { status: "NOT_FOUND" };
    }
    return { status: "OK", session };
  }
}

import { createContext, useContext } from "react";

import type { SessionService } from "@/features/sessions/SessionService";

/**
 * Contrat React pur d'exposition de `SessionService` : aucun import
