import { DATABASE_NAME } from "@/infrastructure/database/constants";
import { ExpoDatabase } from "@/infrastructure/database/ExpoDatabase";
import { initializeDatabase } from "@/infrastructure/database/initializeDatabase";
import { SqliteActivityDefinitionRepository } from "@/infrastructure/database/repositories/SqliteActivityDefinitionRepository";
import { SqliteBodyZoneRepository } from "@/infrastructure/database/repositories/SqliteBodyZoneRepository";
import { SqliteCategoryRepository } from "@/infrastructure/database/repositories/SqliteCategoryRepository";
import { SqliteLabelRepository } from "@/infrastructure/database/repositories/SqliteLabelRepository";
import { SqliteMediaRepository } from "@/infrastructure/database/repositories/SqliteMediaRepository";
import { SqliteProfileRepository } from "@/infrastructure/database/repositories/SqliteProfileRepository";
import { SqliteSessionRepository } from "@/infrastructure/database/repositories/SqliteSessionRepository";
import { ActivityDefinitionService } from "@/features/activities/ActivityDefinitionService";
import { ActivityDefinitionServiceProvider } from "@/features/activities/ActivityDefinitionServiceProvider";
import { ProfileService } from "@/features/preferences/ProfileService";
import { ProfileServiceContext } from "@/features/preferences/ProfileServiceContext";
import { ReferentialService } from "@/features/reference-data/ReferentialService";
import { ReferentialServiceContext } from "@/features/reference-data/ReferentialServiceContext";
import { SessionServiceContext } from "@/features/sessions/SessionServiceContext";
import { SessionService } from "@/features/sessions/SessionService";
import { ActivityMediaImportService } from "@/domain/media/ActivityMediaImportService";
import { getLocalMediaStore } from "@/infrastructure/media/LocalMediaStore";
import { PhotoLibraryPicker } from "@/infrastructure/media/PhotoLibraryPicker";

/**
 * Câblage réel `expo-sqlite → ExpoDatabase → SqliteSessionRepository →
 * SessionService`. Seul fichier de la feature à importer `expo-sqlite` —
 * voir `SessionServiceContext.tsx` pour le contrat React pur.
 *
 * **Architecture corrigée (T01-S05, suite à contre-vérification)** :
 * `SQLiteProvider` (expo-sqlite) est mémoïsé (`React.memo`) avec un
 * comparateur qui ignore délibérément `children`
 * (`node_modules/expo-sqlite/src/hooks.tsx`). Tout `children` qui varie
 * d'un rendu à l'autre — typiquement le `<Stack>` applicatif de
 * `app/_layout.tsx`, conditionné par `fontsSettled` — serait donc
 * silencieusement absorbé s'il transitait par lui : une fois le premier
 * rendu passé (où `children` valait encore `null`), plus aucune mise à jour
 * de ce `children` n'atteindrait l'arbre réel, laissant l'application vide
 * indéfiniment après la disparition du splash.
 *
 * `SQLiteProvider` ne reçoit donc ici qu'un unique enfant interne
 * strictement stable, `SessionServiceInitializer`, dont les props ne
 * varient jamais au fil des rendus de `SessionServiceProvider` — son
 * bail-out mémoïsé reste ainsi sans conséquence. Le `children` applicatif
 * réel ne traverse jamais `SQLiteProvider` : il est enveloppé directement
 * par `SessionServiceContext.Provider` (notre propre composant, non
 * mémoïsé), rendu en dehors de `SQLiteProvider`, donc toujours à jour.
 *
 * **V2-PRE-2 (plan §6.3)** : `ProfileService` et `ReferentialService` sont
 * construits ici, sur la MÊME connexion SQLite que `SessionService` —
 * aucune seconde connexion, aucun second cycle de migration (rationale
 * d'injection SQLite déjà établie par `ActivityDefinitionService`).
 */

/**
 * Référence de niveau module, donc stable entre rendus — condition exigée
 * par `SQLiteProvider` (`onInit`/`onError` doivent rester des références
 * stables pour ne pas rouvrir la base à chaque rendu). Pose les pragmas
 * canoniques puis exécute la migration (idempotente) avant que
 * `SQLiteProvider` ne rende le moindre enfant.
 */
async function onDatabaseInit(nativeDatabase: SQLiteDatabase): Promise<void> {
  await initializeDatabase(new ExpoDatabase(nativeDatabase));
}

export type SessionServiceProviderProps = {
  children: ReactNode;
  /**
   * Appelé une fois la base ouverte, migrée et le service construit.
   * Idempotent par nature : plusieurs appels successifs (par exemple lors
   * d'un remontage en développement) n'ont aucun effet observable au-delà
   * du premier signal de disponibilité.
   */
  onReady?: () => void;
};

type SessionServiceInitializerProps = {
  /** Remonte l'instance construite ; ne reçoit jamais de forme différente. */
  onServiceReady: (service: SessionService) => void;
  /**
   * V2-CAT-01 : remonte `ActivityDefinitionService`, construit à partir de
   * la MÊME connexion SQLite que `SessionService` (rationale d'injection
   * SQLite du plan) — aucune seconde connexion, aucun second cycle de
   * migration.
   */
  onActivityDefinitionServiceReady: (service: ActivityDefinitionService) => void;
  /** V2-PRE-2 : remonte `ProfileService`, même connexion SQLite. */
  onProfileServiceReady: (service: ProfileService) => void;
  /** V2-PRE-2 : remonte `ReferentialService`, même connexion SQLite. */
  onReferentialServiceReady: (service: ReferentialService) => void;
};

/**
 * Unique enfant de `SQLiteProvider`. Ses props (`onServiceReady`) sont
 * garanties référentiellement stables par `SessionServiceProvider`
 * ci-dessous : `SQLiteProvider` ne reçoit donc jamais de `children`
 * différent d'un rendu à l'autre, et son bail-out mémoïsé (comparateur qui
 * ignore `children`) n'a alors aucune conséquence observable. Ne rend rien
 * visuellement — son seul rôle est de construire les services (mémoïsés sur
 * la connexion native stable) et de signaler leur disponibilité.
 */
function SessionServiceInitializer({
  onServiceReady,
  onActivityDefinitionServiceReady,
  onProfileServiceReady,
  onReferentialServiceReady,
}: SessionServiceInitializerProps) {
  const nativeDatabase = useSQLiteContext();

  const sessionService = useMemo(() => {
    const database = new ExpoDatabase(nativeDatabase);
    return new SessionService(new SqliteSessionRepository(database), new SqliteCategoryRepository(database));
  }, [nativeDatabase]);

  // Correction (device check Hermann, commentaire 5948936550 ; revue
  // indépendante 5950755410) : CategoryRepository, BodyZoneRepository et
  // LabelRepository étaient omis ici, laissant `listCategories()`/
  // `listBodyZones()`/`listLabels()` lever systématiquement — le sélecteur
  // de Catégorie restait vide, chaque écran consommant les Zones (Catalogue,
  // Composition, Sélection, éditeur d'Activité) dégradait silencieusement
  // vers un référentiel VIDE, et la couleur d'une Séance Étiquetée restait
  // la présentation neutre, en production. Même connexion `database` que les
  // autres Repository, aucune seconde connexion ni second cycle de
  // migration.
  const activityDefinitionService = useMemo(() => {
    const database = new ExpoDatabase(nativeDatabase);
    return new ActivityDefinitionService(
      new SqliteActivityDefinitionRepository(database),
      new SqliteCategoryRepository(database),
      new SqliteBodyZoneRepository(database),
      new SqliteLabelRepository(database),
      // PRE-3 (D-333/D-334) : adaptateurs médias — photothèque seule, copie
      // interne stable, lecture des références sur la MÊME connexion.
      {
        importService: new ActivityMediaImportService(new PhotoLibraryPicker(), getLocalMediaStore(), () => Crypto.randomUUID()),
        repository: new SqliteMediaRepository(database),
      },
    );
  }, [nativeDatabase]);

  const profileService = useMemo(() => {
    const database = new ExpoDatabase(nativeDatabase);
    return new ProfileService(new SqliteProfileRepository(database));
  }, [nativeDatabase]);

  const referentialService = useMemo(() => {
    const database = new ExpoDatabase(nativeDatabase);
    return new ReferentialService(
      new SqliteCategoryRepository(database),
      new SqliteBodyZoneRepository(database),
      new SqliteLabelRepository(database),
    );
  }, [nativeDatabase]);

  useEffect(() => {
    onServiceReady(sessionService);
  }, [sessionService, onServiceReady]);

  useEffect(() => {
    onActivityDefinitionServiceReady(activityDefinitionService);
  }, [activityDefinitionService, onActivityDefinitionServiceReady]);

  useEffect(() => {
    onProfileServiceReady(profileService);
  }, [profileService, onProfileServiceReady]);

  useEffect(() => {
    onReferentialServiceReady(referentialService);
  }, [referentialService, onReferentialServiceReady]);

  return null;
}

/**
 * Expose `SessionService` via `SessionServiceContext` dès qu'il est
 * construit, et relaie le `children` applicatif — qui peut varier
 * librement d'un rendu à l'autre (par ex. `null` puis `<Stack>` selon
 * `fontsSettled`) — sans jamais le faire transiter par `SQLiteProvider`.
 * L'état du service reste local à ce composant : `RootLayout` n'a besoin
 * que du signal booléen `onReady`, jamais de l'instance elle-même.
 */
export function SessionServiceProvider({ children, onReady }: SessionServiceProviderProps) {
  const [sessionService, setSessionService] = useState<SessionService | null>(null);
  const [activityDefinitionService, setActivityDefinitionService] =
    useState<ActivityDefinitionService | null>(null);
  const [profileService, setProfileService] = useState<ProfileService | null>(null);
  const [referentialService, setReferentialService] = useState<ReferentialService | null>(null);
  // V2-PRE-2 (plan §6.3) : `onReady` attend aussi le CHARGEMENT du Profil
  // (pas seulement la construction de `ProfileService`) — un échec de
  // lecture suit le traitement d'erreur déjà établi ailleurs dans le projet
  // pour cette même lecture (`console.error`, jamais un blocage indéfini de
  // l'ouverture de l'application).
  const [isProfileLoaded, setIsProfileLoaded] = useState(false);

  const handleServiceReady = useCallback((service: SessionService) => {
    setSessionService(service);
  }, []);

  const handleActivityDefinitionServiceReady = useCallback(
    (service: ActivityDefinitionService) => {
      setActivityDefinitionService(service);
    },
    [],
  );

  const handleProfileServiceReady = useCallback((service: ProfileService) => {
    setProfileService(service);
    service.getProfile().then(
      () => setIsProfileLoaded(true),
      (error: unknown) => {
        console.error("Le Profil n'a pas pu être chargé.", error);
        setIsProfileLoaded(true);
      },
    );
  }, []);

  const handleReferentialServiceReady = useCallback((service: ReferentialService) => {
    setReferentialService(service);
  }, []);

  // V2-PRE-2 (plan §6.3) : un seul signal `onReady`, une fois `SessionService`,
  // `ProfileService`, `ReferentialService` ET le Profil chargé — jamais dès
  // que `SessionService` seul est construit. Aucun écran n'est donc jamais
  // rendu avec un contexte Profil ou référentiel nul.
  useEffect(() => {
    if (sessionService && profileService && referentialService && isProfileLoaded) {
      onReady?.();
    }
  }, [sessionService, profileService, referentialService, isProfileLoaded, onReady]);

  return (
    <>
      <SQLiteProvider databaseName={DATABASE_NAME} onInit={onDatabaseInit}>
        <SessionServiceInitializer
          onServiceReady={handleServiceReady}
          onActivityDefinitionServiceReady={handleActivityDefinitionServiceReady}
          onProfileServiceReady={handleProfileServiceReady}
          onReferentialServiceReady={handleReferentialServiceReady}
        />
      </SQLiteProvider>
      <SessionServiceContext.Provider value={sessionService}>
        <ActivityDefinitionServiceProvider service={activityDefinitionService}>
          <ProfileServiceContext.Provider value={profileService}>
            <ReferentialServiceContext.Provider value={referentialService}>
              {children}
            </ReferentialServiceContext.Provider>
          </ProfileServiceContext.Provider>
        </ActivityDefinitionServiceProvider>
      </SessionServiceContext.Provider>
    </>
  );
}

import { Pressable, StyleSheet, Text, View } from "react-native";

import { cycleSideMode, type SideMode } from "@/domain/sessions/sideMode";
import { strings } from "@/shared/i18n";
import { colors, dimensions, minTouchTarget, spacing, type } from "@/shared/ui/tokens";

export type SideModeControlProps = {
  readonly value: SideMode;
  /** Reçoit directement la valeur SUIVANTE (`cycleSideMode(value)`, déjà calculée) — jamais l'appelant qui recalcule le cycle. */
  readonly onChange: (next: SideMode) => void;
  /**
   * Nom accessible COMPLET du contrôle, entièrement composé par l'appelant
   * (plan V2-BILAT-01, `## UI`) : l'Activité (`Côté : …`) et le Tour
   * (`Direction du Tour : …`) portent des textes distincts, jamais dérivés
   * ici — seules les valeurs VISIBLES (`D→G`/`G→D`/vide) sont partagées.
   */
  readonly accessibilityLabel: string;
  /**
   * Titre visible au-dessus du contrôle — `null` (défaut) omet entièrement
   * la ligne de titre. Le contrôle Tour n'affiche aucun titre (« Côté »/
   * « Côtés » proscrit par le plan pour ce contexte) ; le contrôle Activité
   * transmet `Côté`.
   */
  readonly title?: string | null;
  /**
   * Enfant `IN_TOUR` d'un Tour bilatéral (plan `## UI`, « enfant visible,
   * désactivé, proprement `UNILATERAL` ») : le contrôle reste visible mais
   * n'accepte plus aucun appui. `value` doit alors déjà valoir `UNILATERAL`
   * (remis par `applyTourSideModeTransition` au moment de l'activation) —
   * ce composant ne le force pas lui-même, il reste purement présentational.
   */
  readonly disabled?: boolean;
  /** Largeur locale du contrôle — `74` par défaut (Activité, `narrowColumnWidth`) ; le Tour transmet `42`. */
  readonly width?: number;
  /** Hauteur locale du contrôle — `42` par défaut (Activité, `controlHeight`) ; le Tour transmet `34`. */
  readonly height?: number;
  /**
   * Correction bornée (plan `## 3`, « Le contexte Tour est ajouté de manière
   * optionnelle ») : `false` par défaut — le rendu Activité, notamment
   * `UNILATERAL` visuellement VIDE, reste alors STRICTEMENT inchangé, tous
   * les appels Activité existants restant valides sans modification.
   * `true` (transmis uniquement par `CompositionScreen`) : `UNILATERAL`
   * affiche un tiret CENTRÉ (`strings.shared.sideMode.tour.valueLabels`)
   * plutôt qu'un affichage vide, et l'espacement interne du cadre est réduit
   * pour que `D→G`/`G→D` restent ENTIÈREMENT visibles dans la géométrie
   * locale `42 × 34` (jamais tronqués).
   */
  readonly isTourContext?: boolean;
  readonly testID?: string;
};

/**
 * Contrôle `Côté`/`Direction du Tour` (V2-BILAT-01, `sideMode.ts`) — un seul
 * appui fait AVANCER la direction d'un cran (`cycleSideMode` : `Unilatéral →
 * D→G → G→D → Unilatéral`), jamais un sélecteur à trois options distinctes.
 * Partagé par `ExerciseScreen` (Activité, ligne 2/colonne 1 de la grille de
 * paramètres, sous `Séries`) et `CompositionScreen` (Tour, immédiatement à
 * droite du sélecteur `Nombre de tours`) — un seul composant, jamais deux
 * copies locales pouvant diverger. Titre, nom accessible et géométrie sont
 * des props explicites (plan `## UI`, les deux contextes portant des textes
 * et des dimensions différents) ; seules les valeurs VISIBLES (`D→G`/`G→D`/
 * vide pour `UNILATERAL`) sont calculées ici, partagées par construction.
 *
 * Anatomie minimale, cohérente avec les contrôles compacts déjà établis
 * (`ParameterField` d'`ExerciseScreen.tsx`, `Nombre de tours` de
 * `CompositionScreen.tsx`) : libellé court optionnel au-dessus, valeur
 * affichée dans un cadre pressable en dessous. Aucune référence Figma dédiée
 * n'accompagne cette tranche (plan `V2-BILAT-01` — configuration préalable à
 * T03, hors recette visuelle) : la géométrie Activité réutilise donc des
 * tokens déjà canoniques (`dimensions.exerciseParameterRow`, revue
 * indépendante) plutôt que d'en publier de nouveaux ; la géométrie Tour
 * (`42 × 34`), elle, n'a pas d'équivalent canonique existant — écart
 * disclosé dans le rapport de mission.
 */
export function SideModeControl({
  value,
  onChange,
  accessibilityLabel,
  title = null,
  disabled = false,
  width = dimensions.exerciseParameterRow.narrowColumnWidth,
  height = dimensions.exerciseParameterRow.controlHeight,
  isTourContext = false,
  testID,
}: SideModeControlProps) {
  // Valeur VISIBLE : `RIGHT_LEFT`/`LEFT_RIGHT` affichent toujours `D→G`/
  // `G→D`, partagés entre Activité et Tour. `UNILATERAL` diverge SEUL selon
  // le contexte — vide pour l'Activité (comportement par défaut, INCHANGÉ),
  // tiret centré pour le Tour (`isTourContext`, plan `## 4.2`).
  const valueLabel = isTourContext
    ? strings.shared.sideMode.tour.valueLabels[value]
    : strings.shared.sideMode.valueLabels[value];

  function handlePress() {
    onChange(cycleSideMode(value));
  }

  return (
    <View style={styles.container} testID={testID}>
      {title !== null ? (
        <Text style={styles.label} numberOfLines={1}>
          {title}
        </Text>
      ) : null}
      <Pressable
        disabled={disabled}
        onPress={handlePress}
        accessibilityRole="button"
        accessibilityLabel={accessibilityLabel}
        accessibilityState={{ disabled }}
        hitSlop={hitSlopFor(height)}
        style={[
          styles.control,
          { width, height },
          // Espacement interne RÉDUIT pour le Tour (`42 × 34`, plan `## 3`,
          // « espacement interne réduit localement pour éviter la
          // troncature ») — jamais appliqué à l'Activité (`74 × 42`, marge
          // déjà suffisante), qui garde `styles.control.paddingHorizontal`.
          isTourContext ? styles.controlTourPadding : null,
          disabled ? styles.controlDisabled : null,
        ]}
        testID={testID ? `${testID}-control` : undefined}
      >
        <Text
          style={[styles.value, disabled ? styles.valueDisabled : null]}
          numberOfLines={1}
          testID={testID ? `${testID}-value` : undefined}
        >
          {valueLabel}
        </Text>
      </Pressable>
    </View>
  );
}

/** Complément vertical portant la cible tactile de `height` à `minTouchTarget` (`48`) — jamais négatif si `height` dépasse déjà ce minimum. */
function hitSlopFor(height: number) {
  const vertical = Math.max((minTouchTarget - height) / 2, 0);
  return { top: vertical, bottom: vertical, left: 0, right: 0 };
}

const styles = StyleSheet.create({
  container: {
    gap: dimensions.exerciseParameterRow.labelGap,
  },
  label: {
    ...type.parameterColumnLabel,
    color: colors.exerciseParameterLabelText,
  },
  control: {
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "center",
    backgroundColor: colors.background,
    borderWidth: 1,
    borderColor: colors.exerciseParameterControlBorder,
    borderRadius: dimensions.exerciseParameterRow.controlRadius,
    paddingHorizontal: spacing[12],
  },
  // Correction bornée (plan `## 3`) : `42 × 34` (Tour) ne laisse pas la
  // place du `paddingHorizontal` Activité (`spacing/12` de chaque côté,
  // `24` au total sur une largeur de `42`) sans tronquer `D→G`/`G→D` —
  // réduit au plus petit palier DSF non nul (`spacing/4`), jamais retiré
  // entièrement (le cadre resterait visuellement collé au texte).
  controlTourPadding: {
    paddingHorizontal: spacing[4],
  },
  controlDisabled: {
    opacity: 0.5,
  },
  value: {
    ...type.label,
    color: colors.exerciseParameterValueText,
  },
  valueDisabled: {
    color: colors.disabled,
  },
});

import { useCallback, useEffect, useRef, useState } from "react";

import { useSessionService } from "@/features/sessions/SessionServiceContext";
import type { SessionSummary } from "@/domain/sessions/Session";

/**
 * Hook de chargement pur du Catalogue (T01-S06). Ne connaît ni
 * `expo-router` ni la navigation : c'est l'appelant (`CatalogueScreen`) qui
 * décide quand déclencher `reload`/`cancelPending`, typiquement au focus et
 * au blur d'un `useFocusEffect`. N'importe ni `SqliteSessionRepository`, ni
 * `Database`, ni `expo-sqlite` — le seul point d'accès aux données est
 * `useSessionService()`.
 */
export type SessionCatalogueState =
  | { status: "loading" }
  | { status: "empty" }
  | { status: "ready"; sessions: readonly SessionSummary[] }
  | { status: "error"; error: unknown };

export type UseSessionCatalogueResult = {
  state: SessionCatalogueState;
  /** Démarre un nouveau chargement ; référence stable (`useCallback`). */
  reload: () => void;
  /**
   * Invalide toute requête actuellement en vol, sans en démarrer de
   * nouvelle : sa résolution ultérieure (succès ou échec) sera ignorée.
   * Référence stable (`useCallback`).
   */
  cancelPending: () => void;
};

export function useSessionCatalogue(): UseSessionCatalogueResult {
  const sessionService = useSessionService();
  const [state, setState] = useState<SessionCatalogueState>({ status: "loading" });

  // Identifiant de la dernière requête déclenchée : toute résolution dont
  // l'identifiant capturé ne correspond plus à cette valeur au moment où
  // elle arrive est ignorée — qu'elle soit périmée par un rechargement plus
  // récent (concurrence) ou invalidée explicitement par `cancelPending`
  // (blur). C'est la même garde dans les deux cas.
  const requestIdRef = useRef(0);

  // Garde de démontage. Réinitialisé DANS le corps de l'effet (pas dans
  // l'initialiseur de `useRef`) afin de redevenir correctement `true` lors
  // du remontage synthétique de React Strict Mode : `useRef(false)` ne
  // s'exécute qu'au tout premier rendu, alors que ce corps d'effet se
  // rejoue à chaque remontage — synthétique ou réel.
  const isMountedRef = useRef(false);
  useEffect(() => {
    isMountedRef.current = true;
    return () => {
      isMountedRef.current = false;
    };
  }, []);

  const cancelPending = useCallback(() => {
    requestIdRef.current += 1;
  }, []);

  const reload = useCallback(() => {
    const requestId = ++requestIdRef.current;
    setState({ status: "loading" });

    sessionService.listActiveSessions().then(
      (sessions) => {
        if (requestIdRef.current !== requestId || !isMountedRef.current) {
          return;
        }
        setState(
          sessions.length === 0 ? { status: "empty" } : { status: "ready", sessions },
        );
      },
      (error: unknown) => {
        if (requestIdRef.current !== requestId || !isMountedRef.current) {
          return;
        }
        // L'erreur réelle est journalisée pour le diagnostic technique ;
        // aucun détail technique n'est jamais exposé à l'utilisateur (même
        // principe que RootErrorBoundary/RootErrorFallback, T01-S05).
        console.error("Impossible de charger les séances actives.", error);
        setState({ status: "error", error });
      },
    );
  }, [sessionService]);

  return { state, reload, cancelPending };
}

import type { ReactNode } from "react";
import { Modal, StyleSheet, View } from "react-native";

import { colors } from "@/shared/ui/tokens";

export type WheelPickerOverlayProps = {
  /** Rend la superposition uniquement lorsque vrai — même convention que le reste de l'écran appelant (`openOverlay !== null`). */
  visible: boolean;
  children: ReactNode;
};

/**
 * Couche de superposition plein écran, TRANSVERSALE à tout sélecteur
 * numérique à roulette (`DurationWheelPicker`/`NumberWheelPicker`),
 * introduite par la correction VISUAL (T01-S09, correction tentative 2,
 * point D — commentaire de revue 5551813745).
 *
 * Règle transversale : « Tout sélecteur numérique à roulette s'ouvre dans
 * une couche d'overlay au-dessus de l'écran, centrée dans la zone utile,
 * avec arrière-plan atténué. Sa position ne dépend ni du contrôle
 * déclencheur ni du défilement. Le contenu sous-jacent reste inaccessible
 * au toucher et au défilement jusqu'à Annuler ou Confirmer. »
 *
 * Remplace l'ancien mécanisme d'ancrage local (`PopoverAnchor` +
 * `AnchoredRow.elevated` + `zIndex`), qui positionnait le sélecteur en
 * popover descendant de sa ligne/carte déclenchrice à l'intérieur du
 * `ScrollView` de l'écran — une position par construction dépendante du
 * déclencheur et du défilement, contraire à la règle ci-dessus (root cause
 * du défaut signalé).
 *
 * Implémentation : `Modal` React Native natif (`transparent`, plein écran
 * par construction, rendu dans une couche native séparée du reste de
 * l'arborescence) — sa position ne dépend donc jamais du `ScrollView` ou de
 * la ligne qui l'a ouvert, et tout le contenu sous-jacent est
 * structurellement inaccessible au toucher/défilement tant qu'elle est
 * montée, sans mécanisme `zIndex`/`elevated` à maintenir manuellement.
 *
 * Le voile de fond (`backdrop`) n'est délibérément PAS pressable : contraire
 * à l'ancien `composition-backdrop`/`exercise-backdrop` (qui fermait au
 * toucher), un sélecteur numérique à roulette ne se ferme désormais QUE par
 * ses propres actions Annuler/Confirmer — jamais par un toucher en dehors,
 * conformément à la règle ci-dessus.
 *
 * Ne modifie ni ne remplace `DurationWheelPicker.tsx`/`NumberWheelPicker
 * .tsx` eux-mêmes (baseline gelée, mécanisme d'interaction natif inchangé)
 * — uniquement leur CONTENEUR de positionnement dans l'écran appelant
 * (`CompositionScreen.tsx`/`ExerciseScreen.tsx`), conformément à « Priorité
 * aux primitives natives de l'OS » (`.github/AI_ORCHESTRATION.md`) : « Si le
 * rendu natif nécessite une adaptation de conteneur... corriger
 * l'intégration autour de la primitive native sans remplacer son mécanisme
 * d'interaction. »
 */
export function WheelPickerOverlay({ visible, children }: WheelPickerOverlayProps) {
  if (!visible) {
    return null;
  }
  return (
    <Modal visible transparent animationType="fade" statusBarTranslucent testID="wheel-picker-overlay">
      <View style={styles.backdrop} testID="wheel-picker-overlay-backdrop">
        <View style={styles.center} testID="wheel-picker-overlay-center">
          {children}
        </View>
      </View>
    </Modal>
  );
}

const styles = StyleSheet.create({
  backdrop: {
    flex: 1,
    backgroundColor: colors.overlayScrim,
    alignItems: "center",
    justifyContent: "center",
  },
  center: {
    alignItems: "center",
  },
});

import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { afterEach, beforeEach, describe, expect, it } from "@jest/globals";

import { DATABASE_VERSION } from "@/infrastructure/database/constants";
import { initializeDatabase } from "@/infrastructure/database/initializeDatabase";
import { NodeSqliteDatabase } from "@/infrastructure/database/testing/NodeSqliteDatabase";

describe("initializeDatabase", () => {
  let database: NodeSqliteDatabase;

  beforeEach(() => {
    database = NodeSqliteDatabase.openInMemory();
  });

  afterEach(() => {
    database.close();
  });

  it("applies the foreign_keys pragma and runs the migration", async () => {
    await initializeDatabase(database);

    const foreignKeys = await database.getFirstAsync<{ foreign_keys: number }>(
      "PRAGMA foreign_keys",
    );
    const version = await database.getFirstAsync<{ user_version: number }>(
      "PRAGMA user_version",
    );
    const user = await database.getFirstAsync<{ id: string }>("SELECT id FROM users");

    // foreign_keys is directly observable even on an in-memory database.
    expect(foreignKeys?.foreign_keys).toBe(1);
    expect(version?.user_version).toBe(DATABASE_VERSION);
    expect(user?.id).toMatch(/^usr_[0-9a-f]{32}$/);
  });

  it("is idempotent: a second call is a no-op beyond the first", async () => {
    await initializeDatabase(database);
    const firstUser = await database.getFirstAsync<{ id: string }>("SELECT id FROM users");

    await initializeDatabase(database);

    const users = await database.getAllAsync<{ id: string }>("SELECT id FROM users");
    const version = await database.getFirstAsync<{ user_version: number }>(
      "PRAGMA user_version",
    );

    expect(users).toEqual([firstUser]);
    expect(version?.user_version).toBe(DATABASE_VERSION);
  });

  // `:memory:` reports journal_mode as "memory" regardless of what is
  // requested — its execution cannot be observed there (see
  // T01-S05-rapport-contre-verification.md §3). A real file-backed
  // connection is required to prove that `initializeDatabase` actually
  // executes `PRAGMA journal_mode = WAL`, not merely that the string is
  // listed in STANDARD_PRAGMAS.
  it("actually executes PRAGMA journal_mode = WAL on a real file-backed connection", async () => {
    const tempDirectory = mkdtempSync(join(tmpdir(), "kodjo-initdb-"));
    const databasePath = join(tempDirectory, "test.db");
    let fileDatabase: NodeSqliteDatabase | undefined;

    try {
      // Opening the connection lives inside the protected block: if
      // `openFile` itself throws, the outer `finally` below still runs and
      // removes `tempDirectory`.
      fileDatabase = NodeSqliteDatabase.openFile(databasePath);
      await initializeDatabase(fileDatabase);

      const journalMode = await fileDatabase.getFirstAsync<{ journal_mode: string }>(
        "PRAGMA journal_mode",
      );

      expect(journalMode?.journal_mode.toLowerCase()).toBe("wal");
    } finally {
      try {
        fileDatabase?.close();
      } finally {
        // Nested in its own `finally` so that a failure while closing the
        // connection can never prevent this cleanup from running.
        // `tempDirectory` is a freshly created, unique directory returned
        // by `mkdtempSync` for this test alone — never a broad or
        // unresolved path — so removing it also clears any WAL/SHM
        // sidecar files SQLite created alongside the database file.
        rmSync(tempDirectory, { recursive: true, force: true });
      }
    }
  });
});

