        ) VALUES
          ('ts-a', 'session-a', 'cycle-a', 'tour-a', 'EXERCISE', 'IN_TOUR', 0, 'A', 'DURATION', 30, NULL, 1, 0, NULL, ?, ?),
          ('ts-b', 'session-a', 'cycle-a', 'tour-a', 'EXERCISE', 'IN_TOUR', 1, 'B', 'REPETITIONS', NULL, 12, 2, 5, NULL, ?, ?)`,
