      await database.runAsync("UPDATE activities SET execution_parameters = ? WHERE id = 'occ-legacy'", [corrupt]);
      const rowBefore = await database.getFirstAsync("SELECT * FROM activity_definitions WHERE id = 'def-legacy'");
