  it("P3-17/canonical-roundtrip — base fichier fermée puis rouverte : occurrence canonique, Catégorie et médias intacts", async () => {
    const path = join(tmpdir(), `kodjo-pre3-session-${Date.now()}-${Math.random().toString(16).slice(2)}.db`);
    const fileDatabase = NodeSqliteDatabase.openFile(path);
    try {
      await migrateDatabase(fileDatabase);
      const extremes = parameters({
        mode: "REPETITIONS",
        series: { kind: "VARIABLE", rows: [{ target: 100, pauseSeconds: 300 }, { target: 1, pauseSeconds: 0 }] },
        sideOrder: "BY_SERIES",
        cadenceBeepIntervalSeconds: 10,
      });
      const created = await new SqliteSessionRepository(fileDatabase, ids("ses")).create(
        sessionInput([occurrence({ executionParameters: extremes })]),
      );
      fileDatabase.close();
      const reopened = NodeSqliteDatabase.openFile(path);
      try {
        const activity = (await new SqliteSessionRepository(reopened, ids("ses")).findById(created.id))!.cycle.tour.exercises[0]!;
        expect(activity.executionParameters).toEqual(extremes);
        expect(activity.repetitionCount).toBe(100);
        expect(activity.seriesCount).toBe(2);
        expect(activity.categoryId).toBe("cardio");
        expect(activity.media?.map((item) => item.asset)).toEqual([asset("v1", "VIDEO"), asset("p1")]);
      } finally {
        reopened.close();
      }
    } finally {
      rmSync(path, { force: true });
      rmSync(`${path}-wal`, { force: true });
      rmSync(`${path}-shm`, { force: true });
    }
  });

  it("P3-18/copy-complete — duplication : nouvelle occurrence et nouveaux liens, mêmes fichiers, aucune mutation croisée", async () => {
    const repository = new SqliteSessionRepository(database, ids("ses"));
    const created = await repository.create(sessionInput([occurrence({ postActivityRecoverySeconds: 30 })]));
    const sourceId = created.cycle.tour.exercises[0]!.id;
    const duplicated = await repository.update(
      created.id,
      updateFromDraft(created, (draft) => ({ ...draft, exercises: duplicateActivity(draft.exercises, sourceId, "copy-1") })),
    );
    const exercises = duplicated.status === "UPDATED" ? duplicated.session.cycle.tour.exercises : [];
    const [source, copy] = exercises;
    expect(copy?.id).toBe("copy-1");
    expect(copy?.executionParameters).toEqual(source?.executionParameters);
    expect(copy?.categoryId).toBe(source?.categoryId);
    expect(copy?.postActivityRecoverySeconds).toBe(30);
    expect(copy?.media?.map((item) => item.assetId)).toEqual(source?.media?.map((item) => item.assetId));
    expect(new Set([...(copy?.media ?? []), ...(source?.media ?? [])].map((item) => item.id)).size).toBe(4);
    // Modifier la copie ne touche pas la source.
    const afterEdit = await repository.update(
      created.id,
      updateFromDraft(duplicated.status === "UPDATED" ? duplicated.session : created, (draft) => ({
        ...draft,
        exercises: draft.exercises.map((exercise) =>
          exercise.id === "copy-1" ? { ...exercise, executionParameters: parameters({ cadenceBeepIntervalSeconds: 7 }), media: [] } : exercise,
        ),
      })),
    );
    const finalSource = afterEdit.status === "UPDATED" ? afterEdit.session.cycle.tour.exercises[0] : null;
    expect(finalSource?.executionParameters).toEqual(parameters());
    expect(finalSource?.media?.map((item) => item.assetId)).toEqual(["v1", "p1"]);
  });

  it("P3-23/file-preservation — retirer un lien ou une occurrence ne supprime jamais l'asset référencé ailleurs", async () => {
    const repository = new SqliteSessionRepository(database, ids("ses"));
    const media = new SqliteMediaRepository(database);
    const created = await repository.create(sessionInput([occurrence(), occurrence({ media: [{ assetId: "v1" }] })]));
    expect(await media.countReferences("v1")).toBe(2);
    const removedLink = await repository.update(
      created.id,
      updateFromDraft(created, (draft) => ({
        ...draft,
        exercises: draft.exercises.map((exercise, index) => (index === 0 ? { ...exercise, media: [] } : exercise)),
      })),
    );
    expect(removedLink.status).toBe("UPDATED");
    expect(await media.countReferences("v1")).toBe(1);
    expect(await media.countReferences("p1")).toBe(0);
    // Asset sans référence : conservé (aucune purge globale), toujours lisible.
    expect(await media.findAsset("p1")).toEqual(asset("p1"));
    expect(await media.findAsset("v1")).toEqual(asset("v1", "VIDEO"));
  });
});

import * as SQLite from "expo-sqlite";

import { STANDARD_PRAGMAS } from "./constants";
import type {
  Database,
  SqlParameters,
  SqlRunResult,
} from "./Database";

export class ExpoDatabase implements Database {
  constructor(private readonly database: SQLite.SQLiteDatabase) {}

  execAsync(source: string): Promise<void> {
    return this.database.execAsync(source);
  }

  async runAsync(source: string, parameters: SqlParameters = []): Promise<SqlRunResult> {
    const result = await this.database.runAsync(source, [...parameters]);
    return { changes: result.changes, lastInsertRowId: result.lastInsertRowId };
  }

  getFirstAsync<T>(source: string, parameters: SqlParameters = []): Promise<T | null> {
    return this.database.getFirstAsync<T>(source, [...parameters]);
  }

  getAllAsync<T>(source: string, parameters: SqlParameters = []): Promise<T[]> {
    return this.database.getAllAsync<T>(source, [...parameters]);
  }

  withExclusiveTransactionAsync(task: (transaction: Database) => Promise<void>): Promise<void> {
    return this.database.withExclusiveTransactionAsync(async (transaction) => {
      await task(new ExpoDatabase(transaction));
    });
  }
}
export type OpenedExpoDatabase = {
  database: ExpoDatabase;
  closeAsync(): Promise<void>;
};

export async function openExpoDatabase(databaseName: string): Promise<OpenedExpoDatabase> {
  const nativeDatabase = await SQLite.openDatabaseAsync(databaseName);
  for (const pragma of STANDARD_PRAGMAS) {
    await nativeDatabase.execAsync(pragma);
  }

  return {
    database: new ExpoDatabase(nativeDatabase),
    closeAsync: () => nativeDatabase.closeAsync(),
  };
}

import { STANDARD_PRAGMAS } from "./constants";
import type { Database } from "./Database";
import { migrateDatabase } from "./migrateDatabase";

/**
 * Prépare une connexion `Database` pour l'usage applicatif : pose les
 * pragmas canoniques puis exécute la migration (idempotente). Pure —
 * aucun import React, aucune dépendance à `expo-sqlite` : ne connaît que
 * l'interface `Database`, donc testable avec n'importe quelle
 * implémentation (`NodeSqliteDatabase` en test, `ExpoDatabase` à l'exécution
 * réelle). Ne crée aucune nouvelle migration — `migrateDatabase`/
 * `migration001.ts` sont réutilisés tels quels.
 */
export async function initializeDatabase(database: Database): Promise<void> {
  for (const pragma of STANDARD_PRAGMAS) {
    await database.execAsync(pragma);
  }
  await migrateDatabase(database);
}

import * as SQLite from "expo-sqlite";

import { ExpoDatabase, openExpoDatabase } from "@/infrastructure/database/ExpoDatabase";
import { migrateDatabase } from "@/infrastructure/database/migrateDatabase";
import { SqliteSessionRepository } from "@/infrastructure/database/repositories/SqliteSessionRepository";

const INTEGRATION_DATABASE_NAME = "kodjo-t01-s01-integration.db";

export async function runNativeDatabaseIntegrationCheck(): Promise<void> {
  await SQLite.deleteDatabaseAsync(INTEGRATION_DATABASE_NAME).catch(() => undefined);
  const opened = await openExpoDatabase(INTEGRATION_DATABASE_NAME);

  try {
    await migrateDatabase(opened.database);
    const repository = new SqliteSessionRepository(opened.database);
    const created = await repository.create({
      name: "Contrôle SQLite natif",
      initialCountdownSeconds: 10,
      finalPhaseSeconds: 5,
      tourRepeatCount: 1,
      exercises: [
        {
          type: "EXERCISE",
          structuralPosition: "IN_TOUR",
          name: "Exercice chronométré",
          executionMode: "DURATION",
          durationSeconds: 30,
          repetitionCount: null,
          seriesCount: 3,
          pauseSeconds: 15,
          // T02-S02 / V2-PRE-1 : la récupération post-exercice traverse le
          // contrôle natif — colonne `post_activity_recovery_seconds`
          // (renommée depuis `recovery_seconds`, `migration007`).
          postActivityRecoverySeconds: 20,
          instruction: null,
          bodyZoneIds: [],
        },
      ],
    });

    const reopened = await repository.findById(created.id);
    const listed = await repository.listActive();

    if (!reopened || listed.length !== 1 || listed[0].id !== created.id) {
      throw new Error("Native SQLite integration check failed.");
    }

    // T02-S02 : aller-retour réel de `recovery_seconds` et parité de la durée
    // agrégée par SQL avec la formule du Domaine
    // `D = C × A + (C − 1) × B + R` = 3 × 30 + 2 × 15 + 20 = 140 s. Un
    // contrôle natif qui ne relirait que l'identifiant ne prouverait ni la
    // nouvelle colonne, ni la suppression de la Pause finale.
    const roundTripped = reopened.cycle.tour.exercises[0]!;
    if (roundTripped.postActivityRecoverySeconds !== 20 || roundTripped.pauseSeconds !== 15) {
      throw new Error("Attached recovery was not persisted natively.");
    }
    if (listed[0].estimatedDurationSeconds !== 140) {
      throw new Error("Native SQL duration does not match the domain formula.");
    }

    if (![created.id, created.cycle.id, created.cycle.tour.id, created.cycle.tour.exercises[0]!.id].every(
      (identifier) => /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(identifier),
    )) {
      throw new Error("Crypto.randomUUID() identifiers are invalid.");
    }
  } finally {
    await opened.closeAsync();
  }

  const verificationDatabase = await SQLite.openDatabaseAsync(INTEGRATION_DATABASE_NAME);
  try {
    const database = new ExpoDatabase(verificationDatabase);
    const userCount = await database.getFirstAsync<{ count: number }>(
      "SELECT COUNT(*) AS count FROM users",
    );
    if (userCount?.count !== 1) {
      throw new Error("Stable local user was not persisted.");
    }
  } finally {
    await verificationDatabase.closeAsync();
    await SQLite.deleteDatabaseAsync(INTEGRATION_DATABASE_NAME);
  }
}

import { canonicalBodyZoneKey } from "@/domain/body-zones/BodyZone";
import { canonicalLabelKey } from "@/domain/labels/Label";
import { DATABASE_VERSION, LOCAL_USER_SINGLETON_KEY } from "./constants";
import type { Database } from "./Database";
import { MIGRATION_001 } from "./migrations/migration001";
import { MIGRATION_002 } from "./migrations/migration002";
import { MIGRATION_003 } from "./migrations/migration003";
import { MIGRATION_004 } from "./migrations/migration004";
import { MIGRATION_005 } from "./migrations/migration005";
import { MIGRATION_006 } from "./migrations/migration006";
import { MIGRATION_007 } from "./migrations/migration007";
import { MIGRATION_008_COLUMNS, MIGRATION_008_FINALIZE } from "./migrations/migration008";
import { MIGRATION_009 } from "./migrations/migration009";

type UserVersionRow = { user_version: number };
type CountRow = { count: number };
type NamedRow = { id: string; name: string };

/**
 * Applique séquentiellement chaque migration additive manquante, jamais en
 * bloc : une base à la version 1 (T01-S01…S08) ne rejoue jamais
 * `MIGRATION_001` (déjà appliquée, immuable — « Conservation des acquis »).
 * `MIGRATION_002` (T01-S09) porte à la version 2, `MIGRATION_003` (T01-S10,
 * mode `TO_FAILURE` — reconstruction additive de `activities`) à la version
 * 3, `MIGRATION_004` (T02-S02, Récupération attachée + suppression des
 * Activités `RECOVERY`) à la version 4, `MIGRATION_005` (V2-BILAT-01,
 * configuration de bilatéralité `activities.side_mode`/`tours.side_mode`)
 * à la version 5. Une base neuve (version 0) les traverse toutes à la suite,
 * dans le même ordre. `migration001.ts` n'est
 * jamais modifié : chaque migration reste un fichier indépendant, exécuté une
 * fois, jamais réécrit.
 *
 * `PRAGMA foreign_keys` étant un no-op dans une transaction (SQLite),
 * `MIGRATION_003` et `MIGRATION_004` s'appuient sur
 * `PRAGMA defer_foreign_keys=ON` dans cette même transaction partagée (Q2-A)
 * — le runner n'est pas restructuré.
 *
 * Toute la séquence s'exécute dans UNE transaction exclusive : un échec à
 * n'importe quelle étape annule l'intégralité des migrations appliquées
 * pendant ce run et laisse `user_version` inchangé (aucun état intermédiaire
 * persisté, aucune Récupération à moitié convertie).
 */
export async function migrateDatabase(database: Database): Promise<void> {
  const versionRow = await database.getFirstAsync<UserVersionRow>("PRAGMA user_version");
  const currentVersion = versionRow?.user_version ?? 0;

  if (currentVersion > DATABASE_VERSION) {
    throw new Error(
      `Database version ${currentVersion} is newer than supported version ${DATABASE_VERSION}.`,
    );
  }

  if (currentVersion === DATABASE_VERSION) {
    return;
  }

  await database.withExclusiveTransactionAsync(async (transaction) => {
    let version = currentVersion;

    if (version === 0) {
      await transaction.execAsync(MIGRATION_001);
      await transaction.runAsync(
        `INSERT OR IGNORE INTO users (singleton_key, id, created_at)
         VALUES (?, 'usr_' || lower(hex(randomblob(16))), strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))`,
        [LOCAL_USER_SINGLETON_KEY],
      );
      version = 1;
    }

    if (version === 1) {
      await transaction.execAsync(MIGRATION_002);
      version = 2;
    }

    if (version === 2) {
      await transaction.execAsync(MIGRATION_003);
      version = 3;
    }

    if (version === 3) {
      await transaction.execAsync(MIGRATION_004);
      version = 4;
    }

    if (version === 4) {
      await transaction.execAsync(MIGRATION_005);
      version = 5;
    }

    if (version === 5) {
      await transaction.execAsync(MIGRATION_006);
      version = 6;
    }

    if (version === 6) {
      await transaction.execAsync(MIGRATION_007);
      version = 7;
    }

    if (version === 7) {
      await transaction.execAsync(MIGRATION_008_COLUMNS);

      // Les clés normalisées (NFD, casse) ne sont pas exprimables en SQL
      // pur : chaque Étiquette/Zone déjà persistée (seed `migration007`, ou
      // une installation antérieure) reçoit la sienne, calculée en
      // JavaScript par la MÊME fonction que `LabelRepository.create`/
      // `BodyZoneRepository.create` — jamais une seconde implémentation
      // divergente.
      const labelRows = await transaction.getAllAsync<NamedRow>("SELECT id, name FROM labels");
      for (const row of labelRows) {
        await transaction.runAsync("UPDATE labels SET canonical_key = ? WHERE id = ?", [
          canonicalLabelKey(row.name),
          row.id,
        ]);
      }
      const bodyZoneRows = await transaction.getAllAsync<NamedRow>(
        "SELECT id, name FROM body_zones",
      );
      for (const row of bodyZoneRows) {
        await transaction.runAsync("UPDATE body_zones SET canonical_key = ? WHERE id = ?", [
          canonicalBodyZoneKey(row.name),
          row.id,
        ]);
      }

      await transaction.execAsync(MIGRATION_008_FINALIZE);
      version = 8;
    }

    // PRE-3 : colonnes et table additives uniquement — aucun backfill,
    // aucune lecture du Profil, aucune réécriture des valeurs existantes.
    if (version === 8) {
      await transaction.execAsync(MIGRATION_009);
      version = 9;
    }

    const userCount = await transaction.getFirstAsync<CountRow>(
      "SELECT COUNT(*) AS count FROM users WHERE singleton_key = ?",
      [LOCAL_USER_SINGLETON_KEY],
    );

    if (userCount?.count !== 1) {
      throw new Error("The local user could not be initialized.");
    }

    await transaction.execAsync(`PRAGMA user_version = ${DATABASE_VERSION}`);
  });
}

import * as Crypto from "expo-crypto";

import type { CreateCategoryInput } from "@/domain/categories/Category";
import { canonicalCategoryKey } from "@/domain/categories/validation";
import type {
  ActivityDefinition,
  ActivityDefinitionRepository,
  CreateActivityDefinitionInput,
  UpdateActivityDefinitionInput,
} from "@/domain/activities";
import {
  legacyExecutionParameters,
  parseExecutionParameters,
  projectLegacyScalars,
  serializeExecutionParameters,
  type ExecutionParameters,
} from "@/domain/activities/ExecutionParameters";
import { DEFAULT_SIDE_MODE } from "@/domain/sessions/defaults";
import type { ExerciseExecutionMode } from "@/domain/sessions/Session";
import type { SideMode } from "@/domain/sessions/sideMode";
import type { Database } from "@/infrastructure/database/Database";
import type {
  ActivityDefinitionBodyZoneRow,
  ActivityDefinitionRow,
} from "@/infrastructure/database/types/DatabaseRows";

import { listDefinitionMediaByIds, replaceDefinitionMediaLinks } from "./SqliteMediaRepository";

type UuidFactory = () => string;
type CategoryIdRow = { id: string; is_active: 0 | 1 };

/**
 * Garde « valeur retirée » côté stockage (T16, D-210, CE-UI-09 L2825/L2837) :
 * une référence `EXISTING` vers une Catégorie RETIRÉE est refusée, SAUF si
 * elle est identique à l'affectation déjà persistée de cet Exercice (une
 * modification qui ne touche pas la Catégorie reste permise même si celle-ci
 * a été retirée entre-temps). Le brouillon appelant reste intact : cette
 * erreur se propage telle quelle, jamais une écriture partielle.
 */
export class RetiredCategoryError extends Error {
  constructor() {
    super("The referenced category has been retired and cannot be newly assigned.");
    this.name = "RetiredCategoryError";
  }
}

const SELECT_COLUMNS = `
  id, name, description, execution_mode, duration_seconds, repetition_count,
  series_count, pause_seconds, category_id, side_mode, side_recovery_seconds,
  execution_parameters, created_at, updated_at
`;

/**
 * PRE-3 : valeurs scalaires écrites. Quand des paramètres canoniques font
 * autorité, les colonnes historiques reçoivent UNIQUEMENT leurs projections
 * (respect des `CHECK`, compatibilité des anciens DTO) — jamais une écriture
 * indépendante concurrente.
 */
function scalarValues(input: CreateActivityDefinitionInput, canonical: ExecutionParameters | null) {
  if (!canonical) {
    return {
      executionMode: input.executionMode,
      durationSeconds: input.durationSeconds,
      repetitionCount: input.repetitionCount,
      seriesCount: input.seriesCount,
      pauseSeconds: input.pauseSeconds,
      sideMode: input.sideMode ?? DEFAULT_SIDE_MODE,
      sideRecoverySeconds: input.sideRecoverySeconds,
    };
  }
  return projectLegacyScalars(canonical);
}

/**
 * Résout une référence de Catégorie (`CreateCategoryInput`) vers un
 * identifiant réellement persisté (D-211) — même patron que l'ancienne
 * résolution `session_categories` (`SqliteSessionRepository`), désormais
 * portée par l'Exercice : `EXISTING` doit référencer une Catégorie déjà
 * présente (défense en profondeur) ; `NEW` retrouve la Catégorie de même clé
 * canonique si elle existe déjà (D-106, jamais de doublon) ou la crée sinon.
 */
async function resolveCategoryId(
  transaction: Database,
  category: CreateCategoryInput,
  uuidFactory: UuidFactory,
  timestamp: string,
  /** Catégorie déjà assignée à cet Exercice avant la modification — `null` à la création (T16). */
  currentCategoryId: string | null = null,
): Promise<string> {
  if (category.kind === "EXISTING") {
    const row = await transaction.getFirstAsync<CategoryIdRow>(
      "SELECT id, is_active FROM categories WHERE id = ?",
      [category.categoryId],
    );
    if (!row) {
      throw new Error("Referenced category does not exist.");
    }
    if (row.is_active === 0 && row.id !== currentCategoryId) {
      throw new RetiredCategoryError();
    }
    return row.id;
  }

  const canonicalKey = canonicalCategoryKey(category.name);
  const existing = await transaction.getFirstAsync<CategoryIdRow>(
    "SELECT id FROM categories WHERE canonical_key = ?",
    [canonicalKey],
  );
  if (existing) {
    return existing.id;
  }
  const categoryId = uuidFactory();
  await transaction.runAsync(
    `INSERT INTO categories (id, name, canonical_key, color, is_predefined, display_order, is_active, created_at)
     VALUES (?, ?, ?, ?, 0, NULL, 1, ?)`,
    [categoryId, category.name, canonicalKey, category.color, timestamp],
  );
  return categoryId;
}

/**
 * Persistance SQLite des `ActivityDefinition` (V2-CAT-01, `migration006` ;
 * V2-PRE-1, `migration007` : Catégorie obligatoire, pause de changement de
 * côté propre, retrait de la récupération post-exercice). Même patron que
 * `SqliteCategoryRepository`/`SqliteSessionRepository` : aucune dépendance à
 * `expo-sqlite` directement (`Database`, interface partagée),
 * `uuidFactory`/`now` injectables pour les tests.
 */
export class SqliteActivityDefinitionRepository implements ActivityDefinitionRepository {
  constructor(
    private readonly database: Database,
    private readonly uuidFactory: UuidFactory = Crypto.randomUUID,
    private readonly now: () => string = () => new Date().toISOString(),
  ) {}

  async create(input: CreateActivityDefinitionInput): Promise<ActivityDefinition> {
    const id = this.uuidFactory();
    const timestamp = this.now();
    const canonical = input.executionParameters ?? null;
    const values = scalarValues(input, canonical);

    // PRE-3 : asset(s) importé(s) + définition + liens ordonnés dans UNE
    // transaction (Terminer Catalogue) — aucune écriture partielle.
    await this.database.withExclusiveTransactionAsync(async (transaction) => {
      const categoryId = await resolveCategoryId(transaction, input.category, this.uuidFactory, timestamp);
      await transaction.runAsync(
        `INSERT INTO activity_definitions (
          id, name, description, execution_mode, duration_seconds, repetition_count,
          series_count, pause_seconds, category_id, side_mode, side_recovery_seconds,
          execution_parameters, created_at, updated_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          id,
          input.name,
          input.description,
          values.executionMode,
          values.durationSeconds,
          values.repetitionCount,
          values.seriesCount,
          values.pauseSeconds,
          categoryId,
          values.sideMode,
          values.sideRecoverySeconds,
          canonical ? serializeExecutionParameters(canonical) : null,
          timestamp,
          timestamp,
        ],
      );
      await insertBodyZones(transaction, id, input.bodyZoneIds);
      await replaceDefinitionMediaLinks(transaction, id, input.media ?? [], this.uuidFactory);
    });

    const created = await this.findById(id);
    if (!created) {
      throw new Error("The created activity definition could not be read back.");
    }
    return created;
  }

  async update(
    id: string,
    input: UpdateActivityDefinitionInput,
  ): Promise<ActivityDefinition | null> {
    const timestamp = this.now();
    let updated = false;

    await this.database.withExclusiveTransactionAsync(async (transaction) => {
      const existing = await transaction.getFirstAsync<{
        id: string;
        created_at: string;
        category_id: string;
        execution_parameters: string | null;
      }>("SELECT id, created_at, category_id, execution_parameters FROM activity_definitions WHERE id = ?", [id]);
      if (!existing) {
        return;
      }
      // PRE-3 : sans paramètres canoniques fournis (ancien appelant), un JSON
      // déjà persisté reste l'autorité — ses projections sont réécrites,
      // jamais des scalaires divergents.
      const canonical =
        input.executionParameters ??
        (existing.execution_parameters !== null ? parseExecutionParameters(existing.execution_parameters) : null);
      const values = scalarValues(input, canonical);
      const categoryId = await resolveCategoryId(
        transaction,
        input.category,
        this.uuidFactory,
        timestamp,
        existing.category_id,
      );

      await transaction.runAsync(
        `UPDATE activity_definitions SET
          name = ?, description = ?, execution_mode = ?, duration_seconds = ?,
          repetition_count = ?, series_count = ?, pause_seconds = ?,
          category_id = ?, side_mode = ?, side_recovery_seconds = ?,
          execution_parameters = ?, updated_at = ?
         WHERE id = ?`,
        [
          input.name,
          input.description,
          values.executionMode,
          values.durationSeconds,
          values.repetitionCount,
          values.seriesCount,
          values.pauseSeconds,
          categoryId,
          values.sideMode,
          values.sideRecoverySeconds,
          canonical ? serializeExecutionParameters(canonical) : null,
          timestamp,
          id,
        ],
      );
      await transaction.runAsync(
        `DELETE FROM activity_definition_body_zones WHERE activity_definition_id = ?`,
        [id],
      );
      await insertBodyZones(transaction, id, input.bodyZoneIds);
      // PRE-3 : `media` absent (ancien appelant) conserve les liens ; une
      // liste explicite — même vide — les remplace. Les assets ne sont
      // jamais supprimés.
      if (input.media !== undefined) {
        await replaceDefinitionMediaLinks(transaction, id, input.media, this.uuidFactory);
      }
      updated = true;
    });

    if (!updated) {
      return null;
    }
    return this.findById(id);
  }

  async findById(id: string): Promise<ActivityDefinition | null> {
    const row = await this.database.getFirstAsync<ActivityDefinitionRow>(
      `SELECT ${SELECT_COLUMNS} FROM activity_definitions WHERE id = ?`,
      [id],
    );
    if (!row) {
      return null;
    }
    const bodyZoneIds = await getBodyZoneIds(this.database, [id]);
    const media = await listDefinitionMediaByIds(this.database, [id]);
    return mapActivityDefinitionRow(row, bodyZoneIds.get(id) ?? [], media.get(id) ?? []);
  }

  async listAll(): Promise<readonly ActivityDefinition[]> {
    const rows = await this.database.getAllAsync<ActivityDefinitionRow>(
      `SELECT ${SELECT_COLUMNS} FROM activity_definitions ORDER BY updated_at DESC`,
    );
    const ids = rows.map((row) => row.id);
    const bodyZonesById = await getBodyZoneIds(this.database, ids);
    const mediaById = await listDefinitionMediaByIds(this.database, ids);
    return rows.map((row) =>
      mapActivityDefinitionRow(row, bodyZonesById.get(row.id) ?? [], mediaById.get(row.id) ?? []),
    );
  }
}

async function insertBodyZones(
  transaction: Database,
  activityDefinitionId: string,
  bodyZoneIds: readonly string[],
): Promise<void> {
  for (const bodyZoneId of bodyZoneIds) {
    await transaction.runAsync(
      `INSERT INTO activity_definition_body_zones (activity_definition_id, body_zone_id) VALUES (?, ?)`,
      [activityDefinitionId, bodyZoneId],
    );
  }
}

async function getBodyZoneIds(
  database: Database,
  activityDefinitionIds: readonly string[],
): Promise<ReadonlyMap<string, readonly string[]>> {
  if (activityDefinitionIds.length === 0) {
    return new Map();
  }
  // `activityDefinitionIds` provient toujours de lignes déjà relues depuis
  // SQLite (jamais une saisie utilisateur directe) — même garantie que
  // `SqliteSessionRepository.getBodyZonesForActivities`.
  const placeholders = activityDefinitionIds.map(() => "?").join(", ");
  const rows = await database.getAllAsync<ActivityDefinitionBodyZoneRow>(
    `SELECT activity_definition_id, body_zone_id FROM activity_definition_body_zones
     WHERE activity_definition_id IN (${placeholders})`,
    activityDefinitionIds,
  );
  const byId = new Map<string, string[]>();
  for (const row of rows) {
    const list = byId.get(row.activity_definition_id) ?? [];
    list.push(row.body_zone_id);
    byId.set(row.activity_definition_id, list);
  }
  return byId;
}

/**
 * Projection d'une ligne. PRE-3 : le JSON canonique fait autorité ; corrompu
 * ou de version inconnue, il lève une `ExecutionParametersDataError` —
 * jamais un repli silencieux sur les scalaires. Sans JSON (ancien objet),
 * l'adaptateur conservateur s'applique (aucune lecture du Profil).
 */
function mapActivityDefinitionRow(
  row: ActivityDefinitionRow,
  bodyZoneIds: readonly string[],
  media: ActivityDefinition["media"] = [],
): ActivityDefinition {
  const executionParameters =
    row.execution_parameters !== null && row.execution_parameters !== undefined
      ? parseExecutionParameters(row.execution_parameters)
      : legacyExecutionParameters({
          executionMode: row.execution_mode as ExerciseExecutionMode,
          durationSeconds: row.duration_seconds,
          repetitionCount: row.repetition_count,
          seriesCount: row.series_count,
          pauseSeconds: row.pause_seconds,
          sideMode: row.side_mode as SideMode,
          sideRecoverySeconds: row.side_recovery_seconds,
        });
  return {
    executionParameters,
    media,
    id: row.id,
    name: row.name,
    description: row.description,
    executionMode: row.execution_mode as ExerciseExecutionMode,
    durationSeconds: row.duration_seconds,
    repetitionCount: row.repetition_count,
    seriesCount: row.series_count,
    pauseSeconds: row.pause_seconds,
    categoryId: row.category_id,
    bodyZoneIds,
    sideMode: row.side_mode as SideMode,
    sideRecoverySeconds: row.side_recovery_seconds,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

