function placeholders(values: readonly unknown[]): string {
  return values.map(() => "?").join(", ");
}

/** Liens ordonnés de plusieurs définitions en UNE requête (aucun N+1). */
export async function listDefinitionMediaByIds(
  database: Database,
  activityDefinitionIds: readonly string[],
): Promise<ReadonlyMap<string, readonly ActivityMediaWithAsset[]>> {
  const byId = new Map<string, ActivityMediaWithAsset[]>();
  if (activityDefinitionIds.length === 0) {
    return byId;
  }
  const rows = await database.getAllAsync<ActivityMediaRow>(
    `SELECT
       activity_media.id AS id,
       activity_media.activity_definition_id AS activity_definition_id,
       activity_media.asset_id AS asset_id,
       activity_media.position AS position,
       ${JOINED_ASSET_COLUMNS}
     FROM activity_media
     JOIN media_assets ON media_assets.id = activity_media.asset_id
     WHERE activity_media.activity_definition_id IN (${placeholders(activityDefinitionIds)})
     ORDER BY activity_media.activity_definition_id ASC, activity_media.position ASC`,
    activityDefinitionIds,
  );
  for (const row of rows) {
    const list = byId.get(row.activity_definition_id) ?? [];
    list.push(mapActivityMediaRow(row));
    byId.set(row.activity_definition_id, list);
  }
  return byId;
}

/** Liens ordonnés de plusieurs occurrences en UNE requête (aucun N+1). */
export async function listSessionActivityMediaByIds(
  database: Database,
  activityIds: readonly string[],
): Promise<ReadonlyMap<string, readonly SessionActivityMediaWithAsset[]>> {
  const byId = new Map<string, SessionActivityMediaWithAsset[]>();
  if (activityIds.length === 0) {
    return byId;
  }
  const rows = await database.getAllAsync<SessionActivityMediaRow>(
    `SELECT
       session_activity_media.id AS id,
       session_activity_media.activity_id AS activity_id,
       session_activity_media.asset_id AS asset_id,
       session_activity_media.position AS position,
       ${JOINED_ASSET_COLUMNS}
     FROM session_activity_media
     JOIN media_assets ON media_assets.id = session_activity_media.asset_id
     WHERE session_activity_media.activity_id IN (${placeholders(activityIds)})
     ORDER BY session_activity_media.activity_id ASC, session_activity_media.position ASC`,
    activityIds,
  );
  for (const row of rows) {
    const list = byId.get(row.activity_id) ?? [];
    list.push(mapSessionActivityMediaRow(row));
    byId.set(row.activity_id, list);
  }
  return byId;
}

/**
 * Crée dans la transaction courante les assets fraîchement préparés qui
 * n'existent pas encore. Un asset déjà persisté n'est JAMAIS réécrit (ses
 * métadonnées restent immuables) ; un asset invalide annule la transaction.
 */
export async function ensureMediaAssets(
  transaction: Database,
  items: readonly MediaLinkInput[],
): Promise<void> {
  for (const item of items) {
    if (!item.asset) {
      continue;
    }
    if (item.asset.id !== item.assetId || !isValidNewMediaAsset(item.asset)) {
      throw new MediaAssetWriteError("Invalid media asset.");
    }
    const existing = await transaction.getFirstAsync<{ id: string }>(
      "SELECT id FROM media_assets WHERE id = ?",
      [item.assetId],
    );
    if (existing) {
      continue;
    }
    const asset = item.asset;
    await transaction.runAsync(
      `INSERT INTO media_assets (id, uri, created_at, kind, mime_type, file_name, size_bytes, duration_ms, width, height)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        asset.id,
        asset.uri,
        asset.createdAt,
        asset.kind ?? null,
        asset.mimeType ?? null,
        asset.fileName ?? null,
        asset.sizeBytes ?? null,
        asset.durationMs ?? null,
        asset.width ?? null,
        asset.height ?? null,
      ],
    );
  }
}

/**
 * Remplace les liens d'une définition par la liste ordonnée fournie
 * (position = rang du tableau). Les assets restent intacts.
 */
export async function replaceDefinitionMediaLinks(
  transaction: Database,
  activityDefinitionId: string,
  items: readonly MediaLinkInput[],
  uuidFactory: UuidFactory,
): Promise<void> {
  await ensureMediaAssets(transaction, items);
  await transaction.runAsync(`DELETE FROM activity_media WHERE activity_definition_id = ?`, [
    activityDefinitionId,
  ]);
  for (const [position, item] of items.entries()) {
    await transaction.runAsync(
      `INSERT INTO activity_media (id, activity_definition_id, asset_id, position) VALUES (?, ?, ?, ?)`,
      [uuidFactory(), activityDefinitionId, item.assetId, position],
    );
  }
}

/**
 * Remplace les liens d'une occurrence (PRE-3) — identités propres, mêmes
 * fichiers physiques que la source. Les assets restent intacts.
 */
export async function replaceSessionActivityMediaLinks(
  transaction: Database,
  activityId: string,
  items: readonly MediaLinkInput[],
  uuidFactory: UuidFactory,
): Promise<void> {
  await ensureMediaAssets(transaction, items);
  await transaction.runAsync(`DELETE FROM session_activity_media WHERE activity_id = ?`, [activityId]);
  for (const [position, item] of items.entries()) {
    await transaction.runAsync(
      `INSERT INTO session_activity_media (id, activity_id, asset_id, position) VALUES (?, ?, ?, ?)`,
      [uuidFactory(), activityId, item.assetId, position],
    );
  }
}

import type { Profile, ProfileDurationSetting } from "@/domain/preferences/Profile";
import type {
  ProfileIdentityInput,
  ProfilePreference,
  ProfileRepository,
} from "@/domain/preferences/ProfileRepository";
import { LOCAL_PROFILE_SINGLETON_KEY } from "@/infrastructure/database/constants";
import type { Database } from "@/infrastructure/database/Database";
import type { ProfileRow } from "@/infrastructure/database/types/DatabaseRows";

const SELECT_COLUMNS = `
  singleton_key, side_change_recovery_seconds_default, post_activity_recovery_seconds_default,
  exercise_countdown_seconds_default, exercise_end_seconds_default,
  session_initial_countdown_seconds_default, session_final_phase_seconds_default,
  sounds_enabled, voice_announcements_enabled, vibration_enabled, notifications_enabled,
  display_name, photo_uri, silhouette, updated_at
`;

/** Colonne SQL de chaque réglage de durée — jamais une concaténation de nom d'origine utilisateur (clé fermée, `ProfileDurationSetting`). */
const DURATION_SETTING_COLUMNS: Readonly<Record<ProfileDurationSetting, string>> = {
  sideChangeRecoverySecondsDefault: "side_change_recovery_seconds_default",
  postActivityRecoverySecondsDefault: "post_activity_recovery_seconds_default",
  exerciseCountdownSecondsDefault: "exercise_countdown_seconds_default",
  exerciseEndSecondsDefault: "exercise_end_seconds_default",
  sessionInitialCountdownSecondsDefault: "session_initial_countdown_seconds_default",
  sessionFinalPhaseSecondsDefault: "session_final_phase_seconds_default",
};

/** Colonne SQL de chaque préférence — même garde que ci-dessus. */
const PREFERENCE_COLUMNS: Readonly<Record<ProfilePreference, string>> = {
  soundsEnabled: "sounds_enabled",
  voiceAnnouncementsEnabled: "voice_announcements_enabled",
  vibrationEnabled: "vibration_enabled",
  notificationsEnabled: "notifications_enabled",
};

/**
 * Lecture et mise à jour du Profil singleton (V2-PRE-1, plan §3.2,
 * `migration007` ; V2-PRE-2, plan §6.1/§6.3, `migration008`). La ligne
 * unique est semée par `migration007` — jamais `null` après initialisation.
 * Chaque opération d'écriture est une seule instruction `UPDATE` ciblée (une
 * seule colonne pour `updateDefault`/`updatePreference`, trois pour
 * `updateIdentity`) : les autres réglages restent inchangés par
 * construction, sans lecture-modification-écriture séparée.
 */
export class SqliteProfileRepository implements ProfileRepository {
  constructor(
    private readonly database: Database,
    private readonly now: () => string = () => new Date().toISOString(),
  ) {}

  async get(): Promise<Profile> {
    const row = await this.database.getFirstAsync<ProfileRow>(
      `SELECT ${SELECT_COLUMNS} FROM profiles WHERE singleton_key = ?`,
      [LOCAL_PROFILE_SINGLETON_KEY],
    );
    if (!row) {
      throw new Error("The singleton Profile row is missing — migration007 did not run.");
    }
    return mapProfileRow(row);
  }

  async updateDefault(setting: ProfileDurationSetting, value: number): Promise<Profile> {
    const column = DURATION_SETTING_COLUMNS[setting];
    const timestamp = this.now();
    await this.database.runAsync(
      `UPDATE profiles SET ${column} = ?, updated_at = ? WHERE singleton_key = ?`,
      [value, timestamp, LOCAL_PROFILE_SINGLETON_KEY],
    );
    return this.get();
  }

  async updatePreference(preference: ProfilePreference, value: boolean): Promise<Profile> {
    const column = PREFERENCE_COLUMNS[preference];
    const timestamp = this.now();
    await this.database.runAsync(
      `UPDATE profiles SET ${column} = ?, updated_at = ? WHERE singleton_key = ?`,
      [value ? 1 : 0, timestamp, LOCAL_PROFILE_SINGLETON_KEY],
    );
    return this.get();
  }

  async updateIdentity(input: ProfileIdentityInput): Promise<Profile> {
    const timestamp = this.now();
    await this.database.runAsync(
      `UPDATE profiles SET display_name = ?, photo_uri = ?, silhouette = ?, updated_at = ? WHERE singleton_key = ?`,
      [input.displayName, input.photoUri, input.silhouette, timestamp, LOCAL_PROFILE_SINGLETON_KEY],
    );
    return this.get();
  }
}

export function mapProfileRow(row: ProfileRow): Profile {
  return {
    id: String(row.singleton_key),
    sideChangeRecoverySecondsDefault: row.side_change_recovery_seconds_default,
    postActivityRecoverySecondsDefault: row.post_activity_recovery_seconds_default,
    exerciseCountdownSecondsDefault: row.exercise_countdown_seconds_default,
    exerciseEndSecondsDefault: row.exercise_end_seconds_default,
    sessionInitialCountdownSecondsDefault: row.session_initial_countdown_seconds_default,
    sessionFinalPhaseSecondsDefault: row.session_final_phase_seconds_default,
    soundsEnabled: row.sounds_enabled === 1,
    voiceAnnouncementsEnabled: row.voice_announcements_enabled === 1,
    vibrationEnabled: row.vibration_enabled === 1,
    notificationsEnabled: row.notifications_enabled === 1,
    displayName: row.display_name,
    photoUri: row.photo_uri,
    silhouette: row.silhouette,
    updatedAt: row.updated_at,
  };
}

